package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMinShard       = lnwire.MilliSatoshi(5_000_000)
	candidateRiskCost       = 2_000_000.0
	candidateHopCost        = 25_000.0
	candidateFailureCost    = 8_000_000.0
	candidateReservedCost   = 2_000_000.0
	candidateEvidenceLife   = 10 * time.Minute
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateGlobalBelief struct {
	quality float64
	updated time.Time
}

var candidateKnowledge = struct {
	sync.Mutex

	beliefs     map[candidateEdgeKey]candidateGlobalBelief
	lastViewNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]candidateGlobalBelief),
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from     route.Vertex
	to       route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateRouter struct {
	view   routing.SimNetworkView
	now    time.Time
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localReserved map[uint64]lnwire.MilliSatoshi

	// lowerOK records amounts recently proven to traverse a channel.
	lowerOK map[candidateEdgeKey]lnwire.MilliSatoshi

	// upperFail records amounts that failed during the current payment.
	// Amounts at or above this bound are excluded, while smaller retries
	// remain available.
	upperFail map[candidateEdgeKey]lnwire.MilliSatoshi

	quality      map[candidateEdgeKey]float64
	failures     map[candidateEdgeKey]uint32
	policyBad    map[candidateEdgeKey]bool
	inUse        map[candidateEdgeKey]uint32
	currentShard lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	now := view.Now()
	r := &candidateRouter{
		view:          view,
		now:           now,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		localReserved: make(map[uint64]lnwire.MilliSatoshi),
		lowerOK:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		upperFail:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		quality:       make(map[candidateEdgeKey]float64),
		failures:      make(map[candidateEdgeKey]uint32),
		policyBad:     make(map[candidateEdgeKey]bool),
		inUse:         make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				edge := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.loadBeliefs(now)

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.currentShard = divideCandidateAmount(spec.Amount, parts)
	if r.currentShard < candidateMinShard {
		r.currentShard = candidateMinShard
	}
	if r.currentShard > spec.Amount {
		r.currentShard = spec.Amount
	}

	return r, nil
}

func divideCandidateAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) loadBeliefs(now time.Time) {
	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	if !candidateKnowledge.lastViewNow.IsZero() &&
		now.Before(candidateKnowledge.lastViewNow) {

		candidateKnowledge.beliefs =
			make(map[candidateEdgeKey]candidateGlobalBelief)
	}
	candidateKnowledge.lastViewNow = now

	for key := range r.edges {
		belief, ok := candidateKnowledge.beliefs[key]
		if !ok {
			continue
		}

		age := now.Sub(belief.updated)
		if age < 0 {
			continue
		}

		decay := math.Exp(
			-float64(age) / float64(candidateEvidenceLife),
		)
		r.quality[key] = belief.quality * decay
	}
}

func (r *candidateRouter) updateQuality(key candidateEdgeKey,
	delta float64) {

	value := r.quality[key] + delta
	if value > 6 {
		value = 6
	}
	if value < -6 {
		value = -6
	}
	r.quality[key] = value

	now := r.view.Now()

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	if !candidateKnowledge.lastViewNow.IsZero() &&
		now.Before(candidateKnowledge.lastViewNow) {

		candidateKnowledge.beliefs =
			make(map[candidateEdgeKey]candidateGlobalBelief)
	}
	candidateKnowledge.lastViewNow = now

	old := candidateKnowledge.beliefs[key]
	if !old.updated.IsZero() {
		age := now.Sub(old.updated)
		if age >= 0 {
			old.quality *= math.Exp(
				-float64(age) /
					float64(candidateEvidenceLife),
			)
		} else {
			old.quality = 0
		}
	}

	old.quality += delta
	if old.quality > 6 {
		old.quality = 6
	}
	if old.quality < -6 {
		old.quality = -6
	}
	old.updated = now
	candidateKnowledge.beliefs[key] = old
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.001
	}

	x := float64(amt) / float64(capacity)

	// The first term models the nearly empty mode. The second models the
	// nearly full mode and its capacity cliff.
	lowMode := 0.48 * math.Exp(-x/0.018)
	highMode := 0.50 / (1 + math.Exp((x-0.92)/0.035))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if lower := r.lowerOK[edge.key]; lower >= amt {
		return 0.995
	}

	p := candidatePrior(amt, edge.capacity)
	logOdds := math.Log(p/(1-p)) + r.quality[edge.key]
	p = 1 / (1 + math.Exp(-logOdds))

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

type candidatePathState struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type candidatePathQueue []*candidatePathState

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidatePathQueue) Push(value any) {
	*q = append(*q, value.(*candidatePathState))
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	value := old[last]
	*q = old[:last]

	return value
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	bestScore := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	bestAmount := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &candidatePathQueue{}
	heap.Push(pq, &candidatePathState{
		node:   r.spec.Target,
		amount: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidatePathState)
		knownScore, ok := bestScore[item.node]
		if !ok || item.score > knownScore+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOver := item.amount

			if !edge.usable(amountOver) ||
				r.policyBad[edge.key] {

				continue
			}

			if upper := r.upperFail[edge.key]; upper != 0 &&
				amountOver >= upper {

				continue
			}

			if edge.from == r.source {
				available := r.localBalances[edge.chanID] -
					r.localReserved[edge.chanID]
				if available < amountOver {
					continue
				}
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(amountOver)
				sending += fee
			}

			probability := r.edgeProbability(edge, amountOver)
			edgeScore := float64(fee) + candidateHopCost -
				candidateRiskCost*math.Log(probability)

			edgeScore += float64(r.failures[edge.key]) *
				candidateFailureCost
			edgeScore += float64(r.inUse[edge.key]) *
				candidateReservedCost

			score := item.score + edgeScore
			oldScore, ok := bestScore[edge.from]
			if ok && score >= oldScore {
				continue
			}

			bestScore[edge.from] = score
			bestAmount[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidatePathState{
				node:   edge.from,
				amount: sending,
				score:  score,
			})
		}
	}

	if _, ok := bestAmount[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("source is payment target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteEdges(rt *route.Route) []candidateEdgeKey {
	keys := make([]candidateEdgeKey, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		from = hop.PubKeyBytes
	}

	return keys
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)
	for _, key := range keys {
		r.inUse[key]++
	}

	if len(rt.Hops) != 0 {
		r.localReserved[rt.Hops[0].ChannelID] += rt.TotalAmount
	}
}

func (r *candidateRouter) releaseRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)
	for _, key := range keys {
		if r.inUse[key] > 0 {
			r.inUse[key]--
		}
	}

	if len(rt.Hops) != 0 {
		chanID := rt.Hops[0].ChannelID
		reserved := r.localReserved[chanID]
		if reserved <= rt.TotalAmount {
			delete(r.localReserved, chanID)
		} else {
			r.localReserved[chanID] = reserved - rt.TotalAmount
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	shard := r.currentShard
	if shard == 0 || shard > amt {
		shard = amt
	}

	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.reserveRoute(rt)
			return rt, nil
		}

		if shard <= candidateMinShard {
			return nil, err
		}

		nextShard := shard * 3 / 5
		if nextShard < candidateMinShard {
			nextShard = candidateMinShard
		}
		if nextShard >= shard {
			return nil, err
		}

		shard = nextShard
		r.currentShard = shard
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordPassingPrefix(rt *route.Route,
	count int) {

	keys := candidateRouteEdges(rt)
	if count > len(keys) {
		count = len(keys)
	}

	for i := 0; i < count; i++ {
		amount := candidateRouteAmount(rt, i)
		if amount > r.lowerOK[keys[i]] {
			r.lowerOK[keys[i]] = amount
		}

		r.updateQuality(keys[i], 0.35)
	}
}

func (r *candidateRouter) recordSettledRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)

	for i, key := range keys {
		amount := candidateRouteAmount(rt, i)

		if lower := r.lowerOK[key]; lower != 0 {
			if lower <= amount {
				delete(r.lowerOK, key)
			} else {
				r.lowerOK[key] = lower - amount
			}
		}

		if upper := r.upperFail[key]; upper != 0 {
			if upper <= amount {
				r.upperFail[key] = 1
			} else {
				r.upperFail[key] = upper - amount
			}
		}

		edge := r.edges[key]
		delta := 0.8
		if edge != nil && edge.capacity > 0 {
			fraction := float64(amount) /
				float64(edge.capacity)
			delta = 1.3 - 2.5*fraction
			if delta < -0.5 {
				delta = -0.5
			}
		}
		r.updateQuality(key, delta)

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   rt.Hops[i].PubKeyBytes,
		}
		if _, ok := r.edges[reverse]; ok {
			r.updateQuality(reverse, 0.7)
		}
	}

	if len(rt.Hops) != 0 {
		chanID := rt.Hops[0].ChannelID
		balance := r.localBalances[chanID]
		if balance <= rt.TotalAmount {
			r.localBalances[chanID] = 0
		} else {
			r.localBalances[chanID] =
				balance - rt.TotalAmount
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.releaseRoute(rt)

	if result.Failure == nil {
		r.recordSettledRoute(rt)
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	keys := candidateRouteEdges(rt)

	if failIndex < 0 {
		for _, key := range keys {
			r.failures[key]++
			r.updateQuality(key, -0.15)
		}
		return nil
	}

	r.recordPassingPrefix(rt, failIndex)

	if failIndex >= len(keys) {
		return nil
	}

	key := keys[failIndex]
	amount := candidateRouteAmount(rt, failIndex)

	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		upper, ok := r.upperFail[key]
		if !ok || amount < upper {
			r.upperFail[key] = amount
		}
		r.failures[key]++
		r.updateQuality(key, -2.4)

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		r.policyBad[key] = true
		r.failures[key] += 2
		r.updateQuality(key, -1.0)

	default:
		r.failures[key]++
		r.updateQuality(key, -0.5)
	}

	return nil
}

