package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	minShardAmt    = lnwire.MilliSatoshi(5_000_000)
	riskCostMsat   = 5_000_000.0
	hopCostMsat    = 2_000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	confidence float64
	failCount uint32
	updated   time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs    map[edgeKey]liquidityBelief
	policyBad  map[edgeKey]bool
	penalties  map[edgeKey]float64
	shardAmt   lnwire.MilliSatoshi
	lastShard  lnwire.MilliSatoshi
	shardFails uint32
	failures   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balances[chanID] = balance
	}

	router := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: balances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		policyBad:     make(map[edgeKey]bool),
		penalties:     make(map[edgeKey]float64),
		shardAmt:      spec.Amount,
	}

	now := view.Now()

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if !belief.updated.IsZero() && !now.Before(belief.updated) {
			router.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.edges[key] = edge
				router.incomingEdges[node] = append(
					router.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func clampProbability(probability float64) float64 {
	switch {
	case probability < 0.005:
		return 0.005
	case probability > 0.995:
		return 0.995
	default:
		return probability
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode models nearly depleted channels. The high mode models
	// channels whose balance remains close to their full capacity.
	lowMode := math.Exp(-ratio / 0.025)
	highMode := 1 / (1 + math.Exp((ratio-0.88)/0.055))

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0.005
		}

		return 0.995
	}

	prior := bimodalPrior(amt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.confidence <= 0 {
		return prior
	}

	now := r.view.Now()
	if now.Before(belief.updated) {
		return prior
	}

	ageMinutes := now.Sub(belief.updated).Minutes()
	freshness := math.Exp(-ageMinutes / 12)
	weight := belief.confidence * freshness
	if weight < 0.02 {
		return prior
	}
	if weight > 0.95 {
		weight = 0.95
	}

	learned := prior
	switch {
	case belief.lowerOK > 0 && amt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && amt >= belief.upperFail:
		learned = 0.005

	case belief.upperFail > 0:
		estimate := belief.estimate
		if estimate <= 0 {
			estimate = belief.upperFail / 4
		}

		scale := float64(belief.upperFail) * 0.12
		if scale < 1_000_000 {
			scale = 1_000_000
		}

		z := (float64(amt) - float64(estimate)) / scale
		learned = 0.005 + 0.99/(1+math.Exp(z))

	case belief.estimate > 0:
		scale := float64(belief.estimate) * 0.15
		if scale < 1_000_000 {
			scale = 1_000_000
		}

		z := (float64(amt) - float64(belief.estimate)) / scale
		learned = 0.005 + 0.99/(1+math.Exp(z))
	}

	probability := (1-weight)*prior + weight*learned

	if belief.upperFail > 0 && amt >= belief.upperFail {
		count := belief.failCount
		if count > 3 {
			count = 3
		}
		probability *= math.Pow(0.12, float64(count))
	}

	return clampProbability(probability)
}

type pathItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	index  int
}

type pathQueue []*pathItem

func (q pathQueue) Len() int {
	return len(q)
}

func (q pathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *pathQueue) Push(value any) {
	item := value.(*pathItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *pathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	bestScore := make(map[route.Vertex]float64)
	requiredAmt := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	requiredAmt[r.spec.Target] = amt

	queue := &pathQueue{}
	heap.Push(queue, &pathItem{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
	})

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*pathItem)
		best, ok := bestScore[item.node]
		if !ok || item.score > best+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] || !edge.usable(item.amount) {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < item.amount {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			probability := r.edgeProbability(edge, item.amount)
			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				hopCostMsat + r.penalties[edge.key]*riskCostMsat

			previous, exists := bestScore[edge.key.from]
			if exists && score >= previous {
				continue
			}

			bestScore[edge.key.from] = score
			requiredAmt[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &pathItem{
				node:   edge.key.from,
				amount: sending,
				score:  score,
			})
		}
	}

	if _, ok := requiredAmt[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("source is payment target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func reducedShard(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	reduced := amt * 3 / 5
	if reduced >= amt {
		reduced = amt - 1
	}

	return reduced
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts > 0 && inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}
	if r.failures >= 64 {
		return nil, errors.New("attempt budget exhausted")
	}

	if r.shardAmt <= 0 || r.shardAmt > amt {
		r.shardAmt = amt
	}

	for r.shardAmt >= minShardAmt || r.shardAmt == amt {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			r.lastShard = r.shardAmt
			return rt, nil
		}

		if r.shardAmt <= minShardAmt {
			return nil, err
		}

		r.shardAmt = reducedShard(r.shardAmt)
		if r.shardAmt < minShardAmt {
			r.shardAmt = minShardAmt
		}
		if r.shardAmt > amt {
			r.shardAmt = amt
		}
	}

	return nil, errors.New("no route found")
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func routeEdgeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) saveBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
		belief.failCount = 0
	}

	estimate := amt + amt/5
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.confidence = math.Min(0.95, belief.confidence+0.32)
	belief.updated = r.view.Now()
	belief.failCount = 0
	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = amt / 3
	}

	estimate := amt / 4
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.confidence = math.Min(0.95, belief.confidence+0.48)
	belief.updated = r.view.Now()
	belief.failCount++
	r.saveBelief(key, belief)
}

func (r *candidateRouter) successfulPrefix(rt *route.Route,
	count int) {

	if count > len(rt.Hops) {
		count = len(rt.Hops)
	}

	for i := 0; i < count; i++ {
		r.recordSuccess(
			routeEdgeKey(rt, i), routeEdgeAmount(rt, i),
		)
	}
}

func (r *candidateRouter) failureEdgeIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return nil
	}

	if result.Failure == nil {
		r.successfulPrefix(rt, len(rt.Hops))

		if len(rt.Hops) > 0 {
			firstChan := rt.Hops[0].ChannelID
			spent := rt.TotalAmount
			if balance := r.localBalances[firstChan]; balance >= spent {
				r.localBalances[firstChan] = balance - spent
			} else {
				r.localBalances[firstChan] = 0
			}
		}

		r.shardFails = 0
		if r.lastShard > 0 {
			r.shardAmt = r.lastShard
		}

		return nil
	}

	r.failures++
	failIndex := r.failureEdgeIndex(rt, result.FailureSource)

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		if failIndex >= 0 && failIndex < len(rt.Hops) {
			r.successfulPrefix(rt, failIndex)

			key := routeEdgeKey(rt, failIndex)
			amount := routeEdgeAmount(rt, failIndex)
			r.recordFailure(key, amount)
			r.penalties[key] += 1.5
		} else {
			for i := range rt.Hops {
				r.penalties[routeEdgeKey(rt, i)] += 0.18
			}
		}

		r.shardFails++
		if r.shardFails >= 2 && r.shardAmt > minShardAmt {
			r.shardAmt = reducedShard(r.shardAmt)
			if r.shardAmt < minShardAmt {
				r.shardAmt = minShardAmt
			}
			r.shardFails = 0
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if failIndex >= 0 && failIndex < len(rt.Hops) {
			r.successfulPrefix(rt, failIndex)
			r.policyBad[routeEdgeKey(rt, failIndex)] = true
		} else {
			for i := range rt.Hops {
				r.penalties[routeEdgeKey(rt, i)] += 0.3
			}
		}

	default:
		for i := range rt.Hops {
			r.penalties[routeEdgeKey(rt, i)] += 0.12
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = uint32(40)
	minProbability    = 0.005
	maxProbability    = 0.995
	lowerRetryFactor  = 0.55
	globalHalfLifeMin = 20.0
	maxAttempts       = 48
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	confidence float64
	updatedAt time.Time
}

var sharedCandidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]liquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localBeliefs map[candidateEdgeKey]liquidityBelief
	edgePenalty  map[candidateEdgeKey]float64
	policyBad    map[candidateEdgeKey]bool

	retryMax lnwire.MilliSatoshi
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localBeliefs:  make(map[candidateEdgeKey]liquidityBelief),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	// The low mode makes very small transfers nearly certain, while the
	// high mode retains roughly one-half probability through the middle
	// of a channel and falls sharply near full capacity.
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.88)/0.07))

	return clampProbability(lowMode + highMode)
}

func learnedProbability(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return maxProbability
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		return minProbability
	}

	estimate := b.estimate
	if estimate <= 0 {
		estimate = capacity / 2
	}

	width := math.Max(float64(capacity)*0.075, 1)
	x := (float64(amt) - float64(estimate)) / width

	return clampProbability(1 / (1 + math.Exp(x)))
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] >= amt {
			return maxProbability
		}

		return minProbability
	}

	prior := bimodalPrior(amt, edge.capacity)

	if local, ok := r.localBeliefs[edge.key]; ok {
		learned := learnedProbability(local, amt, edge.capacity)
		confidence := math.Min(0.97, local.confidence)

		return clampProbability(
			confidence*learned + (1-confidence)*prior,
		)
	}

	sharedCandidateKnowledge.RLock()
	global, ok := sharedCandidateKnowledge.beliefs[edge.key]
	sharedCandidateKnowledge.RUnlock()
	if !ok {
		return prior
	}

	ageMinutes := r.view.Now().Sub(global.updatedAt).Minutes()
	if ageMinutes < 0 {
		ageMinutes = 0
	}

	// Evidence from earlier payments is deliberately soft. This preserves
	// useful batch knowledge while allowing background traffic to invalidate
	// old liquidity observations.
	decay := math.Exp(
		-math.Ln2 * ageMinutes / globalHalfLifeMin,
	)
	confidence := math.Min(0.88, global.confidence*decay)
	if confidence < 0.03 {
		return prior
	}

	learned := learnedProbability(global, amt, edge.capacity)

	return clampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

func updateSuccessfulBelief(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	// Under a bimodal balance model, passing an HTLC is evidence that this
	// direction is in the channel's high-liquidity mode.
	highEstimate := lnwire.MilliSatoshi(
		0.88 * float64(capacity),
	)
	if highEstimate < amt {
		highEstimate = amt
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}

	b.confidence = math.Min(0.98, b.confidence+0.38)
	b.updatedAt = now

	return b
}

func updateFailedBelief(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}

	// A directional failure is evidence for the depleted mode, not merely
	// evidence that the balance lies uniformly below the attempted amount.
	lowEstimate := lnwire.MilliSatoshi(
		math.Min(
			float64(amt)*0.25,
			float64(capacity)*0.08,
		),
	)
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.confidence = math.Min(0.98, b.confidence+0.48)
	b.updatedAt = now

	return b
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := updateSuccessfulBelief(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.localBeliefs[key] = local

	sharedCandidateKnowledge.Lock()
	global := sharedCandidateKnowledge.beliefs[key]
	global = updateSuccessfulBelief(
		global, amt, edge.capacity, now,
	)
	sharedCandidateKnowledge.beliefs[key] = global
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.35
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := updateFailedBelief(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.localBeliefs[key] = local

	sharedCandidateKnowledge.Lock()
	global := sharedCandidateKnowledge.beliefs[key]
	global = updateFailedBelief(
		global, amt, edge.capacity, now,
	)
	sharedCandidateKnowledge.beliefs[key] = global
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] += 1.25
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	feeScale := math.Max(float64(amt), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		best, ok := bestScore[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] || !edge.usable(item.amount) {
				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < item.amount {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			probability := r.edgeProbability(edge, item.amount)
			riskCost := -math.Log(probability)
			feeCost := 2 * float64(fee) / feeScale
			hopCost := 0.012
			score := item.score + riskCost + feeCost + hopCost +
				r.edgePenalty[edge.key]

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists && (score > oldScore+1e-12 ||
				(math.Abs(score-oldScore) <= 1e-12 &&
					sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:   edge.key.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func ceilDivAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)

	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is already satisfied")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := ceilDivAmount(amt, partsLeft)

	shard := amt
	if r.retryMax > 0 && r.retryMax < shard {
		shard = r.retryMax
	}
	if shard < minimumShard {
		shard = minimumShard
	}

	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.attempts++
			return rt, nil
		}

		if shard <= minimumShard {
			return nil, err
		}

		nextShard := lnwire.MilliSatoshi(
			float64(shard) * lowerRetryFactor,
		)
		if nextShard < minimumShard {
			nextShard = minimumShard
		}
		if nextShard >= shard {
			return nil, err
		}

		shard = nextShard
		r.retryMax = shard
	}
}

func routeEdgeData(rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func failureClass(failure any) (liquidity, policy bool) {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true, false

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return false, true

	default:
		return false, false
	}
}

func failingEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	keys, amounts := routeEdgeData(rt)
	if len(keys) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range keys {
			r.recordSuccess(keys[i], amounts[i])
		}

		r.retryMax = 0
		return nil
	}

	liquidityFailure, policyFailure := failureClass(result.Failure)
	failIdx := failingEdgeIndex(rt, result.FailureSource)

	if failIdx >= 0 {
		// Every preceding channel successfully carried this attempt to the
		// node that reported the failure.
		for i := 0; i < failIdx && i < len(keys); i++ {
			r.recordSuccess(keys[i], amounts[i])
		}
	}

	switch {
	case liquidityFailure && failIdx >= 0 && failIdx < len(keys):
		r.recordFailure(keys[failIdx], amounts[failIdx])

	case liquidityFailure && failIdx < 0 && len(keys) == 1:
		// A source-less failure on a direct route can only concern its
		// single channel.
		r.recordFailure(keys[0], amounts[0])

	case liquidityFailure:
		// When the simulator cannot identify the failing node, diversify
		// away from every uncertain edge without inventing hard bounds.
		for i, key := range keys {
			if i == 0 && key.from == r.source {
				continue
			}
			r.edgePenalty[key] += 0.32
		}

	case policyFailure && failIdx >= 0 && failIdx < len(keys):
		r.policyBad[keys[failIdx]] = true
		r.edgePenalty[keys[failIdx]] += 8

	default:
		for _, key := range keys {
			r.edgePenalty[key] += 0.18
		}
	}

	if liquidityFailure {
		failedAmount := rt.Hops[len(rt.Hops)-1].AmtToForward
		next := lnwire.MilliSatoshi(
			float64(failedAmount) * lowerRetryFactor,
		)
		if next <= 0 {
			next = 1
		}
		if r.retryMax == 0 || next < r.retryMax {
			r.retryMax = next
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	capacity lnwire.MilliSatoshi

	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	estimate    lnwire.MilliSatoshi
	hasEstimate bool
	evidence    float64
	updated     time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	networks map[uint64]map[candidateEdgeKey]*liquidityBelief
}{
	networks: make(map[uint64]map[candidateEdgeKey]*liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	networkID     uint64

	policyBad map[candidateEdgeKey]bool
	edgeUses  map[candidateEdgeKey]uint32

	shardTarget lnwire.MilliSatoshi
	partsUsed   uint32

	attemptsSinceSettle uint32
	unknownFailures     uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balances[chanID] = balance
	}

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: balances,
		policyBad:     make(map[candidateEdgeKey]bool),
		edgeUses:      make(map[candidateEdgeKey]uint32),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				r.networkID += edgeFingerprint(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	initialParts := maxParts
	if initialParts > 4 {
		initialParts = 4
	}
	r.shardTarget = ceilDivide(spec.Amount, initialParts)

	return r, nil
}

func edgeFingerprint(edge *candidateEdge) uint64 {
	x := edge.key.chanID + 0x9e3779b97f4a7c15
	for i := 0; i < len(edge.key.from); i++ {
		x ^= uint64(edge.key.from[i]) + 0x9e3779b97f4a7c15 +
			(x << 6) + (x >> 2)
		x ^= uint64(edge.key.to[i]) + 0x517cc1b727220a95 +
			(x << 6) + (x >> 2)
	}

	x ^= uint64(edge.capacity) + 0x94d049bb133111eb
	x ^= uint64(edge.timeLockDelta) << 32
	return x
}

func ceilDivide(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp((x-0.92)/0.055))

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) beliefProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, edge.capacity)

	sharedBeliefs.Lock()
	network := sharedBeliefs.networks[r.networkID]
	var snapshot liquidityBelief
	var found bool
	if network != nil {
		belief := network[edge.key]
		if belief != nil {
			snapshot = *belief
			found = true
		}
	}
	sharedBeliefs.Unlock()

	if !found || snapshot.evidence == 0 {
		return prior
	}

	age := r.view.Now().Sub(snapshot.updated)
	if age < 0 {
		age = 0
	}

	ageWeight := math.Exp(-float64(age) / float64(45*time.Minute))
	evidenceWeight := 1 - math.Exp(-0.85*snapshot.evidence)
	confidence := ageWeight * evidenceWeight
	if confidence < 0.01 {
		return prior
	}

	target := prior
	switch {
	case snapshot.lowerOK > 0 && amt <= snapshot.lowerOK:
		target = 0.995

	case snapshot.upperFail > 0 && amt >= snapshot.upperFail:
		target = 0.005

	case snapshot.hasEstimate:
		width := math.Max(
			float64(edge.capacity)*0.10,
			5_000_000,
		)
		estimateProbability := 1 / (1 + math.Exp(
			(float64(amt)-float64(snapshot.estimate))/width,
		))
		target = 0.35*prior + 0.65*estimateProbability
	}

	return clampProbability(
		prior*(1-confidence) + target*confidence,
	)
}

func (r *candidateRouter) mutateBelief(key candidateEdgeKey,
	capacity lnwire.MilliSatoshi,
	mutate func(*liquidityBelief)) {

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	network := sharedBeliefs.networks[r.networkID]
	if network == nil {
		network = make(map[candidateEdgeKey]*liquidityBelief)
		sharedBeliefs.networks[r.networkID] = network
	}

	belief := network[key]
	if belief == nil {
		belief = &liquidityBelief{capacity: capacity}
		network[key] = belief
	}
	if capacity > 0 {
		belief.capacity = capacity
	}

	mutate(belief)
	belief.updated = r.view.Now()
	if belief.evidence > 12 {
		belief.evidence = 12
	}
}

func (r *candidateRouter) observePass(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	r.mutateBelief(edge.key, edge.capacity, func(b *liquidityBelief) {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperFail > 0 && amt >= b.upperFail {
			b.upperFail = 0
		}

		fundedEstimate := amt +
			lnwire.MilliSatoshi(
				0.72*float64(edge.capacity-amt),
			)
		if !b.hasEstimate || fundedEstimate > b.estimate {
			b.estimate = fundedEstimate
			b.hasEstimate = true
		}
		b.evidence += 1
	})
}

func (r *candidateRouter) observeFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	r.mutateBelief(edge.key, edge.capacity, func(b *liquidityBelief) {
		if b.upperFail == 0 || amt < b.upperFail {
			b.upperFail = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}

		failedEstimate := lnwire.MilliSatoshi(
			0.68 * float64(amt),
		)
		if failedEstimate > edge.capacity {
			failedEstimate = edge.capacity
		}
		if !b.hasEstimate || failedEstimate < b.estimate {
			b.estimate = failedEstimate
			b.hasEstimate = true
		}
		b.evidence += 1.4
	})
}

func (r *candidateRouter) observeSettlement(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	r.mutateBelief(edge.key, edge.capacity, func(b *liquidityBelief) {
		if !b.hasEstimate {
			b.estimate = edge.capacity * 9 / 10
			b.hasEstimate = true
		}
		if b.estimate > amt {
			b.estimate -= amt
		} else {
			b.estimate = 0
		}

		if b.lowerOK > amt {
			b.lowerOK -= amt
		} else {
			b.lowerOK = 0
		}
		if b.upperFail > amt {
			b.upperFail -= amt
		} else {
			b.upperFail = 0
		}
		b.evidence += 0.7
	})

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := r.edges[reverseKey]
	if reverse == nil {
		return
	}

	r.mutateBelief(
		reverseKey, reverse.capacity, func(b *liquidityBelief) {
			if !b.hasEstimate {
				b.estimate = reverse.capacity / 10
				b.hasEstimate = true
			}
			b.estimate += amt
			if b.estimate > reverse.capacity {
				b.estimate = reverse.capacity
			}

			b.lowerOK += amt
			if b.lowerOK > reverse.capacity {
				b.lowerOK = reverse.capacity
			}
			if b.upperFail > 0 {
				b.upperFail += amt
				if b.upperFail > reverse.capacity {
					b.upperFail = 0
				}
			}
			b.evidence += 0.7
		},
	)
}

type dijkstraItem struct {
	node     route.Vertex
	required lnwire.MilliSatoshi
	cost     float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	bestCost := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		currentCost, ok := bestCost[item.node]
		if !ok || item.cost > currentCost+0.001 {
			continue
		}
		if item.required != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] || !edge.usable(item.required) {
				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < item.required {

				continue
			}

			sending := item.required
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.required)
				sending += fee
			}
			if sending <= 0 {
				continue
			}

			probability := 0.999
			if edge.key.from != r.source {
				probability = r.beliefProbability(
					edge, item.required,
				)
			}

			riskScale := 50_000 +
				0.0035*float64(item.required)
			riskCost := -math.Log(probability) * riskScale
			useCost := float64(r.edgeUses[edge.key]) *
				riskScale * 0.16
			hopCost := 2_000.0

			newCost := item.cost + float64(fee) +
				riskCost + useCost + hopCost

			oldCost, seen := bestCost[edge.key.from]
			if seen && newCost >= oldCost {
				continue
			}

			bestCost[edge.key.from] = newCost
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:     edge.key.from,
				required: sending,
				cost:     newCost,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("route contains a cycle")
		}
		seen[node] = true

		edge := next[node]
		if edge == nil {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			nextEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.attemptsSinceSettle >= 120 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	usedParts := r.partsUsed + inFlightHtlcs
	if usedParts >= r.spec.MaxParts && r.spec.MaxParts != 0 {
		return nil, errors.New("maximum payment parts exhausted")
	}

	partsLeft := r.spec.MaxParts - usedParts
	if r.spec.MaxParts == 0 || partsLeft == 0 {
		partsLeft = 1
	}

	minimumShard := ceilDivide(amt, partsLeft)
	shard := r.shardTarget
	if shard <= 0 || shard > amt {
		shard = amt
	}
	if shard < minimumShard {
		shard = minimumShard
	}

	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			for _, edge := range r.routeEdges(rt) {
				r.edgeUses[edge.key]++
			}
			r.attemptsSinceSettle++
			return rt, nil
		}

		if shard <= minimumShard {
			return nil, err
		}

		reduced := lnwire.MilliSatoshi(
			0.72 * float64(shard),
		)
		if reduced < minimumShard {
			reduced = minimumShard
		}
		if reduced == shard {
			return nil, err
		}

		shard = reduced
		r.shardTarget = reduced
	}
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []*candidateEdge {

	edges := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if edge := r.edges[key]; edge != nil {
			edges = append(edges, edge)
		}
		from = hop.PubKeyBytes
	}

	return edges
}

func routeEdgeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	edges := r.routeEdges(rt)
	if len(edges) != len(rt.Hops) {
		return nil
	}

	if result.Failure == nil {
		r.partsUsed++
		r.attemptsSinceSettle = 0
		r.unknownFailures = 0

		for i, edge := range edges {
			amt := routeEdgeAmount(rt, i)
			r.observeSettlement(edge, amt)

			if edge.key.from == r.source {
				balance := r.localBalances[edge.key.chanID]
				if balance > amt {
					r.localBalances[edge.key.chanID] =
						balance - amt
				} else {
					r.localBalances[edge.key.chanID] = 0
				}
			}
		}

		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		if r.shardTarget > delivered {
			r.shardTarget = delivered
		}

		return nil
	}

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	code := result.Failure.Code()

	if failIndex < 0 || failIndex >= len(edges) {
		r.unknownFailures++
		if r.unknownFailures >= 3 {
			delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
			reduced := lnwire.MilliSatoshi(
				0.78 * float64(delivered),
			)
			if reduced > 0 &&
				(r.shardTarget == 0 ||
					reduced < r.shardTarget) {

				r.shardTarget = reduced
			}
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.observePass(edges[i], routeEdgeAmount(rt, i))
	}

	failedEdge := edges[failIndex]
	failedAmount := routeEdgeAmount(rt, failIndex)

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.observeFailure(failedEdge, failedAmount)

		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		reduced := lnwire.MilliSatoshi(
			0.68 * float64(delivered),
		)
		if reduced > 0 &&
			(r.shardTarget == 0 || reduced < r.shardTarget) {

			r.shardTarget = reduced
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[failedEdge.key] = true

	default:
		r.edgeUses[failedEdge.key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	minProbability = 0.005
	maxProbability = 0.985

	evidenceHalfLife = 30 * time.Minute
	minShardAmount   = lnwire.MilliSatoshi(1_000_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK    lnwire.MilliSatoshi
	lowerOKAt  time.Time
	upperFail  lnwire.MilliSatoshi
	upperFailAt time.Time
}

var candidateBeliefs = struct {
	sync.Mutex
	byEdge map[candidateEdgeKey]liquidityBelief
}{
	byEdge: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	reservedLocal map[uint64]lnwire.MilliSatoshi
	reservations  map[*route.Route]localReservation

	pathPenalty map[candidateEdgeKey]float64
	blocked     map[candidateEdgeKey]bool

	shardAmt       lnwire.MilliSatoshi
	lastRemaining  lnwire.MilliSatoshi
	failuresAtSize int
}

type localReservation struct {
	chanID uint64
	amount lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		reservedLocal:  make(map[uint64]lnwire.MilliSatoshi),
		reservations:   make(map[*route.Route]localReservation),
		pathPenalty:    make(map[candidateEdgeKey]float64),
		blocked:        make(map[candidateEdgeKey]bool),
		shardAmt:       spec.Amount,
		lastRemaining:  spec.Amount,
		failuresAtSize: 0,
	}

	for chanID, balance := range localBalances {
		router.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := router.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.edges[key] = edge
				router.incomingEdges[node] = append(
					router.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func clampProbability(probability float64) float64 {
	if probability < minProbability {
		return minProbability
	}
	if probability > maxProbability {
		return maxProbability
	}

	return probability
}

func evidenceConfidence(now, observed time.Time) float64 {
	if observed.IsZero() {
		return 0
	}

	age := now.Sub(observed)
	if age <= 0 {
		return 1
	}

	return math.Exp(
		-math.Ln2 * float64(age) / float64(evidenceHalfLife),
	)
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	fraction := float64(amt) / float64(capacity)

	lowMode := 0.5 * math.Exp(-fraction/0.025)
	highMode := 0.5 / (1 + math.Exp((fraction-0.92)/0.045))

	return clampProbability(lowMode + highMode)
}

func edgeBeliefProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) float64 {

	prior := bimodalPrior(amt, edge.capacity)

	candidateBeliefs.Lock()
	belief, ok := candidateBeliefs.byEdge[edge.key]
	candidateBeliefs.Unlock()
	if !ok {
		return prior
	}

	probability := prior

	if belief.lowerOK > 0 && amt <= belief.lowerOK {
		confidence := evidenceConfidence(now, belief.lowerOKAt)
		probability += confidence * (0.995 - probability)
	}

	if belief.upperFail > 0 && amt >= belief.upperFail {
		confidence := evidenceConfidence(now, belief.upperFailAt)
		probability += confidence * (0.003 - probability)
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		amt > belief.lowerOK && amt < belief.upperFail {

		okConfidence := evidenceConfidence(now, belief.lowerOKAt)
		failConfidence := evidenceConfidence(now, belief.upperFailAt)
		confidence := math.Min(okConfidence, failConfidence)

		position := float64(amt-belief.lowerOK) /
			float64(belief.upperFail-belief.lowerOK)
		bounded := 0.995*(1-position) + 0.003*position
		probability += confidence * (bounded - probability)
	}

	return clampProbability(probability)
}

func recordLiquiditySuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi, now time.Time) {

	candidateBeliefs.Lock()
	defer candidateBeliefs.Unlock()

	belief := candidateBeliefs.byEdge[key]
	if belief.lowerOK == 0 || amt > belief.lowerOK ||
		evidenceConfidence(now, belief.lowerOKAt) < 0.25 {

		belief.lowerOK = amt
		belief.lowerOKAt = now
	}

	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
		belief.upperFailAt = time.Time{}
	}

	candidateBeliefs.byEdge[key] = belief
}

func recordLiquidityFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi, now time.Time) {

	candidateBeliefs.Lock()
	defer candidateBeliefs.Unlock()

	belief := candidateBeliefs.byEdge[key]
	if belief.upperFail == 0 || amt < belief.upperFail ||
		evidenceConfidence(now, belief.upperFailAt) < 0.25 {

		belief.upperFail = amt
		belief.upperFailAt = now
	}

	if belief.lowerOK > 0 && amt <= belief.lowerOK {
		belief.lowerOK = 0
		belief.lowerOKAt = time.Time{}
	}

	candidateBeliefs.byEdge[key] = belief
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) localAvailable(chanID uint64) lnwire.MilliSatoshi {
	balance := r.localBalances[chanID]
	reserved := r.reservedLocal[chanID]
	if reserved >= balance {
		return 0
	}

	return balance - reserved
}

func (r *candidateRouter) edgeCost(edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) float64 {

	probability := edgeBeliefProbability(edge, amt, now)
	riskCost := -math.Log(probability)

	fee := edge.fee(amt)
	feeCost := 0.0
	if amt > 0 {
		feeCost = 50 * float64(fee) / float64(amt)
	}

	capacityBonus := 0.0
	if edge.capacity > 0 {
		fraction := float64(amt) / float64(edge.capacity)
		capacityBonus = 0.04 * fraction
	}

	return riskCost + feeCost + capacityBonus +
		0.025 + r.pathPenalty[edge.key]
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	now := r.view.Now()
	dist := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	required[r.spec.Target] = amt

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] || !edge.usable(arriving) {
				continue
			}

			if edge.key.from == r.source &&
				r.localAvailable(edge.key.chanID) < arriving {

				continue
			}

			sending := arriving
			if edge.key.from != r.source {
				sending += edge.fee(arriving)
			}
			if !edge.usable(arriving) {
				continue
			}

			score := item.score + r.edgeCost(edge, arriving, now)
			previous, found := dist[edge.key.from]
			if found && score >= previous {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:   edge.key.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func ceilDivide(amount lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amount
	}

	value := int64(amount)
	parts := int64(divisor)

	return lnwire.MilliSatoshi((value + parts - 1) / parts)
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	if len(rt.Hops) == 0 {
		return
	}

	chanID := rt.Hops[0].ChannelID
	reservation := localReservation{
		chanID: chanID,
		amount: rt.TotalAmount,
	}

	r.reservations[rt] = reservation
	r.reservedLocal[chanID] += reservation.amount
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	if amt < r.lastRemaining {
		r.failuresAtSize = 0
		if r.shardAmt < amt {
			grown := r.shardAmt + r.shardAmt/4
			if grown > r.shardAmt {
				r.shardAmt = grown
			}
		}
	}
	r.lastRemaining = amt

	if r.shardAmt <= 0 || r.shardAmt > amt {
		r.shardAmt = amt
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimumUseful := minShardAmount
	if inFlightHtlcs > 0 {
		required := ceilDivide(amt, partsLeft)
		if required > minimumUseful {
			minimumUseful = required
		}
	}

	for {
		if r.shardAmt < minimumUseful {
			r.shardAmt = minimumUseful
		}
		if r.shardAmt > amt {
			r.shardAmt = amt
		}

		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			r.reserveRoute(rt)
			return rt, nil
		}

		if r.shardAmt <= minimumUseful {
			return nil, err
		}

		nextAmount := r.shardAmt * 2 / 3
		if nextAmount >= r.shardAmt {
			nextAmount = r.shardAmt - 1
		}
		if nextAmount < minimumUseful {
			nextAmount = minimumUseful
		}

		r.shardAmt = nextAmount
		r.failuresAtSize = 0
	}
}

func routeChannelAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, index int) candidateEdgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func failureOutgoingIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func isTemporaryLiquidityFailure(failure any) bool {
	_, ok := failure.(*lnwire.FailTemporaryChannelFailure)
	return ok
}

func isPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient:
		return true
	case *lnwire.FailIncorrectCltvExpiry:
		return true
	default:
		return false
	}
}

func (r *candidateRouter) releaseReservation(rt *route.Route,
	settled bool) {

	reservation, ok := r.reservations[rt]
	if !ok {
		return
	}
	delete(r.reservations, rt)

	reserved := r.reservedLocal[reservation.chanID]
	if reservation.amount >= reserved {
		delete(r.reservedLocal, reservation.chanID)
	} else {
		r.reservedLocal[reservation.chanID] =
			reserved - reservation.amount
	}

	if !settled {
		return
	}

	balance := r.localBalances[reservation.chanID]
	if reservation.amount >= balance {
		r.localBalances[reservation.chanID] = 0
	} else {
		r.localBalances[reservation.chanID] =
			balance - reservation.amount
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	settled := result.Failure == nil
	r.releaseReservation(rt, settled)

	now := r.view.Now()
	if settled {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			if key.from != r.source {
				recordLiquiditySuccess(
					key, routeChannelAmount(rt, i), now,
				)
			}

			r.pathPenalty[key] *= 0.25
		}

		r.failuresAtSize = 0
		return nil
	}

	failIndex := failureOutgoingIndex(rt, result.FailureSource)

	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key := routeEdgeKey(rt, i)
		if key.from == r.source {
			continue
		}

		recordLiquiditySuccess(
			key, routeChannelAmount(rt, i), now,
		)
	}

	if failIndex >= 0 && failIndex < len(rt.Hops) {
		key := routeEdgeKey(rt, failIndex)

		switch {
		case isTemporaryLiquidityFailure(result.Failure):
			if key.from != r.source {
				recordLiquidityFailure(
					key, routeChannelAmount(rt, failIndex), now,
				)
			}
			r.pathPenalty[key] += 1.5

		case isPolicyFailure(result.Failure):
			r.blocked[key] = true
			r.pathPenalty[key] += 20

		default:
			r.pathPenalty[key] += 4
		}
	} else {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			r.pathPenalty[key] += 0.75
		}
	}

	r.failuresAtSize++
	if r.failuresAtSize >= 2 || failIndex < 0 ||
		isPolicyFailure(result.Failure) {

		nextAmount := r.shardAmt * 2 / 3
		if nextAmount < minShardAmount {
			nextAmount = minShardAmount
		}
		if nextAmount < r.shardAmt {
			r.shardAmt = nextAmount
		}
		r.failuresAtSize = 0
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = uint32(40)
	maxRouteHops    = 20
	maxAttempts     = 72
	riskCostMsat    = 180_000.0
	hopCostMsat     = 750.0
	evidenceHalfLife = int64(20 * 60 * 1_000_000_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	capacity  lnwire.MilliSatoshi
	confidence float64
	updated    int64
}

var sharedLiquidityKnowledge = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]liquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.035)
	highMode := 0.49 / (1 + math.Exp(15*(x-0.84)))

	return clampProbability(0.005 + lowMode + highMode)
}

func agedBelief(key candidateEdgeKey, now int64) (liquidityBelief, bool) {
	sharedLiquidityKnowledge.Lock()
	defer sharedLiquidityKnowledge.Unlock()

	belief, ok := sharedLiquidityKnowledge.beliefs[key]
	if !ok {
		return liquidityBelief{}, false
	}

	age := now - belief.updated
	if age < 0 {
		belief.confidence = 0
	} else if age > 0 {
		belief.confidence *= math.Exp(
			-math.Ln2 * float64(age) / float64(evidenceHalfLife),
		)
	}

	return belief, belief.confidence >= 0.01
}

func channelProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi, now int64) float64 {

	prior := bimodalPrior(amt, edge.capacity)
	belief, ok := agedBelief(edge.key, now)
	if !ok {
		return prior
	}

	confidence := math.Min(0.985, belief.confidence)
	evidence := prior

	switch {
	case belief.lowerOK > 0 && amt <= belief.lowerOK:
		evidence = 0.995

	case belief.upperFail > 0 && amt >= belief.upperFail:
		evidence = 0.005

	case belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		x := float64(amt-belief.lowerOK) / span
		x = math.Max(0, math.Min(1, x))

		boundEstimate := 0.005 + 0.99*math.Pow(1-x, 1.45)
		evidence = boundEstimate

		if belief.estimate > 0 && belief.capacity > 0 {
			width := math.Max(
				float64(belief.capacity)*0.10,
				float64(belief.upperFail-belief.lowerOK)*0.20,
			)
			pointEstimate := 0.005 + 0.99/(1+math.Exp(
				(float64(amt-belief.estimate))/width,
			))
			evidence = 0.65*boundEstimate + 0.35*pointEstimate
		}

	case belief.estimate > 0 && belief.capacity > 0:
		width := math.Max(1, float64(belief.capacity)*0.12)
		evidence = 0.005 + 0.99/(1+math.Exp(
			(float64(amt-belief.estimate))/width,
		))
	}

	return clampProbability(
		(1-confidence)*prior + confidence*evidence,
	)
}

func decayStoredBelief(belief liquidityBelief, now int64) liquidityBelief {
	age := now - belief.updated
	if age < 0 {
		return liquidityBelief{}
	}
	if age > 0 {
		belief.confidence *= math.Exp(
			-math.Ln2 * float64(age) / float64(evidenceHalfLife),
		)
	}
	if belief.confidence < 0.03 {
		return liquidityBelief{}
	}

	return belief
}

func recordPass(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now int64) {

	sharedLiquidityKnowledge.Lock()
	defer sharedLiquidityKnowledge.Unlock()

	belief := decayStoredBelief(
		sharedLiquidityKnowledge.beliefs[key], now,
	)
	belief.capacity = capacity

	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}

	belief.confidence = math.Min(0.985, belief.confidence+0.48)
	belief.updated = now
	sharedLiquidityKnowledge.beliefs[key] = belief
}

func recordFailure(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now int64) {

	sharedLiquidityKnowledge.Lock()
	defer sharedLiquidityKnowledge.Unlock()

	belief := decayStoredBelief(
		sharedLiquidityKnowledge.beliefs[key], now,
	)
	belief.capacity = capacity

	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 4
	if belief.estimate == 0 || depletedEstimate < belief.estimate {
		belief.estimate = depletedEstimate
	}

	belief.confidence = math.Min(0.985, belief.confidence+0.62)
	belief.updated = now
	sharedLiquidityKnowledge.beliefs[key] = belief
}

func recordSettlement(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now int64) {

	sharedLiquidityKnowledge.Lock()
	defer sharedLiquidityKnowledge.Unlock()

	forward := decayStoredBelief(
		sharedLiquidityKnowledge.beliefs[key], now,
	)
	forward.capacity = capacity

	preSettlementEstimate := forward.estimate
	if preSettlementEstimate < amt {
		preSettlementEstimate = amt
	}
	highModeEstimate := lnwire.MilliSatoshi(
		float64(capacity) * 0.90,
	)
	if preSettlementEstimate < highModeEstimate {
		preSettlementEstimate = highModeEstimate
	}

	if preSettlementEstimate > amt {
		forward.estimate = preSettlementEstimate - amt
	} else {
		forward.estimate = 0
	}
	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}
	if forward.upperFail > amt {
		forward.upperFail -= amt
	} else {
		forward.upperFail = 0
	}

	forward.confidence = math.Min(0.985, forward.confidence+0.52)
	forward.updated = now
	sharedLiquidityKnowledge.beliefs[key] = forward

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverse := decayStoredBelief(
		sharedLiquidityKnowledge.beliefs[reverseKey], now,
	)
	reverse.capacity = capacity
	reverse.lowerOK += amt
	if reverse.lowerOK > capacity {
		reverse.lowerOK = capacity
	}
	reverse.estimate += amt
	if reverse.estimate > capacity {
		reverse.estimate = capacity
	}
	if reverse.upperFail > 0 && reverse.upperFail <= reverse.lowerOK {
		reverse.upperFail = 0
	}
	reverse.confidence = math.Min(0.985, reverse.confidence+0.35)
	reverse.updated = now
	sharedLiquidityKnowledge.beliefs[reverseKey] = reverse
}

type transientFailure struct {
	amount lnwire.MilliSatoshi
	count  int
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	failures     map[candidateEdgeKey]transientFailure
	policyBanned map[candidateEdgeKey]bool
	shardLimit   lnwire.MilliSatoshi
	attempts     int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		failures:       make(map[candidateEdgeKey]transientFailure),
		policyBanned:   make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[node] = append(
					router.incomingEdges[node], edge,
				)
				router.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

type pathItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int
	index  int
}

type pathQueue []*pathItem

func (q pathQueue) Len() int {
	return len(q)
}

func (q pathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *pathQueue) Push(value any) {
	item := value.(*pathItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *pathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) edgePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	failure, ok := r.failures[edge.key]
	if !ok || failure.count == 0 {
		return 0
	}

	ratio := float64(amt) / math.Max(1, float64(failure.amount))
	switch {
	case ratio >= 0.95:
		return 3.2 * float64(failure.count)
	case ratio >= 0.65:
		return 1.1 * float64(failure.count)
	default:
		return 0.22 * float64(failure.count)
	}
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	now := r.view.Now().UnixNano()
	bestScore := make(map[route.Vertex]float64)
	bestAmount := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	bestAmount[r.spec.Target] = amt

	pq := &pathQueue{}
	heap.Push(pq, &pathItem{
		node:   r.spec.Target,
		amount: amt,
	})

	var sourceRisk float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*pathItem)
		knownScore, ok := bestScore[item.node]
		if !ok || item.score > knownScore {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= maxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amount
			if !edge.usable(amtOver) || r.policyBanned[edge.key] {
				continue
			}

			if edge.key.from == r.source {
				if r.localBalances[edge.key.chanID] < amtOver {
					continue
				}
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			probability := 0.999

			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
				probability = channelProbability(edge, amtOver, now)
			}

			edgeRisk := -math.Log(clampProbability(probability))
			edgeRisk += r.edgePenalty(edge, amtOver)
			score := item.score + float64(fee) +
				riskCostMsat*edgeRisk + hopCostMsat

			oldScore, exists := bestScore[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			bestAmount[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &pathItem{
				node:   edge.key.from,
				amount: sending,
				score:  score,
				risk:   item.risk + edgeRisk,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := bestAmount[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, clampProbability(math.Exp(-sourceRisk)), nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to

		if len(path) > maxRouteHops {
			return nil, errors.New("route exceeds maximum hop count")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("source is the payment target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1

	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := finalCltvDelta
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func addAmountCandidate(amounts *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amt, minimum,
	maximum lnwire.MilliSatoshi) {

	if amt < minimum {
		amt = minimum
	}
	if amt > maximum {
		amt = maximum
	}
	if amt <= 0 || seen[amt] {
		return
	}

	seen[amt] = true
	*amounts = append(*amounts, amt)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	maximum := amt

	if r.shardLimit > 0 && r.shardLimit < maximum {
		maximum = r.shardLimit
	}
	if maximum < minimum {
		maximum = minimum
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 5)
	seen := make(map[lnwire.MilliSatoshi]bool)

	addAmountCandidate(&amounts, seen, maximum, minimum, maximum)
	if r.shardLimit == 0 && partsLeft > 1 {
		addAmountCandidate(
			&amounts, seen, amt*3/4, minimum, maximum,
		)
		addAmountCandidate(
			&amounts, seen, amt/2, minimum, maximum,
		)
		addAmountCandidate(
			&amounts, seen, minimum, minimum, maximum,
		)
	}

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		progress := float64(shard) / float64(amt)
		fee := rt.TotalAmount - shard
		if fee < 0 {
			fee = 0
		}
		feeFraction := float64(fee) /
			math.Max(1, float64(shard))

		utility := math.Log(clampProbability(probability)) +
			1.8*math.Log(progress) - 18*feeFraction
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		trial := maximum
		for trial > minimum {
			trial = lnwire.MilliSatoshi(float64(trial) * 0.65)
			if trial < minimum {
				trial = minimum
			}

			rt, _, err := r.findRoute(trial)
			if err == nil {
				bestRoute = rt
				r.shardLimit = trial
				break
			}
			if trial == minimum {
				break
			}
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return bestRoute, nil
}

func routeEdgeKey(rt *route.Route, index int) candidateEdgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func routeEdgeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) edgeCapacity(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	if edge, ok := r.edges[key]; ok {
		return edge.capacity
	}

	return 0
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	now := r.view.Now().UnixNano()

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			amount := routeEdgeAmount(rt, i)
			capacity := r.edgeCapacity(key)
			if capacity > 0 {
				recordSettlement(key, amount, capacity, now)
			}
			delete(r.failures, key)
		}

		if len(rt.Hops) > 0 {
			first := rt.Hops[0].ChannelID
			if balance := r.localBalances[first]; balance > rt.TotalAmount {
				r.localBalances[first] = balance - rt.TotalAmount
			} else {
				r.localBalances[first] = 0
			}
		}

		r.shardLimit = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key := routeEdgeKey(rt, i)
		amount := routeEdgeAmount(rt, i)
		capacity := r.edgeCapacity(key)
		if capacity > 0 {
			recordPass(key, amount, capacity, now)
		}
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			failure := r.failures[key]
			failure.amount = routeEdgeAmount(rt, i)
			failure.count++
			r.failures[key] = failure
		}
		return nil
	}

	key := routeEdgeKey(rt, failIndex)
	amount := routeEdgeAmount(rt, failIndex)
	failure := r.failures[key]
	failure.amount = amount
	failure.count++
	r.failures[key] = failure

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		capacity := r.edgeCapacity(key)
		if capacity > 0 {
			recordFailure(key, amount, capacity, now)
		}

		if failure.count >= 2 {
			delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
			lowerRetry := lnwire.MilliSatoshi(
				float64(delivered) * 0.65,
			)
			if lowerRetry > 0 &&
				(r.shardLimit == 0 || lowerRetry < r.shardLimit) {

				r.shardLimit = lowerRetry
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBanned[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta      = uint32(40)
	minProbability     = 0.005
	maxProbability     = 0.995
	globalHalfLifeMin  = 14.0
	localHalfLifeMin   = 7.0
	lowerRetryFactor   = 0.55
	maxAttempts        = 48
	knownFailurePenalty = 0.90
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	confidence float64
	updatedAt time.Time
}

var sharedCandidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]liquidityBelief
	lastNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localBeliefs map[candidateEdgeKey]liquidityBelief
	edgePenalty  map[candidateEdgeKey]float64
	edgeUses     map[candidateEdgeKey]uint32
	policyBad    map[candidateEdgeKey]bool

	retryMax lnwire.MilliSatoshi
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		localBeliefs:  make(map[candidateEdgeKey]liquidityBelief),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		edgeUses:      make(map[candidateEdgeKey]uint32),
		policyBad:     make(map[candidateEdgeKey]bool),
	}
	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	now := view.Now()
	sharedCandidateKnowledge.Lock()
	if !sharedCandidateKnowledge.lastNow.IsZero() &&
		now.Before(sharedCandidateKnowledge.lastNow) {

		sharedCandidateKnowledge.beliefs =
			make(map[candidateEdgeKey]liquidityBelief)
	}
	sharedCandidateKnowledge.lastNow = now
	sharedCandidateKnowledge.Unlock()

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func clampAmount(amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.90)/0.065))

	return clampProbability(lowMode + highMode)
}

func learnedProbability(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return maxProbability
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		return minProbability
	}

	estimate := b.estimate
	if estimate <= 0 {
		estimate = capacity / 2
	}

	width := math.Max(float64(capacity)*0.055, 1)
	x := (float64(amt) - float64(estimate)) / width

	return clampProbability(1 / (1 + math.Exp(x)))
}

func decayedConfidence(b liquidityBelief, now time.Time,
	halfLife, ceiling float64) float64 {

	if b.confidence <= 0 {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	confidence := b.confidence
	if halfLife > 0 {
		confidence *= math.Exp(-math.Ln2 * age / halfLife)
	}
	if confidence > ceiling {
		confidence = ceiling
	}

	return confidence
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] >= amt {
			return maxProbability
		}

		return minProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	now := r.view.Now()

	if local, ok := r.localBeliefs[edge.key]; ok {
		confidence := decayedConfidence(
			local, now, localHalfLifeMin, 0.98,
		)
		if confidence >= 0.025 {
			learned := learnedProbability(
				local, amt, edge.capacity,
			)

			return clampProbability(
				confidence*learned +
					(1-confidence)*prior,
			)
		}
	}

	sharedCandidateKnowledge.RLock()
	global, ok := sharedCandidateKnowledge.beliefs[edge.key]
	sharedCandidateKnowledge.RUnlock()
	if !ok {
		return prior
	}

	confidence := decayedConfidence(
		global, now, globalHalfLifeMin, 0.90,
	)
	if confidence < 0.025 {
		return prior
	}

	learned := learnedProbability(global, amt, edge.capacity)

	return clampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

func observePass(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := lnwire.MilliSatoshi(
		0.90 * float64(capacity),
	)
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.estimate = clampAmount(b.estimate, capacity)
	b.confidence = math.Min(0.985, b.confidence+0.40)
	b.updatedAt = now

	return b
}

func observeFailure(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}

	lowEstimate := lnwire.MilliSatoshi(math.Min(
		float64(amt)*0.20,
		float64(capacity)*0.055,
	))
	b.estimate = clampAmount(lowEstimate, capacity)
	b.confidence = math.Min(0.99, b.confidence+0.52)
	b.updatedAt = now

	return b
}

func settleBelief(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	b = observePass(b, amt, capacity, now)

	b.estimate = clampAmount(b.estimate-amt, capacity)
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.updatedAt = now

	return b
}

func mirrorBelief(b liquidityBelief,
	capacity lnwire.MilliSatoshi) liquidityBelief {

	mirror := liquidityBelief{
		estimate:  clampAmount(capacity-b.estimate, capacity),
		confidence: b.confidence * 0.92,
		updatedAt: b.updatedAt,
	}

	if b.upperFail > 0 && b.upperFail <= capacity {
		mirror.lowerOK = capacity - b.upperFail + 1
	}
	if b.lowerOK > 0 && b.lowerOK <= capacity {
		mirror.upperFail = capacity - b.lowerOK + 1
	}

	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	return mirror
}

func reverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func (r *candidateRouter) storeLocalPair(key candidateEdgeKey,
	b liquidityBelief, capacity lnwire.MilliSatoshi,
	reverseMinimum lnwire.MilliSatoshi) {

	r.localBeliefs[key] = b

	rev := reverseKey(key)
	if _, ok := r.edges[rev]; !ok {
		return
	}

	mirror := mirrorBelief(b, capacity)
	if reverseMinimum > mirror.lowerOK {
		mirror.lowerOK = clampAmount(
			reverseMinimum, capacity,
		)
	}
	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	r.localBeliefs[rev] = mirror
}

func storeSharedPair(key candidateEdgeKey, b liquidityBelief,
	capacity, reverseMinimum lnwire.MilliSatoshi) {

	sharedCandidateKnowledge.beliefs[key] = b

	rev := reverseKey(key)
	mirror := mirrorBelief(b, capacity)
	if reverseMinimum > mirror.lowerOK {
		mirror.lowerOK = clampAmount(
			reverseMinimum, capacity,
		)
	}
	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	sharedCandidateKnowledge.beliefs[rev] = mirror
	if b.updatedAt.After(sharedCandidateKnowledge.lastNow) {
		sharedCandidateKnowledge.lastNow = b.updatedAt
	}
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observePass(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, 0)

	sharedCandidateKnowledge.Lock()
	global := observePass(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, 0)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.40
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observeFailure(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	reverseMinimum := edge.capacity - clampAmount(
		amt, edge.capacity,
	)
	r.storeLocalPair(
		key, local, edge.capacity, reverseMinimum,
	)

	sharedCandidateKnowledge.Lock()
	global := observeFailure(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(
		key, global, edge.capacity, reverseMinimum,
	)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] += knownFailurePenalty
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := settleBelief(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, amt)

	sharedCandidateKnowledge.Lock()
	global := settleBelief(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, amt)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.30
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	feeScale := math.Max(float64(amt), 250_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		best, ok := bestScore[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.amount) {

				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] <
					item.amount {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			probability := r.edgeProbability(
				edge, item.amount,
			)
			riskCost := -math.Log(probability)
			feeCost := 1.35 * float64(fee) / feeScale
			hopCost := 0.055
			useCost := 0.075 * math.Min(
				float64(r.edgeUses[edge.key]), 8,
			)

			score := item.score + riskCost + feeCost +
				hopCost + useCost +
				r.edgePenalty[edge.key]

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists && (score > oldScore+1e-12 ||
				(math.Abs(score-oldScore) <= 1e-12 &&
					sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:   edge.key.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func ceilDivAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)

	return (amt + divisor - 1) / divisor
}

func routeEdgeData(rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	keys, _ := routeEdgeData(rt)
	for _, key := range keys {
		r.edgeUses[key]++
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is already satisfied")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := ceilDivAmount(amt, partsLeft)
	shard := minimumShard

	if r.retryMax > minimumShard && r.retryMax < amt {
		shard = r.retryMax
	}

	var lastErr error
	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.attempts++
			r.markRouteUsed(rt)

			return rt, nil
		}
		lastErr = err

		if shard >= amt {
			return nil, lastErr
		}

		nextShard := lnwire.MilliSatoshi(
			math.Ceil(float64(shard) * 1.7),
		)
		if nextShard <= shard {
			nextShard = shard + 1
		}
		if nextShard > amt {
			nextShard = amt
		}
		shard = nextShard
	}
}

func failureClass(failure any) (liquidity, policy bool) {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true, false

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return false, true

	default:
		return false, false
	}
}

func failingEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) lowerRetry(
	failedAmount lnwire.MilliSatoshi) {

	next := lnwire.MilliSatoshi(
		float64(failedAmount) * lowerRetryFactor,
	)
	if next <= 0 {
		next = 1
	}
	if r.retryMax == 0 || next < r.retryMax {
		r.retryMax = next
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	keys, amounts := routeEdgeData(rt)
	if len(keys) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range keys {
			r.recordSettlement(keys[i], amounts[i])
		}

		first := keys[0]
		if first.from == r.source {
			balance := r.localBalances[first.chanID]
			if balance > amounts[0] {
				r.localBalances[first.chanID] =
					balance - amounts[0]
			} else {
				r.localBalances[first.chanID] = 0
			}
		}

		r.retryMax = 0
		return nil
	}

	liquidityFailure, policyFailure := failureClass(
		result.Failure,
	)
	failIdx := failingEdgeIndex(rt, result.FailureSource)

	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(keys); i++ {
			r.recordPass(keys[i], amounts[i])
		}
	}

	switch {
	case liquidityFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.recordFailure(keys[failIdx], amounts[failIdx])

	case liquidityFailure && failIdx < 0 && len(keys) == 1:
		r.recordFailure(keys[0], amounts[0])

	case liquidityFailure:
		for i, key := range keys {
			penalty := 0.72
			if i == 0 && key.from == r.source {
				penalty = 0.25
			}
			r.edgePenalty[key] += penalty
		}

	case policyFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.policyBad[keys[failIdx]] = true
		r.edgePenalty[keys[failIdx]] += 10

	default:
		for _, key := range keys {
			r.edgePenalty[key] += 0.30
		}
	}

	if liquidityFailure {
		failedAmount := rt.Hops[len(rt.Hops)-1].
			AmtToForward
		r.lowerRetry(failedAmount)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMinShard       = lnwire.MilliSatoshi(5_000_000)
	candidateRiskCost       = 2_000_000.0
	candidateHopCost        = 25_000.0
	candidateFailureCost    = 8_000_000.0
	candidateReservedCost   = 2_000_000.0
	candidateEvidenceLife   = 10 * time.Minute
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateGlobalBelief struct {
	quality float64
	updated time.Time
}

var candidateKnowledge = struct {
	sync.Mutex

	beliefs     map[candidateEdgeKey]candidateGlobalBelief
	lastViewNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]candidateGlobalBelief),
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from     route.Vertex
	to       route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateRouter struct {
	view   routing.SimNetworkView
	now    time.Time
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localReserved map[uint64]lnwire.MilliSatoshi

	// lowerOK records amounts recently proven to traverse a channel.
	lowerOK map[candidateEdgeKey]lnwire.MilliSatoshi

	// upperFail records amounts that failed during the current payment.
	// Amounts at or above this bound are excluded, while smaller retries
	// remain available.
	upperFail map[candidateEdgeKey]lnwire.MilliSatoshi

	quality      map[candidateEdgeKey]float64
	failures     map[candidateEdgeKey]uint32
	policyBad    map[candidateEdgeKey]bool
	inUse        map[candidateEdgeKey]uint32
	currentShard lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	now := view.Now()
	r := &candidateRouter{
		view:          view,
		now:           now,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		localReserved: make(map[uint64]lnwire.MilliSatoshi),
		lowerOK:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		upperFail:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		quality:       make(map[candidateEdgeKey]float64),
		failures:      make(map[candidateEdgeKey]uint32),
		policyBad:     make(map[candidateEdgeKey]bool),
		inUse:         make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				edge := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.loadBeliefs(now)

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.currentShard = divideCandidateAmount(spec.Amount, parts)
	if r.currentShard < candidateMinShard {
		r.currentShard = candidateMinShard
	}
	if r.currentShard > spec.Amount {
		r.currentShard = spec.Amount
	}

	return r, nil
}

func divideCandidateAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) loadBeliefs(now time.Time) {
	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	if !candidateKnowledge.lastViewNow.IsZero() &&
		now.Before(candidateKnowledge.lastViewNow) {

		candidateKnowledge.beliefs =
			make(map[candidateEdgeKey]candidateGlobalBelief)
	}
	candidateKnowledge.lastViewNow = now

	for key := range r.edges {
		belief, ok := candidateKnowledge.beliefs[key]
		if !ok {
			continue
		}

		age := now.Sub(belief.updated)
		if age < 0 {
			continue
		}

		decay := math.Exp(
			-float64(age) / float64(candidateEvidenceLife),
		)
		r.quality[key] = belief.quality * decay
	}
}

func (r *candidateRouter) updateQuality(key candidateEdgeKey,
	delta float64) {

	value := r.quality[key] + delta
	if value > 6 {
		value = 6
	}
	if value < -6 {
		value = -6
	}
	r.quality[key] = value

	now := r.view.Now()

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	if !candidateKnowledge.lastViewNow.IsZero() &&
		now.Before(candidateKnowledge.lastViewNow) {

		candidateKnowledge.beliefs =
			make(map[candidateEdgeKey]candidateGlobalBelief)
	}
	candidateKnowledge.lastViewNow = now

	old := candidateKnowledge.beliefs[key]
	if !old.updated.IsZero() {
		age := now.Sub(old.updated)
		if age >= 0 {
			old.quality *= math.Exp(
				-float64(age) /
					float64(candidateEvidenceLife),
			)
		} else {
			old.quality = 0
		}
	}

	old.quality += delta
	if old.quality > 6 {
		old.quality = 6
	}
	if old.quality < -6 {
		old.quality = -6
	}
	old.updated = now
	candidateKnowledge.beliefs[key] = old
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.001
	}

	x := float64(amt) / float64(capacity)

	// The first term models the nearly empty mode. The second models the
	// nearly full mode and its capacity cliff.
	lowMode := 0.48 * math.Exp(-x/0.018)
	highMode := 0.50 / (1 + math.Exp((x-0.92)/0.035))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if lower := r.lowerOK[edge.key]; lower >= amt {
		return 0.995
	}

	p := candidatePrior(amt, edge.capacity)
	logOdds := math.Log(p/(1-p)) + r.quality[edge.key]
	p = 1 / (1 + math.Exp(-logOdds))

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

type candidatePathState struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type candidatePathQueue []*candidatePathState

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidatePathQueue) Push(value any) {
	*q = append(*q, value.(*candidatePathState))
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	value := old[last]
	*q = old[:last]

	return value
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	bestScore := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	bestAmount := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &candidatePathQueue{}
	heap.Push(pq, &candidatePathState{
		node:   r.spec.Target,
		amount: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidatePathState)
		knownScore, ok := bestScore[item.node]
		if !ok || item.score > knownScore+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOver := item.amount

			if !edge.usable(amountOver) ||
				r.policyBad[edge.key] {

				continue
			}

			if upper := r.upperFail[edge.key]; upper != 0 &&
				amountOver >= upper {

				continue
			}

			if edge.from == r.source {
				available := r.localBalances[edge.chanID] -
					r.localReserved[edge.chanID]
				if available < amountOver {
					continue
				}
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(amountOver)
				sending += fee
			}

			probability := r.edgeProbability(edge, amountOver)
			edgeScore := float64(fee) + candidateHopCost -
				candidateRiskCost*math.Log(probability)

			edgeScore += float64(r.failures[edge.key]) *
				candidateFailureCost
			edgeScore += float64(r.inUse[edge.key]) *
				candidateReservedCost

			score := item.score + edgeScore
			oldScore, ok := bestScore[edge.from]
			if ok && score >= oldScore {
				continue
			}

			bestScore[edge.from] = score
			bestAmount[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidatePathState{
				node:   edge.from,
				amount: sending,
				score:  score,
			})
		}
	}

	if _, ok := bestAmount[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("source is payment target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteEdges(rt *route.Route) []candidateEdgeKey {
	keys := make([]candidateEdgeKey, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		from = hop.PubKeyBytes
	}

	return keys
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)
	for _, key := range keys {
		r.inUse[key]++
	}

	if len(rt.Hops) != 0 {
		r.localReserved[rt.Hops[0].ChannelID] += rt.TotalAmount
	}
}

func (r *candidateRouter) releaseRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)
	for _, key := range keys {
		if r.inUse[key] > 0 {
			r.inUse[key]--
		}
	}

	if len(rt.Hops) != 0 {
		chanID := rt.Hops[0].ChannelID
		reserved := r.localReserved[chanID]
		if reserved <= rt.TotalAmount {
			delete(r.localReserved, chanID)
		} else {
			r.localReserved[chanID] = reserved - rt.TotalAmount
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	shard := r.currentShard
	if shard == 0 || shard > amt {
		shard = amt
	}

	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.reserveRoute(rt)
			return rt, nil
		}

		if shard <= candidateMinShard {
			return nil, err
		}

		nextShard := shard * 3 / 5
		if nextShard < candidateMinShard {
			nextShard = candidateMinShard
		}
		if nextShard >= shard {
			return nil, err
		}

		shard = nextShard
		r.currentShard = shard
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordPassingPrefix(rt *route.Route,
	count int) {

	keys := candidateRouteEdges(rt)
	if count > len(keys) {
		count = len(keys)
	}

	for i := 0; i < count; i++ {
		amount := candidateRouteAmount(rt, i)
		if amount > r.lowerOK[keys[i]] {
			r.lowerOK[keys[i]] = amount
		}

		r.updateQuality(keys[i], 0.35)
	}
}

func (r *candidateRouter) recordSettledRoute(rt *route.Route) {
	keys := candidateRouteEdges(rt)

	for i, key := range keys {
		amount := candidateRouteAmount(rt, i)

		if lower := r.lowerOK[key]; lower != 0 {
			if lower <= amount {
				delete(r.lowerOK, key)
			} else {
				r.lowerOK[key] = lower - amount
			}
		}

		if upper := r.upperFail[key]; upper != 0 {
			if upper <= amount {
				r.upperFail[key] = 1
			} else {
				r.upperFail[key] = upper - amount
			}
		}

		edge := r.edges[key]
		delta := 0.8
		if edge != nil && edge.capacity > 0 {
			fraction := float64(amount) /
				float64(edge.capacity)
			delta = 1.3 - 2.5*fraction
			if delta < -0.5 {
				delta = -0.5
			}
		}
		r.updateQuality(key, delta)

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   rt.Hops[i].PubKeyBytes,
		}
		if _, ok := r.edges[reverse]; ok {
			r.updateQuality(reverse, 0.7)
		}
	}

	if len(rt.Hops) != 0 {
		chanID := rt.Hops[0].ChannelID
		balance := r.localBalances[chanID]
		if balance <= rt.TotalAmount {
			r.localBalances[chanID] = 0
		} else {
			r.localBalances[chanID] =
				balance - rt.TotalAmount
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.releaseRoute(rt)

	if result.Failure == nil {
		r.recordSettledRoute(rt)
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	keys := candidateRouteEdges(rt)

	if failIndex < 0 {
		for _, key := range keys {
			r.failures[key]++
			r.updateQuality(key, -0.15)
		}
		return nil
	}

	r.recordPassingPrefix(rt, failIndex)

	if failIndex >= len(keys) {
		return nil
	}

	key := keys[failIndex]
	amount := candidateRouteAmount(rt, failIndex)

	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		upper, ok := r.upperFail[key]
		if !ok || amount < upper {
			r.upperFail[key] = amount
		}
		r.failures[key]++
		r.updateQuality(key, -2.4)

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		r.policyBad[key] = true
		r.failures[key] += 2
		r.updateQuality(key, -1.0)

	default:
		r.failures[key]++
		r.updateQuality(key, -0.5)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	minProbability       = 0.005
	maxProbability       = 0.995
	globalHalfLifeMin    = 12.0
	lowerRetryFactor     = 0.52
	maxAttempts          = 48
	maxLabelsPerNode     = 8
	baseFailurePenalty   = 0.55
	unknownRoutePenalty  = 0.34
	minRetryShardFraction = 0.40
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK    lnwire.MilliSatoshi
	upperFail  lnwire.MilliSatoshi
	estimate   lnwire.MilliSatoshi
	confidence float64
	updatedAt  time.Time
}

var sharedCandidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]liquidityBelief
	lastNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localBeliefs  map[candidateEdgeKey]liquidityBelief
	edgePenalty   map[candidateEdgeKey]float64
	failureAmount map[candidateEdgeKey]lnwire.MilliSatoshi
	edgeUses      map[candidateEdgeKey]uint32
	policyBad     map[candidateEdgeKey]bool

	retryMax lnwire.MilliSatoshi
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		localBeliefs:   make(map[candidateEdgeKey]liquidityBelief),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		failureAmount:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		policyBad:      make(map[candidateEdgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	now := view.Now()

	sharedCandidateKnowledge.Lock()
	if !sharedCandidateKnowledge.lastNow.IsZero() &&
		now.Before(sharedCandidateKnowledge.lastNow) {

		sharedCandidateKnowledge.beliefs =
			make(map[candidateEdgeKey]liquidityBelief)
	}
	sharedCandidateKnowledge.lastNow = now
	sharedCandidateKnowledge.Unlock()

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability

	case p > maxProbability:
		return maxProbability

	default:
		return p
	}
}

func clampAmount(amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.50 * math.Exp(-x/0.028)
	highMode := 0.50 / (1 + math.Exp((x-0.91)/0.060))

	return clampProbability(lowMode + highMode)
}

func learnedProbability(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return maxProbability
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		return minProbability
	}

	estimate := b.estimate
	if estimate <= 0 {
		estimate = capacity / 2
	}

	width := math.Max(float64(capacity)*0.04, 1)
	if b.upperFail > 0 {
		width = math.Max(
			width, float64(b.upperFail)*0.22,
		)
	}

	x := (float64(amt) - float64(estimate)) / width
	if x > 40 {
		return minProbability
	}
	if x < -40 {
		return maxProbability
	}

	return clampProbability(1 / (1 + math.Exp(x)))
}

func sharedConfidence(b liquidityBelief, now time.Time) float64 {
	if b.confidence <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	confidence := b.confidence * math.Exp(
		-math.Ln2*age/globalHalfLifeMin,
	)
	if confidence > 0.92 {
		confidence = 0.92
	}

	return confidence
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] >= amt {
			return maxProbability
		}

		return minProbability
	}

	prior := bimodalPrior(amt, edge.capacity)

	if local, ok := r.localBeliefs[edge.key]; ok &&
		local.confidence >= 0.02 {

		confidence := math.Min(local.confidence, 0.99)
		learned := learnedProbability(
			local, amt, edge.capacity,
		)

		return clampProbability(
			confidence*learned + (1-confidence)*prior,
		)
	}

	sharedCandidateKnowledge.RLock()
	global, ok := sharedCandidateKnowledge.beliefs[edge.key]
	sharedCandidateKnowledge.RUnlock()
	if !ok {
		return prior
	}

	confidence := sharedConfidence(global, r.view.Now())
	if confidence < 0.02 {
		return prior
	}

	learned := learnedProbability(global, amt, edge.capacity)

	return clampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

func observePass(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := lnwire.MilliSatoshi(
		0.92 * float64(capacity),
	)
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.estimate = clampAmount(b.estimate, capacity)
	b.confidence = math.Min(0.99, b.confidence+0.48)
	b.updatedAt = now

	return b
}

func observeFailure(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}

	lowEstimate := lnwire.MilliSatoshi(math.Min(
		float64(amt)*0.18,
		float64(capacity)*0.05,
	))
	b.estimate = clampAmount(lowEstimate, capacity)
	b.confidence = math.Min(0.995, b.confidence+0.62)
	b.updatedAt = now

	return b
}

func settleBelief(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	b = observePass(b, amt, capacity, now)
	b.estimate = clampAmount(b.estimate-amt, capacity)

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}

	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.updatedAt = now

	return b
}

func mirrorBelief(b liquidityBelief,
	capacity lnwire.MilliSatoshi) liquidityBelief {

	mirror := liquidityBelief{
		estimate: clampAmount(
			capacity-b.estimate, capacity,
		),
		confidence: b.confidence * 0.90,
		updatedAt:  b.updatedAt,
	}

	if b.upperFail > 0 && b.upperFail <= capacity {
		mirror.lowerOK = capacity - b.upperFail + 1
	}
	if b.lowerOK > 0 && b.lowerOK <= capacity {
		mirror.upperFail = capacity - b.lowerOK + 1
	}

	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	return mirror
}

func reverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func (r *candidateRouter) storeLocalPair(key candidateEdgeKey,
	b liquidityBelief, capacity,
	reverseMinimum lnwire.MilliSatoshi) {

	r.localBeliefs[key] = b

	reverse := reverseKey(key)
	if _, ok := r.edges[reverse]; !ok {
		return
	}

	mirror := mirrorBelief(b, capacity)
	if reverseMinimum > mirror.lowerOK {
		mirror.lowerOK = clampAmount(
			reverseMinimum, capacity,
		)
	}
	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	r.localBeliefs[reverse] = mirror
}

func storeSharedPair(key candidateEdgeKey, b liquidityBelief,
	capacity, reverseMinimum lnwire.MilliSatoshi) {

	sharedCandidateKnowledge.beliefs[key] = b

	reverse := reverseKey(key)
	mirror := mirrorBelief(b, capacity)
	if reverseMinimum > mirror.lowerOK {
		mirror.lowerOK = clampAmount(
			reverseMinimum, capacity,
		)
	}
	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	sharedCandidateKnowledge.beliefs[reverse] = mirror
	if b.updatedAt.After(sharedCandidateKnowledge.lastNow) {
		sharedCandidateKnowledge.lastNow = b.updatedAt
	}
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observePass(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, 0)

	sharedCandidateKnowledge.Lock()
	global := observePass(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, 0)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.30
	if failedAt := r.failureAmount[key]; failedAt > 0 &&
		amt >= failedAt {

		delete(r.failureAmount, key)
	}
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observeFailure(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	reverseMinimum := edge.capacity - clampAmount(
		amt, edge.capacity,
	)
	r.storeLocalPair(
		key, local, edge.capacity, reverseMinimum,
	)

	sharedCandidateKnowledge.Lock()
	global := observeFailure(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(
		key, global, edge.capacity, reverseMinimum,
	)
	sharedCandidateKnowledge.Unlock()

	previous := r.failureAmount[key]
	if previous == 0 || amt < previous {
		r.failureAmount[key] = amt
	}
	r.edgePenalty[key] = math.Min(
		2.5, r.edgePenalty[key]+baseFailurePenalty,
	)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := settleBelief(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, amt)

	sharedCandidateKnowledge.Lock()
	global := settleBelief(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, amt)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.20
	delete(r.failureAmount, key)
}

func (r *candidateRouter) amountPenalty(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) float64 {

	penalty := r.edgePenalty[key]
	failedAt := r.failureAmount[key]
	if failedAt <= 0 || amt >= failedAt {
		return penalty
	}

	ratio := float64(amt) / float64(failedAt)
	return penalty * (0.10 + 0.90*ratio*ratio)
}

type searchLabel struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
	hops   uint16

	edge   *candidateEdge
	next   *searchLabel
	active bool
}

type searchQueue []*searchLabel

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	return q[i].amount < q[j].amount
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(value any) {
	*q = append(*q, value.(*searchLabel))
}

func (q *searchQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func dominates(a, b *searchLabel) bool {
	return a.active &&
		a.score <= b.score+1e-12 &&
		a.amount <= b.amount
}

func addSearchLabel(labels map[route.Vertex][]*searchLabel,
	label *searchLabel) bool {

	current := labels[label.node]
	for _, existing := range current {
		if dominates(existing, label) {
			return false
		}
	}

	kept := current[:0]
	for _, existing := range current {
		if dominates(label, existing) {
			existing.active = false
			continue
		}

		kept = append(kept, existing)
	}

	label.active = true
	kept = append(kept, label)

	if len(kept) > maxLabelsPerNode {
		worst := 0
		worstValue := math.Inf(-1)

		for i, existing := range kept {
			value := existing.score +
				0.16*math.Log1p(float64(existing.amount))
			if value > worstValue {
				worst = i
				worstValue = value
			}
		}

		removed := kept[worst]
		removed.active = false
		kept = append(kept[:worst], kept[worst+1:]...)

		if removed == label {
			labels[label.node] = kept
			return false
		}
	}

	labels[label.node] = kept

	return true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	target := &searchLabel{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
		active: true,
	}

	labels := map[route.Vertex][]*searchLabel{
		r.spec.Target: {target},
	}
	queue := &searchQueue{target}
	heap.Init(queue)

	feeScale := math.Max(float64(amt), 300_000)

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*searchLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			return r.buildRoute(item)
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.amount) {

				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] <
					item.amount {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			if sending <= 0 {
				continue
			}

			probability := r.edgeProbability(
				edge, item.amount,
			)
			riskCost := -math.Log(probability)
			feeCost := 0.90 * float64(fee) / feeScale
			hopCost := 0.085
			if item.hops >= 10 {
				hopCost += 0.025 *
					float64(item.hops-9)
			}

			useCost := 0.065 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.amountPenalty(
				edge.key, item.amount,
			)

			label := &searchLabel{
				node:   edge.key.from,
				score: item.score + riskCost +
					feeCost + hopCost +
					useCost + penalty,
				amount: sending,
				hops:   item.hops + 1,
				edge:   edge,
				next:   item,
			}

			if addSearchLabel(labels, label) {
				heap.Push(queue, label)
			}
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	sourceLabel *searchLabel) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	label := sourceLabel
	for label.node != r.spec.Target {
		if visited[label.node] {
			return nil, errors.New("route contains a cycle")
		}
		visited[label.node] = true

		if label.edge == nil || label.next == nil {
			return nil, fmt.Errorf(
				"broken path at %v", label.node,
			)
		}

		path = append(path, label.edge)
		label = label.next
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = sourceLabel.nextAmountAtTarget()
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amounts[last]
		outgoingExpiry := finalCltvDelta

		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (l *searchLabel) nextAmountAtTarget() lnwire.MilliSatoshi {
	current := l
	for current.next != nil {
		current = current.next
	}

	return current.amount
}

func ceilDivAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func appendShardCandidate(candidates *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool,
	value, maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if seen[value] {
		return
	}

	seen[value] = true
	*candidates = append(*candidates, value)
}

func routeEdgeData(rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	keys, _ := routeEdgeData(rt)
	for _, key := range keys {
		r.edgeUses[key]++
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is already satisfied")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := ceilDivAmount(amt, partsLeft)

	desired := minimumShard
	if partsLeft > 1 && r.retryMax > 0 &&
		r.retryMax < amt {

		floor := lnwire.MilliSatoshi(math.Ceil(
			float64(minimumShard) *
				minRetryShardFraction,
		))
		if floor < 1 {
			floor = 1
		}

		desired = r.retryMax
		if desired < floor {
			desired = floor
		}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	var candidates []lnwire.MilliSatoshi

	appendShardCandidate(
		&candidates, seen, desired, amt,
	)

	if partsLeft > 1 {
		appendShardCandidate(
			&candidates, seen, minimumShard, amt,
		)
		appendShardCandidate(
			&candidates, seen,
			lnwire.MilliSatoshi(math.Ceil(
				float64(minimumShard)*0.72,
			)),
			amt,
		)
		appendShardCandidate(
			&candidates, seen,
			lnwire.MilliSatoshi(math.Ceil(
				float64(minimumShard)*0.45,
			)),
			amt,
		)
	}

	appendShardCandidate(
		&candidates, seen,
		lnwire.MilliSatoshi(math.Ceil(
			float64(minimumShard)*1.45,
		)),
		amt,
	)
	appendShardCandidate(
		&candidates, seen,
		lnwire.MilliSatoshi(math.Ceil(
			float64(minimumShard)*2.15,
		)),
		amt,
	)
	appendShardCandidate(&candidates, seen, amt, amt)

	var lastErr error
	for _, shard := range candidates {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		r.attempts++
		r.markRouteUsed(rt)

		return rt, nil
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func failureClass(failure any) (liquidity, policy bool) {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true, false

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return false, true

	default:
		return false, false
	}
}

func failingEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) lowerRetry(
	failedAmount lnwire.MilliSatoshi) {

	next := lnwire.MilliSatoshi(math.Ceil(
		float64(failedAmount) * lowerRetryFactor,
	))
	if next <= 0 {
		next = 1
	}

	if r.retryMax == 0 || next < r.retryMax {
		r.retryMax = next
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	keys, amounts := routeEdgeData(rt)
	if len(keys) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range keys {
			r.recordSettlement(keys[i], amounts[i])
		}

		first := keys[0]
		if first.from == r.source {
			balance := r.localBalances[first.chanID]
			if balance > amounts[0] {
				r.localBalances[first.chanID] =
					balance - amounts[0]
			} else {
				r.localBalances[first.chanID] = 0
			}
		}

		r.retryMax = 0
		return nil
	}

	liquidityFailure, policyFailure := failureClass(
		result.Failure,
	)
	failIdx := failingEdgeIndex(
		rt, result.FailureSource,
	)

	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(keys); i++ {
			r.recordPass(keys[i], amounts[i])
		}
	}

	switch {
	case liquidityFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.recordFailure(keys[failIdx], amounts[failIdx])

	case liquidityFailure && failIdx < 0 && len(keys) == 1:
		r.recordFailure(keys[0], amounts[0])

	case liquidityFailure:
		for i, key := range keys {
			penalty := unknownRoutePenalty
			if i == 0 && key.from == r.source {
				penalty *= 0.35
			}

			r.edgePenalty[key] = math.Min(
				2.0, r.edgePenalty[key]+penalty,
			)
		}

	case policyFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.policyBad[keys[failIdx]] = true
		r.edgePenalty[keys[failIdx]] += 12

	default:
		for _, key := range keys {
			r.edgePenalty[key] = math.Min(
				2.0, r.edgePenalty[key]+0.22,
			)
		}
	}

	if liquidityFailure {
		failedAmount := rt.Hops[len(rt.Hops)-1].
			AmtToForward
		r.lowerRetry(failedAmount)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	minProbability = 0.005
	maxProbability = 0.995

	localHalfLifeMin  = 10.0
	globalHalfLifeMin = 8.0

	lowerRetryFactor = 0.55
	minRetryFraction = 0.45
	maxAttempts      = 48
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK    lnwire.MilliSatoshi
	upperFail  lnwire.MilliSatoshi
	estimate   lnwire.MilliSatoshi
	confidence float64
	updatedAt  time.Time
}

var sharedCandidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]liquidityBelief
	lastNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localBeliefs map[candidateEdgeKey]liquidityBelief
	edgePenalty  map[candidateEdgeKey]float64
	edgeUses     map[candidateEdgeKey]uint32
	failedAmount map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBad    map[candidateEdgeKey]bool

	retryAmount lnwire.MilliSatoshi
	attempts    uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		localBeliefs:  make(map[candidateEdgeKey]liquidityBelief),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		edgeUses:      make(map[candidateEdgeKey]uint32),
		failedAmount:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	now := view.Now()

	sharedCandidateKnowledge.Lock()
	if !sharedCandidateKnowledge.lastNow.IsZero() &&
		!now.After(sharedCandidateKnowledge.lastNow) {

		sharedCandidateKnowledge.beliefs =
			make(map[candidateEdgeKey]liquidityBelief)
	}
	sharedCandidateKnowledge.lastNow = now
	sharedCandidateKnowledge.Unlock()

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	nodes := []route.Vertex{source}

	for len(nodes) > 0 {
		node := nodes[0]
		nodes = nodes[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					nodes = append(nodes, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func clampAmount(amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}
	if amt <= 0 {
		return maxProbability
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.49 * math.Exp(-x/0.030)
	highMode := 0.50 / (1 + math.Exp((x-0.91)/0.060))

	return clampProbability(lowMode + highMode)
}

func learnedProbability(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return maxProbability
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		return minProbability
	}

	estimate := b.estimate
	if estimate <= 0 {
		estimate = capacity / 2
	}

	width := math.Max(float64(capacity)*0.045, 1)
	x := (float64(amt) - float64(estimate)) / width

	return clampProbability(1 / (1 + math.Exp(x)))
}

func decayedConfidence(b liquidityBelief, now time.Time,
	halfLife, ceiling float64) float64 {

	if b.confidence <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	confidence := b.confidence
	if halfLife > 0 {
		confidence *= math.Exp(-math.Ln2 * age / halfLife)
	}
	if confidence > ceiling {
		confidence = ceiling
	}

	return confidence
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] >= amt {
			return maxProbability
		}

		return minProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	now := r.view.Now()

	if belief, ok := r.localBeliefs[edge.key]; ok {
		confidence := decayedConfidence(
			belief, now, localHalfLifeMin, 0.985,
		)
		if confidence >= 0.02 {
			learned := learnedProbability(
				belief, amt, edge.capacity,
			)

			return clampProbability(
				confidence*learned +
					(1-confidence)*prior,
			)
		}
	}

	sharedCandidateKnowledge.RLock()
	belief, ok := sharedCandidateKnowledge.beliefs[edge.key]
	sharedCandidateKnowledge.RUnlock()
	if !ok {
		return prior
	}

	confidence := decayedConfidence(
		belief, now, globalHalfLifeMin, 0.88,
	)
	if confidence < 0.02 {
		return prior
	}

	learned := learnedProbability(belief, amt, edge.capacity)

	return clampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

func observePass(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := lnwire.MilliSatoshi(
		0.91 * float64(capacity),
	)
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.estimate = clampAmount(b.estimate, capacity)
	b.confidence = math.Min(0.985, b.confidence+0.42)
	b.updatedAt = now

	return b
}

func observeFailure(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}

	lowEstimate := lnwire.MilliSatoshi(math.Min(
		float64(amt)*0.18,
		float64(capacity)*0.045,
	))
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.estimate = clampAmount(b.estimate, capacity)
	b.confidence = math.Min(0.99, b.confidence+0.55)
	b.updatedAt = now

	return b
}

func observeSettlement(b liquidityBelief, amt,
	capacity lnwire.MilliSatoshi, now time.Time) liquidityBelief {

	b = observePass(b, amt, capacity, now)
	b.estimate = clampAmount(b.estimate-amt, capacity)

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.updatedAt = now

	return b
}

func reverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func mirrorBelief(b liquidityBelief,
	capacity lnwire.MilliSatoshi) liquidityBelief {

	mirror := liquidityBelief{
		estimate: clampAmount(
			capacity-b.estimate, capacity,
		),
		confidence: b.confidence * 0.90,
		updatedAt:  b.updatedAt,
	}

	if b.upperFail > 0 && b.upperFail <= capacity {
		mirror.lowerOK = capacity - b.upperFail + 1
	}
	if b.lowerOK > 0 && b.lowerOK <= capacity {
		mirror.upperFail = capacity - b.lowerOK + 1
	}

	if mirror.upperFail > 0 &&
		mirror.lowerOK >= mirror.upperFail {

		mirror.upperFail = 0
	}

	return mirror
}

func mergeReverseMinimum(b liquidityBelief,
	minimum, capacity lnwire.MilliSatoshi) liquidityBelief {

	if minimum > b.lowerOK {
		b.lowerOK = clampAmount(minimum, capacity)
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail > 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}

	return b
}

func (r *candidateRouter) storeLocalPair(key candidateEdgeKey,
	b liquidityBelief, capacity,
	reverseMinimum lnwire.MilliSatoshi) {

	r.localBeliefs[key] = b

	reverse := reverseKey(key)
	if _, ok := r.edges[reverse]; !ok {
		return
	}

	mirror := mirrorBelief(b, capacity)
	mirror = mergeReverseMinimum(
		mirror, reverseMinimum, capacity,
	)
	r.localBeliefs[reverse] = mirror
}

func storeSharedPair(key candidateEdgeKey, b liquidityBelief,
	capacity, reverseMinimum lnwire.MilliSatoshi) {

	sharedCandidateKnowledge.beliefs[key] = b

	reverse := reverseKey(key)
	mirror := mirrorBelief(b, capacity)
	mirror = mergeReverseMinimum(
		mirror, reverseMinimum, capacity,
	)
	sharedCandidateKnowledge.beliefs[reverse] = mirror

	if b.updatedAt.After(sharedCandidateKnowledge.lastNow) {
		sharedCandidateKnowledge.lastNow = b.updatedAt
	}
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observePass(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, 0)

	sharedCandidateKnowledge.Lock()
	global := observePass(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, 0)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.25
	if failed := r.failedAmount[key]; failed > 0 && amt >= failed {
		delete(r.failedAmount, key)
	}
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observeFailure(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	reverseMinimum := edge.capacity - clampAmount(
		amt, edge.capacity,
	)
	r.storeLocalPair(
		key, local, edge.capacity, reverseMinimum,
	)

	sharedCandidateKnowledge.Lock()
	global := observeFailure(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(
		key, global, edge.capacity, reverseMinimum,
	)
	sharedCandidateKnowledge.Unlock()

	if old := r.failedAmount[key]; old == 0 || amt < old {
		r.failedAmount[key] = amt
	}
	r.edgePenalty[key] = math.Min(
		r.edgePenalty[key]+0.85, 3.0,
	)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok {
		return
	}

	now := r.view.Now()
	local := observeSettlement(
		r.localBeliefs[key], amt, edge.capacity, now,
	)
	r.storeLocalPair(key, local, edge.capacity, amt)

	sharedCandidateKnowledge.Lock()
	global := observeSettlement(
		sharedCandidateKnowledge.beliefs[key],
		amt, edge.capacity, now,
	)
	storeSharedPair(key, global, edge.capacity, amt)
	sharedCandidateKnowledge.Unlock()

	r.edgePenalty[key] *= 0.20
	delete(r.failedAmount, key)
}

func (r *candidateRouter) failurePenalty(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) float64 {

	penalty := r.edgePenalty[key]
	failed := r.failedAmount[key]
	if failed <= 0 {
		return penalty
	}

	ratio := float64(amt) / float64(failed)
	switch {
	case ratio <= 0.35:
		return penalty * 0.05
	case ratio <= lowerRetryFactor:
		return penalty * 0.15
	case ratio < 0.85:
		return penalty * 0.50
	default:
		return penalty
	}
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	return q[i].amount < q[j].amount
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	feeScale := math.Max(float64(amt), 500_000)

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*dijkstraItem)

		best, ok := bestScore[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if current := required[item.node]; current != item.amount {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.amount) {

				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] <
					item.amount {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			probability := r.edgeProbability(
				edge, item.amount,
			)
			riskCost := -math.Log(probability)
			feeCost := 0.85 * float64(fee) / feeScale
			hopCost := 0.16

			uses := math.Min(
				float64(r.edgeUses[edge.key]), 6,
			)
			useCost := 0.14 * uses

			score := item.score + riskCost + feeCost +
				hopCost + useCost +
				r.failurePenalty(edge.key, item.amount)

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(score > oldScore+1e-12 ||
					(math.Abs(score-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &dijkstraItem{
				node:   edge.key.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func ceilDivAmount(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)

	return (amt + divisor - 1) / divisor
}

func routeEdgeData(rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	keys, _ := routeEdgeData(rt)
	for _, key := range keys {
		r.edgeUses[key]++
	}
}

func (r *candidateRouter) chooseShard(amt lnwire.MilliSatoshi,
	partsLeft uint32) lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return amt
	}

	average := ceilDivAmount(amt, partsLeft)
	if r.retryAmount <= 0 {
		return average
	}

	floor := lnwire.MilliSatoshi(
		math.Ceil(float64(average) * minRetryFraction),
	)
	if floor <= 0 {
		floor = 1
	}

	shard := r.retryAmount
	if shard < floor {
		shard = floor
	}
	if shard > amt {
		shard = amt
	}

	return shard
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is already satisfied")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	shard := r.chooseShard(amt, partsLeft)

	var lastErr error

	for {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.attempts++
			r.markRouteUsed(rt)

			return rt, nil
		}
		lastErr = err

		if shard >= amt {
			return nil, lastErr
		}

		nextShard := lnwire.MilliSatoshi(
			math.Ceil(float64(shard) * 1.55),
		)
		if nextShard <= shard {
			nextShard = shard + 1
		}
		if nextShard > amt {
			nextShard = amt
		}

		shard = nextShard
	}
}

func failureClass(failure any) (liquidity, policy bool) {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true, false

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return false, true

	default:
		return false, false
	}
}

func failingEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) lowerRetry(
	failedAmount lnwire.MilliSatoshi) {

	next := lnwire.MilliSatoshi(
		math.Ceil(float64(failedAmount) * lowerRetryFactor),
	)
	if next <= 0 {
		next = 1
	}

	if r.retryAmount == 0 || next < r.retryAmount {
		r.retryAmount = next
	}
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		penalty := 0.42
		if i == 0 && key.from == r.source {
			penalty = 0.12
		}

		r.edgePenalty[key] = math.Min(
			r.edgePenalty[key]+penalty, 2.5,
		)
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	keys, amounts := routeEdgeData(rt)
	if len(keys) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range keys {
			r.recordSettlement(keys[i], amounts[i])
		}

		first := keys[0]
		if first.from == r.source {
			balance := r.localBalances[first.chanID]
			if balance > amounts[0] {
				r.localBalances[first.chanID] =
					balance - amounts[0]
			} else {
				r.localBalances[first.chanID] = 0
			}
		}

		r.retryAmount = 0

		return nil
	}

	liquidityFailure, policyFailure := failureClass(
		result.Failure,
	)
	failIdx := failingEdgeIndex(rt, result.FailureSource)

	if failIdx > len(keys) {
		failIdx = -1
	}

	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(keys); i++ {
			r.recordPass(keys[i], amounts[i])
		}
	}

	switch {
	case liquidityFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.recordFailure(keys[failIdx], amounts[failIdx])

	case liquidityFailure && len(keys) == 1:
		r.recordFailure(keys[0], amounts[0])

	case policyFailure &&
		failIdx >= 0 && failIdx < len(keys):

		r.policyBad[keys[failIdx]] = true
		r.edgePenalty[keys[failIdx]] = 20

	default:
		r.penalizeUnknownRoute(keys)
	}

	if liquidityFailure {
		failedAmount := rt.Hops[len(rt.Hops)-1].
			AmtToForward
		if failIdx >= 0 && failIdx < len(amounts) {
			failedAmount = amounts[failIdx]
		}

		r.lowerRetry(failedAmount)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	minShardAmount = lnwire.MilliSatoshi(1_000_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return amt <= e.capacity
}

type liquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	confidence float64
	updated   time.Time
}

var candidateSharedBeliefs = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]liquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]liquidityBelief),
}

type localFailure struct {
	amount lnwire.MilliSatoshi
	at     time.Time
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi

	failed       map[candidateEdgeKey]localFailure
	policyFailed map[candidateEdgeKey]bool

	shardAmt       lnwire.MilliSatoshi
	failuresAtSize int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		failed:         make(map[candidateEdgeKey]localFailure),
		policyFailed:   make(map[candidateEdgeKey]bool),
		shardAmt:       spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				r.edges[edge.key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// The low mode makes very small transfers nearly certain, while the
	// high mode leaves ordinary transfers near a one-sided 50% prior.
	lowMode := 0.485 * math.Exp(-x/0.025)
	highMode := 0.5

	// Even a high-side channel becomes unlikely close to its capacity.
	cliff := 1 / (1 + math.Exp((x-0.92)/0.035))
	p := (highMode + lowMode) * cliff

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.confidence <= 0 {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.confidence
	}

	// Evidence decays quickly enough to tolerate background traffic while
	// remaining useful across nearby payments in the same scenario.
	decay := math.Exp(-float64(age) / float64(25*time.Minute))
	confidence := b.confidence * decay
	if confidence < 0 {
		return 0
	}
	if confidence > 1 {
		return 1
	}

	return confidence
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		return 0.999
	}

	prior := bimodalPrior(amt, edge.capacity)
	now := r.view.Now()

	candidateSharedBeliefs.RLock()
	belief, ok := candidateSharedBeliefs.beliefs[edge.key]
	candidateSharedBeliefs.RUnlock()

	if !ok || belief.capacity != edge.capacity {
		return prior
	}

	confidence := beliefConfidence(belief, now)
	if confidence < 0.01 {
		return prior
	}

	reserved := r.reserved[edge.key]
	queryAmt := amt + reserved

	var learned float64
	switch {
	case belief.lowerOK > 0 && queryAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && queryAmt >= belief.upperFail:
		learned = 0.003

	case belief.estimate > 0:
		scale := math.Max(float64(edge.capacity)*0.06, 1)
		distance := (float64(queryAmt) -
			float64(belief.estimate)) / scale
		learned = 0.005 + 0.985/(1+math.Exp(distance))

	default:
		learned = prior
	}

	p := prior*(1-confidence) + learned*confidence
	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func routeAmount(rt *route.Route, channelIndex int) lnwire.MilliSatoshi {
	if channelIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[channelIndex-1].AmtToForward
}

func routeEdgeKeys(rt *route.Route) []candidateEdgeKey {
	keys := make([]candidateEdgeKey, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		from = hop.PubKeyBytes
	}

	return keys
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i, key := range routeEdgeKeys(rt) {
		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) releaseRoute(rt *route.Route) {
	for i, key := range routeEdgeKeys(rt) {
		amount := routeAmount(rt, i)
		if r.reserved[key] <= amount {
			delete(r.reserved, key)
			continue
		}

		r.reserved[key] -= amount
	}
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) failureStillFresh(failure localFailure) bool {
	return r.view.Now().Sub(failure.at) < 8*time.Minute
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	scores := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:  r.spec.Target,
		score: 0,
	})

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := required[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) || r.policyFailed[edge.key] {
				continue
			}

			if failure, ok := r.failed[edge.key]; ok {
				if r.failureStillFresh(failure) &&
					arriving*100 >= failure.amount*88 {

					continue
				}
			}

			reserved := r.reserved[edge.key]
			if arriving+reserved > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance := r.localBalances[edge.chanID]
				if balance < arriving+reserved {
					continue
				}
			}

			sending := arriving
			feeCost := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				feeCost = edge.fee(arriving)
				sending += feeCost
			}

			probability := r.edgeProbability(edge, arriving)

			// Reliability dominates the fee term. The amount-dependent
			// weight makes large-payment exploration favor wide channels.
			riskWeight := 2_000_000.0 +
				float64(arriving)/100.0
			edgeScore := float64(feeCost) -
				math.Log(probability)*riskWeight

			// Concurrent shards receive a mild diversity penalty.
			if reserved > 0 {
				edgeScore += riskWeight *
					float64(reserved) /
					math.Max(float64(edge.capacity), 1)
			}

			newScore := item.score + edgeScore
			oldScore, seen := scores[edge.from]
			if seen && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			required[edge.from] = sending
			next[edge.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 12)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) reduceShard(current lnwire.MilliSatoshi) bool {
	if current <= minShardAmount {
		return false
	}

	reduced := current * 62 / 100
	if reduced < minShardAmount {
		reduced = minShardAmount
	}
	if reduced >= current {
		reduced = current - 1
	}
	if reduced <= 0 {
		return false
	}

	r.shardAmt = reduced
	r.failuresAtSize = 0

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts != 0 && inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}

	if r.shardAmt <= 0 || r.shardAmt > amt {
		r.shardAmt = amt
		r.failuresAtSize = 0
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			r.reserveRoute(rt)
			return rt, nil
		}

		if !r.reduceShard(r.shardAmt) {
			return nil, err
		}
	}
}

func clampMSat(value, low,
	high lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value < low {
		return low
	}
	if value > high {
		return high
	}

	return value
}

func updateFailureBelief(edge *candidateEdge,
	amount lnwire.MilliSatoshi, now time.Time) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	belief := candidateSharedBeliefs.beliefs[edge.key]
	if belief.capacity != edge.capacity {
		belief = liquidityBelief{
			capacity: edge.capacity,
			estimate: edge.capacity / 2,
		}
	}

	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = amount - 1
	}
	if belief.estimate == 0 || belief.estimate >= amount {
		belief.estimate = amount / 4
	}
	belief.confidence = 1
	belief.updated = now
	candidateSharedBeliefs.beliefs[edge.key] = belief

	reverseKey := candidateEdgeKey{
		chanID: edge.chanID,
		from:   edge.to,
	}
	reverse := candidateSharedBeliefs.beliefs[reverseKey]
	if reverse.capacity != edge.capacity {
		reverse = liquidityBelief{
			capacity: edge.capacity,
			estimate: edge.capacity / 2,
		}
	}

	reverseLower := edge.capacity - amount
	if reverseLower < 0 {
		reverseLower = 0
	}
	if reverseLower > reverse.lowerOK {
		reverse.lowerOK = reverseLower
	}
	if reverse.estimate < reverseLower {
		reverse.estimate = reverseLower
	}
	reverse.confidence = math.Max(reverse.confidence, 0.9)
	reverse.updated = now
	candidateSharedBeliefs.beliefs[reverseKey] = reverse
}

func updateSuccessBeliefs(r *candidateRouter, rt *route.Route) {
	now := r.view.Now()
	keys := routeEdgeKeys(rt)

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	for i, key := range keys {
		edge, ok := r.edges[key]
		if !ok {
			continue
		}

		amount := routeAmount(rt, i)
		remaining := edge.capacity - amount
		if remaining < 0 {
			remaining = 0
		}

		belief := candidateSharedBeliefs.beliefs[key]
		if belief.capacity != edge.capacity {
			belief = liquidityBelief{
				capacity: edge.capacity,
			}
		}

		// Passing in a bimodal channel strongly identifies the high side.
		inferredLower := edge.capacity*7/10 - amount
		if inferredLower < 0 {
			inferredLower = 0
		}
		belief.lowerOK = inferredLower
		belief.estimate = remaining
		belief.upperFail = 0
		belief.confidence = 0.92
		belief.updated = now
		candidateSharedBeliefs.beliefs[key] = belief

		reverseKey := candidateEdgeKey{
			chanID: edge.chanID,
			from:   edge.to,
		}
		reverse := candidateSharedBeliefs.beliefs[reverseKey]
		if reverse.capacity != edge.capacity {
			reverse = liquidityBelief{
				capacity: edge.capacity,
			}
		}

		reverse.estimate = clampMSat(
			reverse.estimate+amount, amount, edge.capacity,
		)
		if reverse.lowerOK < amount {
			reverse.lowerOK = amount
		}
		if reverse.upperFail != 0 &&
			reverse.upperFail <= reverse.lowerOK {

			reverse.upperFail = 0
		}
		reverse.confidence = math.Max(reverse.confidence, 0.8)
		reverse.updated = now
		candidateSharedBeliefs.beliefs[reverseKey] = reverse
	}
}

func failingChannelIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	r.releaseRoute(rt)

	if result.Failure == nil {
		updateSuccessBeliefs(r, rt)
		r.failuresAtSize = 0
		return nil
	}

	failIndex := failingChannelIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		r.failuresAtSize++
		if r.failuresAtSize >= 2 {
			r.reduceShard(r.shardAmt)
		}
		return nil
	}

	keys := routeEdgeKeys(rt)
	key := keys[failIndex]
	edge, ok := r.edges[key]
	if !ok {
		return nil
	}

	amount := routeAmount(rt, failIndex)
	code := result.Failure.Code()

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		previous, exists := r.failed[key]
		if !exists || amount < previous.amount ||
			!r.failureStillFresh(previous) {

			r.failed[key] = localFailure{
				amount: amount,
				at:     r.view.Now(),
			}
		}

		updateFailureBelief(edge, amount, r.view.Now())

		r.failuresAtSize++
		if r.failuresAtSize >= 2 {
			r.reduceShard(r.shardAmt)
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry,
		lnwire.CodeAmountBelowMinimum,
		lnwire.CodeExpiryTooSoon,
		lnwire.CodePermanentChannelFailure,
		lnwire.CodeRequiredChannelFeatureMissing,
		lnwire.CodeUnknownNextPeer:

		r.policyFailed[key] = true

	default:
		// Avoid repeatedly selecting the identical failing direction for
		// failures that are not actionable from public gossip.
		r.policyFailed[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	capacity lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var candidateMemory = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
	lastNow time.Time
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// The low mode models a nearly depleted direction, while the high mode
	// models a direction holding almost the entire channel capacity.
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp((x-0.92)/0.055))

	return clampProbability(0.48*lowMode + 0.52*highMode)
}

func beliefProbability(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	candidateMemory.Lock()
	belief, ok := candidateMemory.beliefs[key]
	candidateMemory.Unlock()

	if !ok || belief.conf <= 0 {
		return prior
	}

	capacity = belief.capacity
	if capacity <= 0 {
		return prior
	}

	var learned float64
	switch {
	case belief.lowerOK > 0 && amt <= belief.lowerOK:
		learned = 0.995

	case belief.upperBad > 0 && amt >= belief.upperBad:
		learned = 0.005

	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		width := float64(belief.upperBad - belief.lowerOK)
		pos := float64(amt-belief.lowerOK) / width
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.985 - 0.98*pos

	case belief.estimate > 0:
		scale := math.Max(float64(capacity)*0.07, 1)
		learned = 1 / (1 + math.Exp(
			(float64(amt)-float64(belief.estimate))/scale,
		))

	case belief.upperBad > 0:
		ratio := float64(amt) / float64(belief.upperBad)
		learned = 0.01 + 0.97*math.Exp(-3.2*ratio)

	default:
		learned = math.Max(prior, 0.80)
	}

	confidence := 1 - math.Exp(-0.70*belief.conf)
	if !now.IsZero() && !belief.updated.IsZero() {
		age := now.Sub(belief.updated)
		if age < 0 {
			age = 0
		}
		confidence *= math.Exp(-float64(age) /
			float64(18*time.Minute))
	}

	return clampProbability(
		confidence*clampProbability(learned) +
			(1-confidence)*prior,
	)
}

func recordPass(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) {

	candidateMemory.Lock()
	defer candidateMemory.Unlock()

	b := candidateMemory.beliefs[key]
	b.capacity = capacity

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		b.upperBad = 0
	}

	highEstimate := lnwire.MilliSatoshi(
		0.84 * float64(capacity),
	)
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.conf = math.Min(8, b.conf+1)
	b.updated = now
	candidateMemory.beliefs[key] = b
}

func recordFailure(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) {

	candidateMemory.Lock()
	defer candidateMemory.Unlock()

	b := candidateMemory.beliefs[key]
	b.capacity = capacity

	if b.upperBad == 0 || amt < b.upperBad {
		b.upperBad = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}

	depletedEstimate := amt / 4
	if b.estimate == 0 || depletedEstimate < b.estimate {
		b.estimate = depletedEstimate
	}

	b.conf = math.Min(8, b.conf+1.35)
	b.updated = now
	candidateMemory.beliefs[key] = b
}

func recordSettlement(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) {

	candidateMemory.Lock()
	defer candidateMemory.Unlock()

	b := candidateMemory.beliefs[key]
	b.capacity = capacity

	preEstimate := b.estimate
	highEstimate := lnwire.MilliSatoshi(
		0.84 * float64(capacity),
	)
	if preEstimate < highEstimate {
		preEstimate = highEstimate
	}
	if preEstimate < amt {
		preEstimate = amt
	}

	if b.lowerOK < amt {
		b.lowerOK = amt
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		b.upperBad = 0
	}

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperBad > amt {
		b.upperBad -= amt
	} else {
		b.upperBad = 0
	}
	if preEstimate > amt {
		b.estimate = preEstimate - amt
	} else {
		b.estimate = 0
	}

	b.conf = math.Min(8, b.conf+1)
	b.updated = now
	candidateMemory.beliefs[key] = b
}

func recordReverseCredit(key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) {

	reverse := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}

	candidateMemory.Lock()
	defer candidateMemory.Unlock()

	b := candidateMemory.beliefs[reverse]
	b.capacity = capacity

	if b.lowerOK < amt {
		b.lowerOK = amt
	}
	if b.estimate == 0 {
		b.estimate = amt
	} else if b.estimate < capacity-amt {
		b.estimate += amt
	}
	if b.estimate > capacity {
		b.estimate = capacity
	}
	if b.upperBad > 0 && b.upperBad <= b.lowerOK {
		b.upperBad = 0
	}

	b.conf = math.Min(8, b.conf+0.8)
	b.updated = now
	candidateMemory.beliefs[reverse] = b
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	localFailed   map[uint64]lnwire.MilliSatoshi

	attemptPenalty map[candidateEdgeKey]float64
	policyBad      map[candidateEdgeKey]bool

	failedAttempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	now := view.Now()

	candidateMemory.Lock()
	if !candidateMemory.lastNow.IsZero() &&
		!now.IsZero() && now.Before(candidateMemory.lastNow) {

		candidateMemory.beliefs =
			make(map[candidateEdgeKey]candidateBelief)
	}
	if now.After(candidateMemory.lastNow) {
		candidateMemory.lastNow = now
	}
	candidateMemory.Unlock()

	router := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		localFailed:    make(map[uint64]lnwire.MilliSatoshi),
		attemptPenalty: make(map[candidateEdgeKey]float64),
		policyBad:      make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := router.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.edges[key] = edge
				router.incomingEdges[key.to] = append(
					router.incomingEdges[key.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

type candidateItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
	hops  int
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(x any) {
	*q = append(*q, x.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		return 0.997
	}

	return beliefProbability(
		edge.key, amt, edge.capacity, r.view.Now(),
	)
}

func (r *candidateRouter) localAvailable(chanID uint64) lnwire.MilliSatoshi {
	balance := r.localBalances[chanID]
	spent := r.localSpent[chanID]
	if spent >= balance {
		return 0
	}
	return balance - spent
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source is payment target")
	}

	dist := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	required[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}
		if item.hops >= maxRouteHops {
			continue
		}

		arriving := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] || !edge.usable(arriving) {
				continue
			}

			if edge.key.from == r.source {
				if arriving > r.localAvailable(edge.key.chanID) {
					continue
				}
				if bound := r.localFailed[edge.key.chanID];
					bound > 0 && arriving >= bound {

					continue
				}
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(arriving)
				if fee < 0 ||
					arriving > lnwire.MilliSatoshi(
						math.MaxInt64,
					)-fee {

					continue
				}
				sending += fee
			}

			p := r.edgeProbability(edge, arriving)
			riskCost := -math.Log(p)
			feeCost := 0.0
			if amt > 0 {
				feeCost = 18 * float64(fee) /
					float64(amt)
			}

			retryCost := r.attemptPenalty[edge.key]
			score := item.score + riskCost + feeCost +
				retryCost + 0.012

			old, exists := dist[edge.key.from]
			if exists && score >= old-1e-12 {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.key.from,
				score: score,
				amt:   sending,
				hops:  item.hops + 1,
			})
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	logProbability := 0.0
	for i, edge := range path {
		amtOver := rt.TotalAmount
		if i > 0 {
			amtOver = rt.Hops[i-1].AmtToForward
		}
		logProbability += math.Log(
			r.edgeProbability(edge, amtOver),
		)
	}

	return rt, math.Exp(math.Max(logProbability, -700)), nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		if len(path) > maxRouteHops {
			return nil, nil, errors.New("route exceeds hop limit")
		}
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func addShardSize(sizes *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, size, minimum,
	maximum lnwire.MilliSatoshi) {

	if size < minimum {
		size = minimum
	}
	if size > maximum {
		size = maximum
	}
	if size <= 0 || seen[size] {
		return
	}

	seen[size] = true
	*sizes = append(*sizes, size)
}

func scaledAmount(amt lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	return lnwire.MilliSatoshi(
		int64(amt) * numerator / denominator,
	)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := amt / lnwire.MilliSatoshi(partsLeft)
	if amt%lnwire.MilliSatoshi(partsLeft) != 0 {
		minimum++
	}

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	addShardSize(&sizes, seen, amt, minimum, amt)
	addShardSize(
		&sizes, seen, scaledAmount(amt, 4, 5), minimum, amt,
	)
	addShardSize(
		&sizes, seen, scaledAmount(amt, 3, 5), minimum, amt,
	)
	addShardSize(
		&sizes, seen, scaledAmount(amt, 1, 2), minimum, amt,
	)
	addShardSize(
		&sizes, seen, scaledAmount(amt, 2, 5), minimum, amt,
	)
	addShardSize(&sizes, seen, minimum, minimum, amt)

	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, size := range sizes {
		rt, probability, err := r.findRoute(size)
		if err != nil {
			lastErr = err
			continue
		}

		probability = math.Max(probability, 1e-300)
		progress := float64(size) / float64(minimum)
		utility := math.Log(probability) +
			0.78*math.Log(math.Max(progress, 1))

		fee := rt.TotalAmount - size
		if size > 0 {
			utility -= 12 * float64(fee) / float64(size)
		}

		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	return bestRoute, nil
}

func routeEdgeKeys(rt *route.Route) []candidateEdgeKey {
	keys := make([]candidateEdgeKey, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		from = hop.PubKeyBytes
	}

	return keys
}

func routeAmountAt(rt *route.Route, edgeIndex int) lnwire.MilliSatoshi {
	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("attempt route is nil")
	}

	keys := routeEdgeKeys(rt)
	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			amtOver := routeAmountAt(rt, i)
			recordSettlement(
				key, amtOver, edge.capacity, now,
			)
			recordReverseCredit(
				key, amtOver, edge.capacity, now,
			)

			r.attemptPenalty[key] *= 0.45
		}

		if len(rt.Hops) > 0 {
			first := rt.Hops[0]
			r.localSpent[first.ChannelID] += rt.TotalAmount
		}

		r.failedAttempts = 0
		return nil
	}

	r.failedAttempts++
	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)

	// Every channel preceding the failure carried the HTLC successfully.
	// The failed attempt is atomic, so these observations do not move funds.
	if failIndex > 0 {
		for i := 0; i < failIndex && i < len(keys); i++ {
			edge := r.edges[keys[i]]
			if edge == nil {
				continue
			}
			recordPass(
				keys[i], routeAmountAt(rt, i),
				edge.capacity, now,
			)
			r.attemptPenalty[keys[i]] *= 0.75
		}
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		if failIndex >= 0 && failIndex < len(keys) {
			key := keys[failIndex]
			edge := r.edges[key]
			amtOver := routeAmountAt(rt, failIndex)

			if edge != nil {
				recordFailure(
					key, amtOver, edge.capacity, now,
				)
			}
			r.attemptPenalty[key] += 1.4 +
				0.08*float64(r.failedAttempts)

			if failIndex == 0 {
				old := r.localFailed[key.chanID]
				if old == 0 || amtOver < old {
					r.localFailed[key.chanID] = amtOver
				}
			}
		} else {
			for _, key := range keys {
				r.attemptPenalty[key] += 0.35
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if failIndex >= 0 && failIndex < len(keys) {
			key := keys[failIndex]
			r.policyBad[key] = true
			r.attemptPenalty[key] += 8
		} else {
			for _, key := range keys {
				r.attemptPenalty[key] += 0.65
			}
		}

	default:
		// Unknown failures provide no safe liquidity bound. Penalizing the
		// attempted path still prevents an identical retry loop.
		for _, key := range keys {
			r.attemptPenalty[key] += 0.45
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	proportional := (amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million

	return e.baseFeeMsat + proportional
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	if b.conf < 0 {
		b.conf = 0
	}
	if b.conf > 0.99 {
		b.conf = 0.99
	}

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Background traffic can invalidate old directional evidence quickly.
	const halfLifeMinutes = 35.0
	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)

	if conf < 0.01 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	b.conf = conf

	// Bounds become hints rather than permanent facts after substantial age.
	if now.Sub(b.updatedAt) > 20*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidateKnowledge.beliefs[reverseKey]
	reverse = candidatePrepareObservation(
		reverse, capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.88)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := edge.capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.conf = math.Max(b.conf, 0.92)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	lowEstimate := amt / 16
	capFloor := edge.capacity / 500
	if capFloor < 1 {
		capFloor = 1
	}
	if lowEstimate > capFloor {
		lowEstimate = capFloor
	}
	if lowEstimate < b.lowerOK {
		lowEstimate = b.lowerOK
	}
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.conf = math.Max(b.conf, 0.98)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	estimate := b.estimate
	if estimate < amt {
		estimate = edge.capacity * 9 / 10
		if estimate < amt {
			estimate = amt
		}
	}

	b.estimate = estimate - amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}

	return probability
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-ratio/0.025)
	highMode := 0.50 /
		(1 + math.Exp((ratio-0.92)/0.045))

	return candidateClampProbability(0.005 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.005
	}

	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.035, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		if fraction < 0 {
			fraction = 0
		}
		if fraction > 1 {
			fraction = 1
		}

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.4)
		probability = 0.65*bounded + 0.35*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	if failedAt := r.sessionFailed[edge.key]; failedAt != 0 {
		if amt >= failedAt {
			return 0
		}

		ratio := float64(amt) / float64(failedAt)
		if ratio > 0.75 {
			return 0.006
		}
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())
	if conf == 0 {
		return prior
	}

	learned := candidateLearnedProbability(
		b, amt, edge.capacity,
	)
	probability := conf*learned + (1-conf)*prior

	if failedAt := r.sessionFailed[edge.key]; failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.55:
			probability *= 0.08
		case ratio > 0.30:
			probability *= 0.30
		case ratio > 0.12:
			probability *= 0.65
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 8 * float64(fee) / feeScale
			hopCost := 0.055
			useCost := 0.035 * math.Min(
				float64(r.edgeUses[edge.key]), 8,
			)
			penalty := r.sessionPenalty[edge.key]

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 20)
	amounts = candidateAppendUnique(amounts, amt)

	limit := partsLeft
	if limit > 16 {
		limit = 16
	}

	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	amounts = candidateAppendUnique(
		amounts, candidateCeilDiv(amt, partsLeft),
	)

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	shards := candidateShardAmounts(amt, partsLeft)
	minimum := candidateCeilDiv(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log1p(
			float64(shard) / math.Max(float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 6 * float64(fee) /
			math.Max(float64(shard), 1)

		utility := math.Log(math.Max(probability, 1e-12)) +
			0.48*progress - feePenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}

		if probability >= 0.55 && shard >= amt/2 {
			bestRoute = rt
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}

	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.20
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}

	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.25, 6,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.15

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.45
		if i > len(keys)/2 {
			penalty = 0.60
		}
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 4,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
		}

		return nil
	}

	// Unknown-source failures contain no reliable channel attribution.
	// Penalizing the route still forces exploration without poisoning
	// persistent channel beliefs.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 56
	candidateMaxRouteHops   = 20
	candidateMaxLabels      = 4
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Persistent evidence is useful across nearby payments, but background
	// traffic can substantially alter a channel within a few virtual minutes.
	const halfLifeMinutes = 12.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	b.conf = conf

	// Old bounds remain represented by the estimate, but cease being hard
	// observations once background traffic could plausibly cross them.
	if now.Sub(b.updatedAt) > 6*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.86)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := edge.capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.conf = math.Max(b.conf, 0.93)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity miss is strong evidence for the depleted mode, but it does
	// not imply that much smaller shards cannot pass.
	lowEstimate := amt / 12
	capFloor := edge.capacity / 400
	if capFloor < 1 {
		capFloor = 1
	}
	if lowEstimate > capFloor {
		lowEstimate = capFloor
	}
	if lowEstimate < b.lowerOK {
		lowEstimate = b.lowerOK
	}
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	estimate := b.estimate
	if estimate < amt {
		estimate = edge.capacity * 9 / 10
		if estimate < amt {
			estimate = amt
		}
	}

	b.estimate = estimate - amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.005, math.Min(probability, 0.995))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode describes tiny payments that pass even on the depleted
	// side. The high mode describes channels whose liquidity is concentrated
	// almost entirely in the requested direction.
	lowMode := 0.49 * math.Exp(-ratio/0.026)
	highMode := 0.495 /
		(1 + math.Exp((ratio-0.915)/0.042))

	return candidateClampProbability(0.005 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.005
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.03, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.2)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.78:
			probability *= 0.025
		case ratio > 0.55:
			probability *= 0.11
		case ratio > 0.32:
			probability *= 0.35
		case ratio > 0.15:
			probability *= 0.72
		}
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgePenalty(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	penalty := r.sessionPenalty[edge.key]
	failedAt := r.sessionFailed[edge.key]

	if failedAt != 0 && amt < failedAt {
		ratio := float64(amt) / float64(failedAt)
		penalty *= math.Max(0.08, ratio)
	}

	return penalty
}

type candidateLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16

	edge   *candidateEdge
	child  *candidateLabel
	active bool
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].amount != q[j].amount {
		return q[i].amount < q[j].amount
	}

	return q[i].hops < q[j].hops
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type candidateLabelKey struct {
	node route.Vertex
	hops uint16
}

func candidateDominates(a, b *candidateLabel) bool {
	return a.score <= b.score+1e-12 && a.amount <= b.amount
}

func candidateInsertLabel(
	labels map[candidateLabelKey][]*candidateLabel,
	label *candidateLabel) bool {

	key := candidateLabelKey{
		node: label.node,
		hops: label.hops,
	}
	current := labels[key]

	for _, existing := range current {
		if existing.active && candidateDominates(existing, label) {
			return false
		}
	}

	kept := current[:0]
	for _, existing := range current {
		if existing.active && candidateDominates(label, existing) {
			existing.active = false
			continue
		}
		if existing.active {
			kept = append(kept, existing)
		}
	}

	label.active = true
	kept = append(kept, label)

	if len(kept) > candidateMaxLabels {
		worst := 0
		for i := 1; i < len(kept); i++ {
			worstValue := kept[worst].score +
				0.12*math.Log1p(float64(kept[worst].amount))
			value := kept[i].score +
				0.12*math.Log1p(float64(kept[i].amount))
			if value > worstValue {
				worst = i
			}
		}

		removed := kept[worst]
		removed.active = false
		kept = append(kept[:worst], kept[worst+1:]...)
		if removed == label {
			labels[key] = kept
			return false
		}
	}

	labels[key] = kept
	return true
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	target := &candidateLabel{
		node:   r.spec.Target,
		amount: deliver,
		active: true,
	}

	labels := make(map[candidateLabelKey][]*candidateLabel)
	labels[candidateLabelKey{
		node: r.spec.Target,
		hops: 0,
	}] = []*candidateLabel{target}

	queue := &candidateQueue{}
	heap.Push(queue, target)

	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item)
			if err != nil {
				item.active = false
				continue
			}

			return rt, item.risk, nil
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}
			if sending <= 0 {
				continue
			}

			riskCost := -math.Log(probability)
			feeCost := 5.5 * float64(fee) / feeScale
			hopCost := 0.075
			useCost := 0.055 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.edgePenalty(edge, item.amount)

			label := &candidateLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + riskCost + feeCost +
					hopCost + useCost + penalty,
				risk:  item.risk + riskCost,
				hops:  item.hops + 1,
				edge:  edge,
				child: item,
			}

			if candidateInsertLabel(labels, label) {
				heap.Push(queue, label)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	sourceLabel *candidateLabel) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for label := sourceLabel; label.node != r.spec.Target; {
		if visited[label.node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[label.node] = true

		if label.edge == nil || label.child == nil {
			return nil, fmt.Errorf(
				"broken path at %v", label.node,
			)
		}

		path = append(path, label.edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		label = label.child
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt < minimum || amt > maximum || amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func (r *candidateRouter) candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 32)

	amounts = candidateAppendUnique(
		amounts, amt, minimum, amt,
	)
	amounts = candidateAppendUnique(
		amounts, minimum, minimum, amt,
	)

	limit := partsLeft
	if limit > 24 {
		limit = 24
	}
	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
			minimum, amt,
		)
	}

	for _, fraction := range []float64{
		0.85, 0.72, 0.60, 0.48, 0.38, 0.30, 0.22, 0.16,
	} {
		shard := lnwire.MilliSatoshi(float64(amt) * fraction)
		amounts = candidateAppendUnique(
			amounts, shard, minimum, amt,
		)
	}

	// Explicitly test amounts below known failures. These candidates often
	// recover depleted-mode channels without forcing the search onto a much
	// longer path.
	for _, failedAt := range r.sessionFailed {
		for _, fraction := range []float64{0.72, 0.48, 0.27, 0.12} {
			shard := lnwire.MilliSatoshi(
				float64(failedAt) * fraction,
			)
			amounts = candidateAppendUnique(
				amounts, shard, minimum, amt,
			)
		}
	}

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := r.candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 4.5 * float64(fee) /
			math.Max(float64(shard), 1)
		hopPenalty := 0.0075 * float64(len(rt.Hops))

		// Reliability dominates. Progress only breaks ties between routes
		// whose probabilities are reasonably close.
		utility := math.Log(math.Max(probability, 1e-12)) +
			0.24*progress - feePenalty - hopPenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}

		if probability >= 0.82 && shard >= amt*3/5 {
			bestRoute = rt
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.12
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+0.65, 4,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.10

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.28
		if i > len(keys)/2 {
			penalty = 0.42
		}
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 3,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 8
		}

		return nil
	}

	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 12
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateKnowledgeKey struct {
	network string
	edge    candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	proportional := (amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million

	return e.baseFeeMsat + proportional
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateKnowledgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateKnowledgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Recent evidence remains valuable across adjacent payments, while
	// background traffic gradually returns the belief to its prior.
	const halfLifeMinutes = 18.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	age := now.Sub(b.updatedAt)
	b.conf = conf

	// Bounds are exact within a short observation window. After that they
	// become a point estimate because background payments may have moved funds.
	if age > 8*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	network string, edge *candidateEdge) candidateLiquidityBelief {

	key := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{capacity: edge.capacity}
	}

	return b
}

func candidateStorePair(
	network string, key candidateEdgeKey,
	forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	forwardKey := candidateKnowledgeKey{
		network: network,
		edge:    key,
	}
	candidateKnowledge.beliefs[forwardKey] = forward

	reverseEdge := candidateReverseKey(key)
	reverseKey := candidateKnowledgeKey{
		network: network,
		edge:    reverseEdge,
	}
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.82)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	knowledgeKey := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[knowledgeKey],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	knowledgeKey := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[knowledgeKey],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// Under a bimodal prior, a liquidity failure is evidence that the
	// direction is close to its depleted mode.
	estimate := amt / 24
	floor := edge.capacity / 1000
	if floor < 1 {
		floor = 1
	}
	if estimate > floor {
		estimate = floor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	knowledgeKey := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[knowledgeKey],
		edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}

	b.estimate -= amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view      routing.SimNetworkView
	networkID string
	source    route.Vertex
	spec      *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32
	routeUses      map[uint64]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		networkID:      fmt.Sprintf("%T:%p", view, view),
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		routeUses:      make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.005, math.Min(probability, 0.995))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	lowMode := 0.49 * math.Exp(-ratio/0.022)
	highMode := 0.495 /
		(1 + math.Exp((ratio-0.91)/0.042))

	return candidateClampProbability(
		0.005 + lowMode + highMode,
	)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.005
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.8)
		probability = 0.75*bounded + 0.25*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(r.networkID, edge)
	conf := candidateBeliefConfidence(b, r.view.Now())

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.70:
			probability *= 0.025
		case ratio > 0.45:
			probability *= 0.12
		case ratio > 0.25:
			probability *= 0.38
		case ratio > 0.10:
			probability *= 0.72
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 7 * float64(fee) / feeScale
			hopCost := 0.14
			useCost := 0.12 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.sessionPenalty[edge.key]

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 24)
	amounts = candidateAppendUnique(amounts, amt)

	for _, numerator := range []int64{80, 65, 50, 40, 30, 22, 16} {
		shard := lnwire.MilliSatoshi(
			(int64(amt)*numerator + 99) / 100,
		)
		amounts = candidateAppendUnique(amounts, shard)
	}

	limit := partsLeft
	if limit > 16 {
		limit = 16
	}
	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	amounts = candidateAppendUnique(
		amounts, candidateCeilDiv(amt, partsLeft),
	)

	return amounts
}

func candidateRouteHash(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, hop := range rt.Hops {
		hash ^= hop.ChannelID
		hash *= prime
	}

	return hash
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}

	r.routeUses[candidateRouteHash(rt)]++
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		if shard < minimum {
			continue
		}

		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log1p(
			float64(shard) / math.Max(float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 5 * float64(fee) /
			math.Max(float64(shard), 1)
		repeatPenalty := 0.55 * math.Min(
			float64(r.routeUses[candidateRouteHash(rt)]), 6,
		)
		longPenalty := 0.035 * math.Max(
			float64(len(rt.Hops)-6), 0,
		)

		utility := math.Log(math.Max(probability, 1e-12)) +
			0.72*progress - feePenalty -
			repeatPenalty - longPenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.12
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.8, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.08

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	last := len(keys) - 1
	for i, key := range keys {
		penalty := 1.0
		if i == 0 {
			penalty = 0.35
		} else if i >= last-1 {
			penalty = 1.5
		}

		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 8,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		balance := r.localBalances[first.chanID]
		if balance > amounts[0] {
			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				r.networkID, edge,
				amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// An unattributed failure should diversify the next route without
	// corrupting persistent liquidity evidence.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)
	beliefHalfLife = int64(30 * 60 * 1_000_000_000)
)

type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type channelKey struct {
	world uint64
	graph uint64
	chanID uint64
	from  route.Vertex
}

type directedLookup struct {
	chanID uint64
	from   route.Vertex
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	confidence float64
	updated    int64
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[channelKey]liquidityBelief
}{
	values: make(map[channelKey]liquidityBelief),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[directedLookup]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	reserved       map[directedLookup]lnwire.MilliSatoshi
	pending        map[*route.Route]map[directedLookup]lnwire.MilliSatoshi

	beliefs  map[directedLookup]liquidityBelief
	loaded   map[directedLookup]bool
	policyBad map[directedLookup]bool
	penalty   map[directedLookup]float64

	worldID uint64
	graphID uint64
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	balanceCopy := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balanceCopy[chanID] = balance
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[directedLookup]*candidateEdge),
		localBalances:  balanceCopy,
		reserved:       make(map[directedLookup]lnwire.MilliSatoshi),
		pending:        make(map[*route.Route]map[directedLookup]lnwire.MilliSatoshi),
		beliefs:        make(map[directedLookup]liquidityBelief),
		loaded:         make(map[directedLookup]bool),
		policyBad:      make(map[directedLookup]bool),
		penalty:        make(map[directedLookup]float64),
		worldID:        simulationIdentity(view),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	var graphHash uint64
	var edgeCount uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				r.edgeLookup[directedLookup{
					chanID: edge.chanID,
					from:   edge.from,
				}] = edge

				graphHash ^= edgeFingerprint(edge)
				edgeCount++

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.graphID = mix64(graphHash ^ mix64(edgeCount))

	return r, nil
}

func simulationIdentity(view routing.SimNetworkView) uint64 {
	value := reflect.ValueOf(view)
	if !value.IsValid() {
		return 0
	}

	switch value.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Func,
		reflect.Chan, reflect.UnsafePointer:

		return uint64(value.Pointer())
	default:
		return 0
	}
}

func edgeFingerprint(edge *candidateEdge) uint64 {
	hash := mix64(edge.chanID) ^
		mix64(uint64(edge.capacity)) ^
		mix64(uint64(edge.baseFeeMsat)) ^
		mix64(uint64(edge.feeRatePPM)) ^
		mix64(uint64(edge.timeLockDelta))

	for i, value := range edge.from {
		hash ^= mix64(uint64(value) + uint64(i+1)*0x9e3779b97f4a7c15)
	}
	for i, value := range edge.to {
		hash ^= mix64(uint64(value) + uint64(i+37)*0x517cc1b727220a95)
	}

	return mix64(hash)
}

func mix64(value uint64) uint64 {
	value ^= value >> 30
	value *= 0xbf58476d1ce4e5b9
	value ^= value >> 27
	value *= 0x94d049bb133111eb
	value ^= value >> 31

	return value
}

func (r *candidateRouter) now() int64 {
	return r.view.Now().UnixNano()
}

func (r *candidateRouter) sharedKey(key directedLookup) channelKey {
	return channelKey{
		world:  r.worldID,
		graph:  r.graphID,
		chanID: key.chanID,
		from:   key.from,
	}
}

func (r *candidateRouter) belief(key directedLookup) liquidityBelief {
	if r.loaded[key] {
		return r.beliefs[key]
	}

	r.loaded[key] = true

	sharedBeliefs.Lock()
	belief := sharedBeliefs.values[r.sharedKey(key)]
	sharedBeliefs.Unlock()

	r.beliefs[key] = belief

	return belief
}

func (r *candidateRouter) storeBelief(key directedLookup,
	belief liquidityBelief) {

	r.loaded[key] = true
	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[r.sharedKey(key)] = belief
	sharedBeliefs.Unlock()
}

func beliefWeight(belief liquidityBelief, now int64) float64 {
	if belief.confidence <= 0 {
		return 0
	}
	if belief.updated > now {
		return 0
	}

	age := now - belief.updated
	weight := belief.confidence *
		math.Exp(-float64(age)/float64(beliefHalfLife))

	return math.Min(0.985, math.Max(0, weight))
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-ratio/0.07)
	highMode := 0.50 / (1 + math.Exp((ratio-0.90)/0.06))
	probability := lowMode + highMode

	return math.Min(0.985, math.Max(0.005, probability))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		return 0.999
	}

	key := directedLookup{
		chanID: edge.chanID,
		from:   edge.from,
	}
	belief := r.belief(key)
	prior := bimodalPrior(amt, edge.capacity)
	weight := beliefWeight(belief, r.now())
	if weight == 0 {
		return prior
	}

	evidence := prior
	switch {
	case belief.lowerOK > 0 && amt <= belief.lowerOK:
		evidence = 0.995

	case belief.upperFail > 0 && amt >= belief.upperFail:
		evidence = 0.005

	case belief.estimate > 0:
		width := math.Max(
			float64(edge.capacity)*0.075,
			1_000_000,
		)
		distance := (float64(amt) - float64(belief.estimate)) /
			width
		evidence = 1 / (1 + math.Exp(distance))
		evidence = math.Min(0.995, math.Max(0.005, evidence))
	}

	probability := (1-weight)*prior + weight*evidence

	return math.Min(0.995, math.Max(0.005, probability))
}

func (r *candidateRouter) freshFailureExcludes(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	key := directedLookup{
		chanID: edge.chanID,
		from:   edge.from,
	}
	belief := r.belief(key)
	if belief.upperFail <= 0 {
		return false
	}

	weight := beliefWeight(belief, r.now())
	retryThreshold := belief.upperFail * 9 / 10

	return weight >= 0.72 && amt >= retryThreshold
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	dist := make(map[route.Vertex]float64)
	arrival := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	arrival[r.spec.Target] = amt

	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		best, ok := dist[item.node]
		if !ok || item.score > best+0.001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			key := directedLookup{
				chanID: edge.chanID,
				from:   edge.from,
			}
			if r.policyBad[key] {
				continue
			}

			reserved := r.reserved[key]
			requiredLiquidity := item.amount + reserved
			if !edge.usable(requiredLiquidity) {
				continue
			}
			if r.freshFailureExcludes(edge, requiredLiquidity) {
				continue
			}

			if edge.from == r.source {
				available := r.localBalances[edge.chanID]
				if available < requiredLiquidity {
					continue
				}
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			risk := 0.0

			if edge.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee

				probability := r.probability(
					edge, requiredLiquidity,
				)
				riskScale := math.Max(
					100_000,
					float64(item.amount)*0.008,
				)
				risk = -math.Log(probability) * riskScale
			}

			historyPenalty := r.penalty[key] *
				math.Max(50_000, float64(item.amount)*0.003)
			score := item.score + float64(fee) + risk +
				historyPenalty

			oldScore, exists := dist[edge.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.from] = score
			arrival[edge.from] = sending
			next[edge.from] = edge
			heap.Push(queue, &dijkstraItem{
				node:   edge.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	candidates := []lnwire.MilliSatoshi{
		amt,
		amt * 13 / 20,
		amt * 9 / 20,
		amt * 3 / 10,
		amt / 5,
		minimum,
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	var lastErr error

	for _, candidate := range candidates {
		if candidate < minimum {
			candidate = minimum
		}
		if candidate > amt || candidate <= 0 || seen[candidate] {
			continue
		}
		seen[candidate] = true

		rt, err := r.findRoute(candidate)
		if err != nil {
			lastErr = err
			continue
		}

		r.reserveRoute(rt)

		return rt, nil
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func routeEdgeAmount(rt *route.Route, edgeIndex int) lnwire.MilliSatoshi {
	if edgeIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[edgeIndex-1].AmtToForward
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []struct {
	key    directedLookup
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
} {

	result := make([]struct {
		key    directedLookup
		edge   *candidateEdge
		amount lnwire.MilliSatoshi
	}, 0, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := directedLookup{
			chanID: hop.ChannelID,
			from:   from,
		}
		result = append(result, struct {
			key    directedLookup
			edge   *candidateEdge
			amount lnwire.MilliSatoshi
		}{
			key:    key,
			edge:   r.edgeLookup[key],
			amount: routeEdgeAmount(rt, i),
		})
		from = hop.PubKeyBytes
	}

	return result
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	reservation := make(map[directedLookup]lnwire.MilliSatoshi)

	for _, routeEdge := range r.routeEdges(rt) {
		reservation[routeEdge.key] += routeEdge.amount
		r.reserved[routeEdge.key] += routeEdge.amount
	}

	r.pending[rt] = reservation
}

func (r *candidateRouter) releaseRoute(rt *route.Route) {
	reservation, ok := r.pending[rt]
	if !ok {
		return
	}

	for key, amount := range reservation {
		if r.reserved[key] <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amount
		}
	}

	delete(r.pending, rt)
}

func (r *candidateRouter) recordPass(edge *candidateEdge,
	amount lnwire.MilliSatoshi) {

	if edge == nil || edge.from == r.source {
		return
	}

	key := directedLookup{
		chanID: edge.chanID,
		from:   edge.from,
	}
	belief := r.belief(key)

	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	estimate := amount * 23 / 20
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.confidence = math.Max(belief.confidence, 0.88)
	belief.updated = r.now()
	r.storeBelief(key, belief)
}

func (r *candidateRouter) recordFailure(edge *candidateEdge,
	amount lnwire.MilliSatoshi) {

	if edge == nil {
		return
	}

	key := directedLookup{
		chanID: edge.chanID,
		from:   edge.from,
	}

	if edge.from == r.source {
		if amount > 0 && r.localBalances[edge.chanID] >= amount {
			r.localBalances[edge.chanID] = amount - 1
		}
		return
	}

	belief := r.belief(key)
	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	failureEstimate := amount / 4
	if belief.estimate == 0 || failureEstimate < belief.estimate {
		belief.estimate = failureEstimate
	}

	belief.confidence = 0.97
	belief.updated = r.now()
	r.storeBelief(key, belief)
	r.penalty[key] += 1
}

func (r *candidateRouter) recordSettlement(edge *candidateEdge,
	amount lnwire.MilliSatoshi) {

	if edge == nil {
		return
	}

	if edge.from == r.source {
		if balance := r.localBalances[edge.chanID]; balance > amount {
			r.localBalances[edge.chanID] = balance - amount
		} else {
			r.localBalances[edge.chanID] = 0
		}
		return
	}

	key := directedLookup{
		chanID: edge.chanID,
		from:   edge.from,
	}
	belief := r.belief(key)

	highEstimate := edge.capacity * 9 / 10
	if belief.estimate < highEstimate {
		belief.estimate = highEstimate
	}
	if belief.estimate > amount {
		belief.estimate -= amount
	} else {
		belief.estimate = 0
	}

	if belief.lowerOK > amount {
		belief.lowerOK -= amount
	} else {
		belief.lowerOK = 0
	}
	if belief.upperFail > amount {
		belief.upperFail -= amount
	} else {
		belief.upperFail = 0
	}

	belief.confidence = math.Max(belief.confidence, 0.82)
	belief.updated = r.now()
	r.storeBelief(key, belief)

	reverseKey := directedLookup{
		chanID: edge.chanID,
		from:   edge.to,
	}
	reverseEdge := r.edgeLookup[reverseKey]
	if reverseEdge == nil {
		return
	}

	reverse := r.belief(reverseKey)
	reverse.lowerOK += amount
	if reverse.lowerOK > reverseEdge.capacity {
		reverse.lowerOK = reverseEdge.capacity
	}
	reverse.estimate += amount
	if reverse.estimate > reverseEdge.capacity {
		reverse.estimate = reverseEdge.capacity
	}
	if reverse.upperFail > 0 {
		reverse.upperFail += amount
		if reverse.upperFail > reverseEdge.capacity {
			reverse.upperFail = reverseEdge.capacity
		}
	}
	reverse.confidence = math.Max(reverse.confidence, 0.80)
	reverse.updated = r.now()
	r.storeBelief(reverseKey, reverse)
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	r.releaseRoute(rt)
	edges := r.routeEdges(rt)

	if result.Failure == nil {
		for _, routeEdge := range edges {
			r.recordPass(routeEdge.edge, routeEdge.amount)
			r.recordSettlement(routeEdge.edge, routeEdge.amount)
		}

		return nil
	}

	failIndex := failureOutgoingIndex(rt, result.FailureSource)

	if failIndex >= 0 {
		for i := 0; i < failIndex && i < len(edges); i++ {
			r.recordPass(edges[i].edge, edges[i].amount)
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(edges) {
		failed := edges[failIndex]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.recordFailure(failed.edge, failed.amount)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyBad[failed.key] = true
			r.penalty[failed.key] += 4

		default:
			r.policyBad[failed.key] = true
			r.penalty[failed.key] += 2
		}

		return nil
	}

	for _, routeEdge := range edges {
		r.penalty[routeEdge.key] += 0.35
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
	candidateLabelsPerNode  = 6
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateKnowledgeKey struct {
	scope string
	edge  candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	scope    string
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateKnowledgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateKnowledgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Evidence decays quickly enough to tolerate active background traffic.
	const halfLifeMinutes = 14.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	b.conf = conf

	// Old bounds are discarded while the softer estimate continues to decay.
	if now.Sub(b.updatedAt) > 12*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	scope string, key candidateEdgeKey,
	forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)

	forwardKey := candidateKnowledgeKey{
		scope: scope,
		edge:  key,
	}
	candidateKnowledge.beliefs[forwardKey] = forward

	reverseKey := candidateKnowledgeKey{
		scope: scope,
		edge:  candidateReverseKey(key),
	}
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.86)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 93 / 100
	if estimate < amt {
		estimate = amt
	}
	if estimate > b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(
		edge.scope, edge.key, b, edge.capacity,
	)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	estimate := amt / 20
	floor := edge.capacity / 1000
	if floor < 1 {
		floor = 1
	}
	if estimate > floor {
		estimate = floor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(
		edge.scope, edge.key, b, edge.capacity,
	)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key],
		edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 93 / 100
		if b.estimate < amt {
			b.estimate = amt
		}
	}
	b.estimate -= amt

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(
		edge.scope, edge.key, b, edge.capacity,
	)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec
	scope  string

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		scope:          fmt.Sprintf("%p", view),
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					scope:    r.scope,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.003, math.Min(probability, 0.997))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The two modes represent a nearly depleted and a nearly full direction.
	lowMode := 0.485 * math.Exp(-ratio/0.022)
	highMode := 0.505 /
		(1 + math.Exp((ratio-0.925)/0.042))

	return candidateClampProbability(
		0.004 + lowMode + highMode,
	)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.997
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.003
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.003 +
			0.994*math.Pow(1-fraction, 2.8)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9998
	}

	if failedAt := r.sessionFailed[edge.key]; failedAt != 0 {
		if amt >= failedAt {
			return 0
		}
		if float64(amt)/float64(failedAt) > 0.78 {
			return 0.003
		}
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())
	if conf == 0 {
		return prior
	}

	learned := candidateLearnedProbability(
		b, amt, edge.capacity,
	)
	probability := conf*learned + (1-conf)*prior

	if failedAt := r.sessionFailed[edge.key]; failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.60:
			probability *= 0.06
		case ratio > 0.40:
			probability *= 0.22
		case ratio > 0.20:
			probability *= 0.55
		default:
			probability *= 0.85
		}
	}

	return candidateClampProbability(probability)
}

type candidateSearchLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
	path   []*candidateEdge
	alive  bool
	index  int
}

type candidateQueue []*candidateSearchLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].amount != q[j].amount {
		return q[i].amount < q[j].amount
	}

	return q[i].hops < q[j].hops
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateQueue) Push(value any) {
	item := value.(*candidateSearchLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	last.index = -1
	*q = old[:len(old)-1]

	return last
}

func candidatePathContains(
	path []*candidateEdge, node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}

	return false
}

func candidateDominates(
	a, b *candidateSearchLabel) bool {

	return a.score <= b.score+1e-12 &&
		a.amount <= b.amount &&
		a.hops <= b.hops
}

func candidateAddLabel(
	labels map[route.Vertex][]*candidateSearchLabel,
	label *candidateSearchLabel) bool {

	existing := labels[label.node]
	for _, other := range existing {
		if other.alive && candidateDominates(other, label) {
			return false
		}
	}

	kept := existing[:0]
	for _, other := range existing {
		if candidateDominates(label, other) {
			other.alive = false
			continue
		}
		if other.alive {
			kept = append(kept, other)
		}
	}
	existing = kept

	if len(existing) >= candidateLabelsPerNode {
		worst := 0
		worstValue := math.Inf(-1)

		for i, other := range existing {
			value := other.score +
				0.06*float64(other.hops) +
				1e-12*float64(other.amount)
			if value > worstValue {
				worstValue = value
				worst = i
			}
		}

		newValue := label.score +
			0.06*float64(label.hops) +
			1e-12*float64(label.amount)
		if newValue >= worstValue {
			return false
		}

		existing[worst].alive = false
		existing = append(
			existing[:worst], existing[worst+1:]...,
		)
	}

	label.alive = true
	labels[label.node] = append(existing, label)

	return true
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	labels := make(map[route.Vertex][]*candidateSearchLabel)
	queue := &candidateQueue{}

	start := &candidateSearchLabel{
		node:   r.spec.Target,
		amount: deliver,
		alive:  true,
	}
	labels[start.node] = []*candidateSearchLabel{start}
	heap.Push(queue, start)

	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateSearchLabel)
		if !item.alive {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item.path)
			if err != nil {
				return nil, 0, err
			}

			return rt, item.risk, nil
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 6.5 * float64(fee) / feeScale
			hopCost := 0.035
			useCost := 0.12 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			label := &candidateSearchLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + riskCost + feeCost +
					hopCost + useCost +
					r.sessionPenalty[edge.key],
				risk: item.risk + riskCost,
				hops: item.hops + 1,
				path: path,
			}

			if candidateAddLabel(labels, label) {
				heap.Push(queue, label)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}
	if len(path) > candidateMaxRouteHops {
		return nil, errors.New("selected route is too long")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("selected route has invalid endpoints")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, errors.New("selected route is disconnected")
		}
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 24)
	amounts = candidateAppendUnique(amounts, amt)

	limit := partsLeft
	if limit > 18 {
		limit = 18
	}

	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	amounts = candidateAppendUnique(
		amounts, candidateCeilDiv(amt, partsLeft),
	)

	return amounts
}

func (r *candidateRouter) addFailureSizedShards(
	amounts []lnwire.MilliSatoshi, remaining,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	for _, failedAt := range r.sessionFailed {
		for _, factor := range []int64{72, 55, 40, 25} {
			shard := lnwire.MilliSatoshi(
				int64(failedAt) * factor / 100,
			)
			if shard < minimum || shard > remaining {
				continue
			}
			amounts = candidateAppendUnique(amounts, shard)
		}
	}

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)
	shards = r.addFailureSizedShards(shards, amt, minimum)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 5.0 * float64(fee) /
			math.Max(float64(shard), 1)
		partPenalty := 0.025 *
			float64(partsLeft-1)

		utility := math.Log(math.Max(probability, 1e-12)) +
			0.72*progress - feePenalty - partPenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}

		if probability >= 0.72 && shard >= amt*2/3 {
			bestRoute = rt
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.15
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.8, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.10

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		position := float64(i+1) / float64(len(keys))
		penalty := 0.8 + 0.8*position
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 7,
		)
		r.edgeUses[key] += 2
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		balance := r.localBalances[first.chanID]
		if balance > amounts[0] {
			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 30

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
	candidateLabelsPerNode  = 6
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateKnowledgeKey struct {
	network uintptr
	edge    candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateKnowledgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateKnowledgeKey]candidateLiquidityBelief),
}

func candidateNetworkID(view routing.SimNetworkView) uintptr {
	value := reflect.ValueOf(view)
	switch value.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Func,
		reflect.Chan, reflect.UnsafePointer:

		if !value.IsNil() {
			return value.Pointer()
		}
	}

	return 0
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.99))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Directional liquidity evidence decays because background payments can
	// move funds between observations.
	const halfLifeMinutes = 18.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	b.conf = conf

	// Recent bounds remain strong. Older observations retain only their
	// confidence-weighted point estimate.
	if now.Sub(b.updatedAt) > 8*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	network uintptr,
	edge *candidateEdge) candidateLiquidityBelief {

	key := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{capacity: edge.capacity}
	}

	return b
}

func candidateStorePair(
	network uintptr, edgeKey candidateEdgeKey,
	forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)

	key := candidateKnowledgeKey{
		network: network,
		edge:    edgeKey,
	}
	candidateKnowledge.beliefs[key] = forward

	reverseEdge := candidateReverseKey(edgeKey)
	reverseKey := candidateKnowledgeKey{
		network: network,
		edge:    reverseEdge,
	}
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.80)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	network uintptr, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.93)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	network uintptr, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	estimate := amt / 24
	floor := edge.capacity / 1000
	if floor < 1 {
		floor = 1
	}
	if estimate > floor {
		estimate = floor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	network uintptr, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}
	b.estimate -= amt

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view      routing.SimNetworkView
	networkID uintptr
	source    route.Vertex
	spec      *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		networkID:      candidateNetworkID(view),
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.005, math.Min(probability, 0.995))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode models nearly empty directions while the high mode
	// models directions holding almost the entire channel balance.
	lowMode := 0.485 * math.Exp(-ratio/0.022)
	highMode := 0.505 /
		(1 + math.Exp((ratio-0.925)/0.042))

	return candidateClampProbability(0.004 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		return 0.005
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		span := math.Max(
			float64(b.upperFail-b.lowerOK), 1,
		)
		fraction := (float64(amt) - float64(b.lowerOK)) / span
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.8)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		if failedAt == 0 {
			return 0.9995
		}

		ratio := float64(amt) / float64(failedAt)
		return candidateClampProbability(
			0.9995 * math.Pow(math.Max(1-ratio, 0.01), 0.35),
		)
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(r.networkID, edge)
	conf := candidateBeliefConfidence(b, r.view.Now())

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.70:
			probability *= 0.025
		case ratio > 0.45:
			probability *= 0.14
		case ratio > 0.22:
			probability *= 0.48
		default:
			probability *= 0.82
		}
	}

	return candidateClampProbability(probability)
}

type candidateLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
	path   []*candidateEdge
	active bool
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func candidatePathContains(
	path []*candidateEdge, vertex route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == vertex || edge.key.to == vertex {
			return true
		}
	}

	return false
}

func candidateDominates(a, b *candidateLabel) bool {
	return a.active &&
		a.score <= b.score+1e-12 &&
		a.amount <= b.amount &&
		a.hops <= b.hops
}

func candidateInsertLabel(
	labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	current := labels[label.node]
	for _, existing := range current {
		if candidateDominates(existing, label) {
			return false
		}
	}

	kept := current[:0]
	for _, existing := range current {
		if candidateDominates(label, existing) {
			existing.active = false
			continue
		}
		kept = append(kept, existing)
	}
	kept = append(kept, label)

	if len(kept) > candidateLabelsPerNode {
		worst := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].score > kept[worst].score ||
				(kept[i].score == kept[worst].score &&
					kept[i].amount > kept[worst].amount) {

				worst = i
			}
		}

		if kept[worst] == label {
			return false
		}

		kept[worst].active = false
		kept = append(kept[:worst], kept[worst+1:]...)
	}

	label.active = true
	labels[label.node] = kept

	return true
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	start := &candidateLabel{
		node:   r.spec.Target,
		amount: deliver,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {start},
	}
	queue := &candidateQueue{start}
	heap.Init(queue)

	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item.path)
			if err != nil {
				return nil, 0, err
			}

			return rt, item.risk, nil
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			sending := item.amount
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 7.0 * float64(fee) / feeScale
			hopCost := 0.14
			if item.hops >= 10 {
				hopCost += 0.035 * float64(item.hops-9)
			}
			useCost := 0.075 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			next := &candidateLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + riskCost + feeCost +
					hopCost + useCost +
					r.sessionPenalty[edge.key],
				risk: item.risk + riskCost,
				hops: item.hops + 1,
				path: path,
			}

			if candidateInsertLabel(labels, next) {
				heap.Push(queue, next)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}
	if len(path) > candidateMaxRouteHops {
		return nil, errors.New("selected route is too long")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("selected route misses target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(candidateFinalCltvDelta)
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 24)

	// Reliability-first candidates come first, while every candidate is large
	// enough to leave the payment completable within the remaining part slots.
	amounts = candidateAppendUnique(amounts, minimum)

	factors := []float64{
		1.18, 1.40, 1.70, 2.0, 2.5, 3.0, 4.0, 6.0, 8.0,
	}
	for _, factor := range factors {
		candidate := lnwire.MilliSatoshi(
			math.Ceil(float64(minimum) * factor),
		)
		if candidate < amt {
			amounts = candidateAppendUnique(amounts, candidate)
		}
	}

	limit := partsLeft
	if limit > 16 {
		limit = 16
	}
	for divisor := limit; divisor >= 2; divisor-- {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, divisor),
		)
	}

	return candidateAppendUnique(amounts, amt)
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 5.0 * float64(fee) /
			math.Max(float64(shard), 1)
		longPenalty := 0.018 *
			math.Max(float64(len(rt.Hops)-8), 0)

		utility := math.Log(math.Max(probability, 1e-12)) +
			0.24*progress - feePenalty - longPenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}

		if probability >= 0.72 && shard >= amt/2 {
			bestRoute = rt
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.18
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.65, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}
	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.12

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.65
		if i >= len(keys)/2 {
			penalty = 0.85
		}
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 5,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				r.networkID, edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

			// A local failure is stronger than the initial balance snapshot.
			if edge.key.from == r.source {
				upper := amounts[failIndex] - 1
				if upper < 0 {
					upper = 0
				}
				if r.localBalances[key.chanID] > upper {
					r.localBalances[key.chanID] = upper
				}
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// Unknown-source failures drive path exploration without contaminating
	// persistent channel liquidity observations.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity lnwire.MilliSatoshi

	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi

	confidence float64
	updatedAt  time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0

	case amt > capacity:
		return capacity

	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.confidence = math.Max(0, math.Min(b.confidence, 0.995))

	return b
}

func candidateEvidenceWeight(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.confidence <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Recent attempt feedback should dominate within a payment, while
	// evidence from earlier payments becomes a soft hint as traffic moves.
	const halfLifeMinutes = 12.0

	weight := b.confidence *
		math.Exp(-math.Ln2*age/halfLifeMinutes)

	if weight < 0.015 {
		return 0
	}

	return weight
}

func candidatePrepareBelief(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	weight := candidateEvidenceWeight(b, now)
	if weight == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	b.confidence = weight

	// Old bounds are not physical bounds in a moving network. Preserve the
	// estimate, but let the prior and fresh observations override them.
	age := now.Sub(b.updatedAt)
	if age > 8*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareBelief(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.confidence = math.Max(
		reverse.confidence, forward.confidence*0.82,
	)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareBelief(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if estimate > b.estimate {
		b.estimate = estimate
	}

	b.confidence = math.Max(b.confidence, 0.95)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareBelief(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A directional miss is strong evidence for the depleted mode, but
	// retaining a small amount permits useful lower-amount retries.
	estimate := amt / 12
	depletedMode := edge.capacity / 400
	if depletedMode < 1 {
		depletedMode = 1
	}
	if estimate > depletedMode {
		estimate = depletedMode
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.confidence = math.Max(b.confidence, 0.99)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareBelief(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	estimate := b.estimate
	if estimate < amt {
		estimate = edge.capacity * 9 / 10
		if estimate < amt {
			estimate = amt
		}
	}

	b.estimate = estimate - amt

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.confidence = math.Max(b.confidence, 0.96)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.002, math.Min(probability, 0.998))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low-liquidity mode gives tiny HTLCs a material chance of passing.
	// The high-liquidity mode remains nearly flat until its capacity cliff.
	lowMode := 0.47 * math.Exp(-ratio/0.018)
	highMode := 0.515 /
		(1 + math.Exp((ratio-0.91)/0.038))

	return candidateClampProbability(0.003 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.998
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.002
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.022, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.002 + 0.996*
			math.Pow(1-fraction, 2.8)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9998
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	confidence := candidateEvidenceWeight(b, r.view.Now())

	probability := prior
	if confidence > 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = confidence*learned +
			(1-confidence)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)

		switch {
		case ratio > 0.72:
			probability *= 0.025

		case ratio > 0.50:
			probability *= 0.10

		case ratio > 0.30:
			probability *= 0.32

		case ratio > 0.12:
			probability *= 0.72
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 2_000_000)

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			sending := item.amount
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			if sending <= 0 {
				continue
			}

			riskCost := -math.Log(probability)
			feeCost := 4.0 * float64(fee) / feeScale
			hopCost := 0.022

			uses := float64(r.edgeUses[edge.key])
			useCost := 0.0
			if uses > 0 {
				// Reusing an edge is reasonable after evidence of success,
				// but repeated unproductive routes must quickly give way to
				// alternatives.
				useCost = 0.075 * math.Min(uses, 12)
				if r.sessionLower[edge.key] >= item.amount {
					useCost *= 0.12
				}
			}

			capacityRatio := float64(item.amount) /
				math.Max(float64(edge.capacity), 1)
			capacityCost := 0.025 * capacityRatio

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + capacityCost +
				r.sessionPenalty[edge.key]

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 18)

	// Start with amounts that preserve enough part slots to complete the
	// payment. Dense coverage near the minimum is valuable because depleted
	// bimodal channels often still pass a much smaller retry.
	multipliers := []float64{
		1.0, 1.15, 1.35, 1.6, 2.0, 2.5, 3.2, 4.0,
	}

	for _, multiplier := range multipliers {
		shard := lnwire.MilliSatoshi(
			math.Ceil(float64(minimum) * multiplier),
		)
		if shard > amt {
			shard = amt
		}
		amounts = candidateAppendUnique(amounts, shard)
	}

	for parts := partsLeft; parts >= 2; parts-- {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
		if parts == 2 {
			break
		}
	}

	amounts = candidateAppendUnique(amounts, amt)

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey

	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		fee := rt.TotalAmount - shard

		progress := math.Log(
			1 + float64(shard)/math.Max(float64(minimum), 1),
		)
		feePenalty := 3.0 * float64(fee) /
			math.Max(float64(shard), 1)

		// Success probability dominates. Progress is still rewarded enough
		// to avoid needless dust-like parts when two candidates are similarly
		// reliable.
		utility := math.Log(math.Max(probability, 1e-15)) +
			0.34*progress - feePenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.08
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.8, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.05

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		position := float64(i+1) / float64(len(keys))
		penalty := 0.9 + 0.8*position

		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 7,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		balance := r.localBalances[first.chanID]
		if balance > amounts[0] {
			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 30

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// An unattributed failure should cause broad route exploration without
	// turning uncertain feedback into persistent liquidity evidence.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 64
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	proportional := (amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million

	return e.baseFeeMsat + proportional
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}

	return amt
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	if b.conf < 0 {
		b.conf = 0
	}
	if b.conf > 0.99 {
		b.conf = 0.99
	}

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Directional liquidity can move substantially between payments.
	const halfLifeMinutes = 10.0
	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	b.conf = conf

	// Old bounds are useful as estimates, but no longer as hard facts.
	if now.Sub(b.updatedAt) > 6*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.85)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	// Under a bimodal prior, observing a pass strongly favors the high mode.
	highEstimate := edge.capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.conf = math.Max(b.conf, 0.92)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity failure strongly favors the depleted mode.
	lowEstimate := amt / 20
	capFloor := edge.capacity / 700
	if capFloor < 1 {
		capFloor = 1
	}
	if lowEstimate > capFloor {
		lowEstimate = capFloor
	}
	if lowEstimate < b.lowerOK {
		lowEstimate = b.lowerOK
	}
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.conf = math.Max(b.conf, 0.98)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	estimate := b.estimate
	if estimate < amt {
		estimate = edge.capacity * 9 / 10
		if estimate < amt {
			estimate = amt
		}
	}

	b.estimate = estimate - amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower     map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed    map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailCount map[candidateEdgeKey]uint8
	sessionBlocked   map[candidateEdgeKey]bool
	sessionPenalty   map[candidateEdgeKey]float64
	edgeUses         map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:             view,
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		edges:            make(map[candidateEdgeKey]*candidateEdge),
		localBalances:    make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailCount: make(map[candidateEdgeKey]uint8),
		sessionBlocked:   make(map[candidateEdgeKey]bool),
		sessionPenalty:   make(map[candidateEdgeKey]float64),
		edgeUses:         make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	if probability < 0.003 {
		return 0.003
	}
	if probability > 0.997 {
		return 0.997
	}

	return probability
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode supplies near-certain probability for tiny HTLCs. The
	// high mode represents channels whose balance sits near full capacity.
	lowMode := 0.49 * math.Exp(-ratio/0.027)
	highMode := 0.50 /
		(1 + math.Exp((ratio-0.91)/0.043))

	return candidateClampProbability(0.003 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.997
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.003
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.03, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(1, fraction))

		bounded := 0.003 + 0.994*math.Pow(1-fraction, 2.7)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	now := r.view.Now()
	conf := candidateBeliefConfidence(b, now)
	if conf != 0 && now.Sub(b.updatedAt) > 6*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt := r.sessionFailed[edge.key]; failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		count := float64(r.sessionFailCount[edge.key])

		switch {
		case ratio >= 1:
			probability *= 0.006 / math.Max(count, 1)
		case ratio > 0.72:
			probability *= 0.025
		case ratio > 0.48:
			probability *= 0.12
		case ratio > 0.25:
			probability *= 0.42
		case ratio > 0.10:
			probability *= 0.72
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 6.5 * float64(fee) / feeScale
			hopCost := 0.045
			useCost := 0.11 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.sessionPenalty[edge.key]

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateScaledAmount(
	amt lnwire.MilliSatoshi, numerator,
	denominator int64) lnwire.MilliSatoshi {

	if denominator <= 0 {
		return 0
	}

	value := int64(amt)
	if value > math.MaxInt64/numerator {
		return amt
	}

	return lnwire.MilliSatoshi(
		(value*numerator + denominator - 1) / denominator,
	)
}

func (r *candidateRouter) shardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 32)
	amounts = candidateAppendUnique(amounts, amt)

	limit := partsLeft
	if limit > 20 {
		limit = 20
	}
	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	// Geometric probes make lower-amount retries available even when MaxParts
	// is small. They are selected only when their probability compensates for
	// the risk of consuming a part with little progress.
	for _, fraction := range [][2]int64{
		{4, 5}, {3, 4}, {2, 3}, {3, 5}, {1, 2},
		{2, 5}, {1, 3}, {1, 4}, {1, 6}, {1, 8},
	} {
		amounts = candidateAppendUnique(
			amounts,
			candidateScaledAmount(
				amt, fraction[0], fraction[1],
			),
		)
	}

	// Probe directly below observed liquidity cliffs.
	for _, failedAt := range r.sessionFailed {
		if failedAt <= 1 {
			continue
		}

		for _, fraction := range [][2]int64{
			{3, 4}, {1, 2}, {1, 3}, {1, 5},
		} {
			probe := candidateScaledAmount(
				failedAt, fraction[0], fraction[1],
			)
			if probe <= amt {
				amounts = candidateAppendUnique(
					amounts, probe,
				)
			}
		}
	}

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := r.shardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log1p(
			float64(shard) / math.Max(float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 5 * float64(fee) /
			math.Max(float64(shard), 1)

		utility := math.Log(math.Max(probability, 1e-12)) +
			0.72*progress - feePenalty

		if shard < minimum {
			shortfall := 1 - float64(shard)/float64(minimum)
			utility -= 0.55 * shortfall
		}

		// Prefer a route that can make meaningful progress when otherwise
		// equivalent, but never at the cost of a large reliability loss.
		if shard >= amt/2 {
			utility += 0.06
		}

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}

	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
		delete(r.sessionFailCount, key)
	}

	r.sessionPenalty[key] *= 0.15
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
		r.sessionFailCount[key] = 1
	} else if r.sessionFailCount[key] < math.MaxUint8 {
		r.sessionFailCount[key]++
	}

	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	increment := 1.15 +
		0.25*math.Min(float64(r.sessionFailCount[key]), 4)
	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+increment, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
		delete(r.sessionFailCount, key)
	}

	r.sessionPenalty[key] *= 0.10

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.75
		if i >= len(keys)/2 {
			penalty = 0.95
		}
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 5,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20
		}

		return nil
	}

	// Unknown failures trigger path exploration without corrupting persistent
	// channel-liquidity observations.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateKnowledgeKey struct {
	scope uint64
	edge  candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	scope    uint64
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateKnowledgeKey]candidateLiquidityBelief
	views   map[uint64]routing.SimNetworkView
}{
	beliefs: make(map[candidateKnowledgeKey]candidateLiquidityBelief),
	views:   make(map[uint64]routing.SimNetworkView),
}

func candidateViewScope(view routing.SimNetworkView) uint64 {
	value := reflect.ValueOf(view)
	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Pointer,
		reflect.Slice, reflect.UnsafePointer:

		if pointer := value.Pointer(); pointer != 0 {
			return uint64(pointer)
		}
	}

	return uint64(uintptr(reflect.ValueOf(&view).Pointer()))
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	const halfLifeMinutes = 18.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	b.conf = conf

	age := now.Sub(b.updatedAt)
	switch {
	case age > 12*time.Minute:
		b.lowerOK = 0
		b.upperFail = 0

	case age > 5*time.Minute:
		// Old bounds remain useful as point-estimate evidence, but they are
		// no longer safe hard constraints in a moving network.
		if b.lowerOK != 0 {
			b.estimate = (b.estimate + b.lowerOK) / 2
		}
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(edge *candidateEdge) candidateLiquidityBelief {
	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{capacity: edge.capacity}
	}

	return b
}

func candidateStorePair(
	edge *candidateEdge, forward candidateLiquidityBelief) {

	forward = candidateNormalizeBelief(forward, edge.capacity)

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  candidateReverseKey(edge.key),
	}
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		edge.capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.82)
	reverse.estimate = edge.capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = edge.capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = edge.capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, edge.capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(edge, b)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	estimate := amt / 20
	floor := edge.capacity / 1000
	if floor < 1 {
		floor = 1
	}
	if estimate > floor {
		estimate = floor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(edge, b)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateKnowledgeKey{
		scope: edge.scope,
		edge:  edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}
	b.estimate -= amt

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(edge, b)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec
	scope  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	failedUses     map[candidateEdgeKey]uint32
	routeFailures  map[uint64]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	scope := candidateViewScope(view)
	candidateKnowledge.Lock()
	candidateKnowledge.views[scope] = view
	candidateKnowledge.Unlock()

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		scope:          scope,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		failedUses:     make(map[candidateEdgeKey]uint32),
		routeFailures:  make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					scope:    scope,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.003, math.Min(probability, 0.997))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// A bimodal balance has roughly half its mass near either endpoint.
	// Tiny HTLCs can pass in either mode, while medium HTLCs principally
	// depend on being on the funded side.
	lowMode := 0.49 * math.Exp(-ratio/0.018)
	highMode := 0.495 /
		(1 + math.Exp((ratio-0.91)/0.04))

	return candidateClampProbability(0.003 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.997
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.003
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.003 + 0.994*math.Pow(1-fraction, 2.8)
		probability = 0.75*bounded + 0.25*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9998
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}
	if r.sessionLower[edge.key] >= amt {
		return 0.999
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	// A failed amount is strong evidence under a bimodal prior, but smaller
	// probes remain useful instead of permanently blacklisting the edge.
	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.72:
			probability *= 0.025
		case ratio > 0.48:
			probability *= 0.12
		case ratio > 0.24:
			probability *= 0.42
		case ratio > 0.10:
			probability *= 0.75
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 500_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 7 * float64(fee) / feeScale
			hopCost := 0.14
			failureCost := 0.12 * math.Min(
				float64(r.failedUses[edge.key]), 10,
			)
			newScore := item.score + riskCost + feeCost +
				hopCost + failureCost +
				r.sessionPenalty[edge.key] +
				extraPenalty[edge.key]

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 14)
	amounts = candidateAppendUnique(amounts, amt)

	// Prefer a compact geometric ladder. It covers large progress-making
	// shards and low-risk probes without running a full route search for
	// every possible part count.
	parts := []uint32{2, 3, 4, 6, 8, 10, 12, 16}
	for _, count := range parts {
		if count <= partsLeft {
			amounts = candidateAppendUnique(
				amounts, candidateCeilDiv(amt, count),
			)
		}
	}

	amounts = candidateAppendUnique(
		amounts, candidateCeilDiv(amt, partsLeft),
	)

	return amounts
}

func candidateRouteHash(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, hop := range rt.Hops {
		value := hop.ChannelID
		for i := 0; i < 8; i++ {
			hash ^= value & 0xff
			hash *= prime
			value >>= 8
		}
		for _, value := range hop.PubKeyBytes {
			hash ^= uint64(value)
			hash *= prime
		}
	}

	return hash
}

func candidatePenalizePath(
	rt *route.Route, penalties map[candidateEdgeKey]float64,
	amount float64) {

	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		penalties[key] += amount
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		extra := make(map[candidateEdgeKey]float64)

		// Generate several genuinely different path candidates for each
		// shard. This avoids repeatedly returning the same route after an
		// unattributed failure.
		for alternative := 0; alternative < 3; alternative++ {
			rt, logRisk, err := r.findRoute(shard, extra)
			if err != nil {
				break
			}

			probability := math.Exp(-logRisk)
			fee := rt.TotalAmount - shard
			progress := math.Log1p(
				float64(shard) /
					math.Max(float64(minimum), 1),
			)
			feePenalty := 5 * float64(fee) /
				math.Max(float64(shard), 1)
			hopPenalty := 0.015 * float64(len(rt.Hops))

			hash := candidateRouteHash(rt)
			historyPenalty := 1.35 *
				float64(r.routeFailures[hash])

			utility := math.Log(math.Max(probability, 1e-15)) +
				0.42*progress - feePenalty - hopPenalty -
				historyPenalty

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestUtility = utility
			}

			candidatePenalizePath(rt, extra, 0.85)
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.15
	if r.failedUses[key] != 0 {
		r.failedUses[key]--
	}
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.failedUses[key]++
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.10
	if r.failedUses[key] != 0 {
		r.failedUses[key]--
	}

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeRoute(
	keys []candidateEdgeKey, severe bool) {

	base := 0.75
	if severe {
		base = 1.5
	}

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		position := float64(i+1) / float64(len(keys))
		penalty := base * (0.75 + 0.5*position)
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 8,
		)
		r.failedUses[key]++
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()
	hash := candidateRouteHash(rt)

	if result.Failure == nil {
		delete(r.routeFailures, hash)

		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		balance := r.localBalances[first.chanID]
		if balance > amounts[0] {
			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	r.routeFailures[hash]++

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			r.penalizeRoute(keys, false)
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

			// The exact path should still be avoided while smaller probes
			// of the identified channel remain available.
			r.sessionPenalty[key] = math.Min(
				r.sessionPenalty[key]+0.35, 2,
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 30

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 15
			r.penalizeRoute(keys, false)
		}

		return nil
	}

	// An unknown failure source must not poison a persistent liquidity
	// belief. Strongly diversify the session path instead, including exact
	// route history so repeated unattributed failures cannot consume the
	// entire attempt budget on one route.
	r.penalizeRoute(keys, true)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Evidence remains useful in static scenarios, but becomes a soft hint
	// after background traffic has had time to move liquidity.
	const halfLifeMinutes = 18.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	b.conf = conf

	// Old bounds must not remain absolute in a moving network. The estimate is
	// retained and blended with the prior through the decayed confidence.
	if now.Sub(b.updatedAt) > 12*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(edge *candidateEdge) candidateLiquidityBelief {
	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{capacity: edge.capacity}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey], capacity,
		forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.86)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key], edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	// Under the bimodal model, a successful probe is evidence that this is
	// the funded direction, not merely that exactly the probe amount exists.
	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key], edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity failure strongly selects the depleted mode. Preserve any
	// proven lower bound, but otherwise place the estimate near zero.
	estimate := edge.capacity / 1000
	probeEstimate := amt / 24
	if estimate < 1 {
		estimate = 1
	}
	if probeEstimate < estimate {
		estimate = probeEstimate
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key], edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}
	b.estimate -= amt

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateFailureEvidence struct {
	amount lnwire.MilliSatoshi
	count  uint32
	at     time.Time
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]candidateFailureEvidence
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]candidateFailureEvidence),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				// InPolicy is the other node's policy for the directed
				// edge from OtherNode into node.
				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.002, math.Min(probability, 0.997))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode covers the small chance that even the depleted direction
	// can carry a tiny HTLC. The high mode models a funded direction with a
	// steep cliff near the channel capacity.
	lowMode := 0.47 * math.Exp(-ratio/0.018)
	highMode := 0.515 /
		(1 + math.Exp((ratio-0.90)/0.038))

	return candidateClampProbability(0.003 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.lowerOK != 0 && amt <= b.lowerOK {
		probability = math.Max(probability, 0.997)
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		probability = math.Min(probability, 0.002)
	}
	if b.upperFail != 0 && amt > b.lowerOK && amt < b.upperFail {
		span := float64(b.upperFail - b.lowerOK)
		fraction := float64(amt-b.lowerOK) / math.Max(span, 1)
		bounded := 0.002 + 0.995*math.Pow(1-fraction, 2.7)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9998
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.999
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())
	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	failure, failed := r.sessionFailed[edge.key]
	if failed && failure.amount > 0 {
		age := r.view.Now().Sub(failure.at).Minutes()
		if age < 0 {
			age = 0
		}

		// Session failures are strong but deliberately not absolute. This
		// avoids premature "no route" termination when a cut edge is the
		// only path and background traffic has since rebalanced it.
		freshness := math.Exp(-math.Ln2 * age / 4.0)
		ratio := float64(amt) / float64(failure.amount)

		var multiplier float64
		switch {
		case ratio >= 1:
			multiplier = 0.008
		case ratio >= 0.72:
			multiplier = 0.025
		case ratio >= 0.45:
			multiplier = 0.16
		case ratio >= 0.20:
			multiplier = 0.52
		default:
			multiplier = 0.84
		}

		if failure.count > 1 {
			multiplier = math.Pow(
				multiplier,
				math.Min(float64(failure.count), 3),
			)
		}

		effective := 1 - freshness*(1-multiplier)
		probability *= effective
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}
			if sending <= 0 {
				continue
			}

			riskCost := -math.Log(probability)
			feeCost := 5.5 * float64(fee) / feeScale
			hopCost := 0.14
			useCost := 0.055 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.sessionPenalty[edge.key]

			// Prefer channels with substantial capacity headroom even when
			// their raw bimodal probability is similar.
			headroom := float64(edge.capacity) /
				math.Max(float64(item.amount), 1)
			headroomCost := 0.0
			if headroom < 2 {
				headroomCost = 0.18 * (2 - headroom)
			}

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty + headroomCost

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 18)

	// Evaluate the completion-safe minimum first, then progressively larger
	// shards. Every candidate leaves enough part slots to finish the payment.
	amounts = candidateAppendUnique(amounts, minimum)
	for _, numerator := range []int64{
		5, 6, 8, 10, 12, 16, 24, 32,
	} {
		shard := minimum * lnwire.MilliSatoshi(numerator) / 4
		if shard > amt {
			shard = amt
		}
		amounts = candidateAppendUnique(amounts, shard)
	}
	amounts = candidateAppendUnique(amounts, amt)

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		fee := rt.TotalAmount - shard

		// Success dominates. Larger shards receive only a modest progress
		// reward, preventing them from displacing much safer MPP shards.
		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		feePenalty := 4.5 * float64(fee) /
			math.Max(float64(shard), 1)
		hopPenalty := 0.015 * float64(len(rt.Hops))

		utility := math.Log(math.Max(probability, 1e-15)) +
			0.20*progress - feePenalty - hopPenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	// A node reports failure of its outgoing channel. If source is hop i,
	// the failed directed edge is therefore i+1.
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}

	if failure, ok := r.sessionFailed[key]; ok &&
		amt >= failure.amount {

		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.15
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi,
	now time.Time) {

	failure := r.sessionFailed[key]
	if failure.amount == 0 || amt < failure.amount {
		failure.amount = amt
		failure.count = 1
	} else {
		failure.count++
	}
	failure.at = now
	r.sessionFailed[key] = failure

	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	// Penalize the observed edge enough to explore alternatives, while its
	// nonzero probability still permits a later or lower-amount retry.
	increment := 1.7 + 0.35*math.Min(float64(failure.count), 4)
	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+increment, 9,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failure, ok := r.sessionFailed[key]; ok {
		if failure.amount > amt {
			failure.amount -= amt
			r.sessionFailed[key] = failure
		} else {
			delete(r.sessionFailed, key)
		}
	}

	r.sessionPenalty[key] *= 0.10

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
	r.sessionPenalty[reverse] *= 0.25
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		position := float64(i+1) / float64(len(keys))
		penalty := 0.35 + 0.55*position
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 5,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		balance := r.localBalances[first.chanID]
		if balance > amounts[0] {
			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex], now,
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// These indicate a deterministic mismatch between the route
			// and the advertised policy. Do not retry this direction.
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// Unknown-source failures cannot safely update a particular liquidity
	// belief. Spread a temporary penalty across the attempted route instead.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 30
	candidateLabelsPerNode  = 7
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(
	amt lnwire.MilliSatoshi) bool {

	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(
	key candidateEdgeKey) candidateEdgeKey {

	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0

	case amt > capacity:
		return capacity

	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Evidence remains durable when the simulation clock does not move, while
	// background traffic progressively returns the belief toward its prior.
	const halfLifeMinutes = 24.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	age := now.Sub(b.updatedAt)
	b.conf = conf

	// Old bounds are no longer treated as physical limits after enough
	// simulated time for background traffic to reverse the channel.
	if age > 16*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.84)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi,
	now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.93)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi,
	now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity failure under a bimodal prior moves the estimate close to
	// the depleted mode. Smaller retries remain possible through the smooth
	// probability model rather than a permanent blacklist.
	estimate := amt / 20
	depletedMode := edge.capacity / 600
	if depletedMode < 1 {
		depletedMode = 1
	}
	if estimate > depletedMode {
		estimate = depletedMode
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi,
	now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}

	b.estimate -= amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(
	probability float64) float64 {

	return math.Max(0.005, math.Min(probability, 0.995))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode makes tiny probes likely to pass even on the depleted
	// side. The high mode represents channels whose funds sit almost wholly
	// in this direction and falls sharply near capacity.
	lowMode := 0.47 * math.Exp(-ratio/0.022)
	highMode := 0.505 /
		(1 + math.Exp((ratio-0.91)/0.042))

	return candidateClampProbability(0.005 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.005
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.03, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.6)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}
	if !edge.usable(amt) {
		return 0
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		probability := 0.9995
		if failedAt != 0 {
			ratio := float64(amt) / float64(failedAt)
			probability *= 0.08 +
				0.92*math.Pow(math.Max(1-ratio, 0), 1.4)
		}

		return candidateClampProbability(probability)
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())

	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		retryWeight := 0.08 +
			0.92*math.Pow(math.Max(1-ratio, 0), 1.45)
		probability *= retryWeight
	}

	return candidateClampProbability(probability)
}

type candidateSearchLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
	path   []*candidateEdge
	active bool
}

type candidateQueue []*candidateSearchLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].amount != q[j].amount {
		return q[i].amount < q[j].amount
	}

	return q[i].hops < q[j].hops
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateSearchLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func candidatePathContains(
	path []*candidateEdge, node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}

	return false
}

func candidateDominates(
	left, right *candidateSearchLabel) bool {

	return left.active &&
		left.amount <= right.amount &&
		left.score <= right.score+1e-12
}

func candidateLabelQuality(
	label *candidateSearchLabel,
	deliver lnwire.MilliSatoshi) float64 {

	amountCost := 0.04 * float64(label.amount) /
		math.Max(float64(deliver), 1)

	return label.score + amountCost
}

func candidateInsertLabel(
	labels map[route.Vertex][]*candidateSearchLabel,
	label *candidateSearchLabel,
	deliver lnwire.MilliSatoshi) bool {

	current := labels[label.node]
	for _, existing := range current {
		if candidateDominates(existing, label) {
			return false
		}
	}

	kept := current[:0]
	for _, existing := range current {
		if candidateDominates(label, existing) {
			existing.active = false
			continue
		}

		kept = append(kept, existing)
	}

	label.active = true
	kept = append(kept, label)

	if len(kept) > candidateLabelsPerNode {
		worst := 0
		worstQuality := candidateLabelQuality(kept[0], deliver)

		for i := 1; i < len(kept); i++ {
			quality := candidateLabelQuality(kept[i], deliver)
			if quality > worstQuality {
				worst = i
				worstQuality = quality
			}
		}

		removed := kept[worst]
		removed.active = false
		kept = append(kept[:worst], kept[worst+1:]...)

		if removed == label {
			labels[label.node] = kept
			return false
		}
	}

	labels[label.node] = kept
	return true
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	start := &candidateSearchLabel{
		node:   r.spec.Target,
		amount: deliver,
		active: true,
	}

	labels := map[route.Vertex][]*candidateSearchLabel{
		r.spec.Target: {start},
	}
	queue := &candidateQueue{start}
	heap.Init(queue)

	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateSearchLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item.path)
			if err != nil {
				return nil, 0, err
			}

			return rt, item.risk, nil
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			sending := item.amount
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}
			if !edge.usable(item.amount) || sending <= 0 {
				continue
			}

			riskCost := -math.Log(probability)
			feeCost := 5.5 * float64(fee) / feeScale
			hopCost := 0.13
			useCost := 0.07 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			next := &candidateSearchLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + riskCost + feeCost +
					hopCost + useCost +
					r.sessionPenalty[edge.key],
				risk: item.risk + riskCost,
				hops: item.hops + 1,
				path: path,
			}

			if !candidateInsertLabel(labels, next, deliver) {
				continue
			}

			heap.Push(queue, next)
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}
	if len(path) > candidateMaxRouteHops {
		return nil, errors.New("selected route is too long")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("selected route misses target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func (r *candidateRouter) shardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 28)
	amounts = candidateAppendUnique(amounts, amt)

	limit := partsLeft
	if limit > 20 {
		limit = 20
	}

	for parts := uint32(2); parts <= limit; parts++ {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts = candidateAppendUnique(amounts, minimum)

	// A slightly undersized probe can escape a learned liquidity cliff
	// without spending so many part slots that completion becomes unlikely.
	if partsLeft >= 3 {
		amounts = candidateAppendUnique(
			amounts, minimum*3/4,
		)
	}

	// Retry just below liquidity failures observed during this payment.
	for _, failedAt := range r.sessionFailed {
		for _, numerator := range []lnwire.MilliSatoshi{2, 1} {
			retry := failedAt * numerator / 3
			if retry > amt {
				continue
			}
			if retry < minimum/2 {
				continue
			}

			amounts = candidateAppendUnique(amounts, retry)
		}
	}

	sort.Slice(amounts, func(i, j int) bool {
		return amounts[i] > amounts[j]
	})

	return amounts
}

func (r *candidateRouter) markRouteUsed(
	rt *route.Route) {

	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) releaseRouteUse(
	key candidateEdgeKey) {

	if r.edgeUses[key] > 0 {
		r.edgeUses[key]--
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	shards := r.shardAmounts(amt, partsLeft)
	reference := candidateCeilDiv(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := math.Log(
			math.Max(float64(shard), 1) /
				math.Max(float64(reference), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 4.5 * float64(fee) /
			math.Max(float64(shard), 1)

		// Expected progress dominates fees, while route probability remains
		// the primary term. A small completion bonus avoids unnecessary MPP
		// fragmentation when the whole payment has a credible route.
		utility := math.Log(math.Max(probability, 1e-12)) +
			0.82*progress - feePenalty

		if shard == amt {
			utility += 0.12
		}

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.16
	r.releaseRouteUse(key)
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.65, 7,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.10
	r.releaseRouteUse(key)

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.55
		if i >= len(keys)/2 {
			penalty = 0.75
		}

		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 4.5,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil {
				continue
			}

			if edge.key.from != r.source {
				candidateRecordPass(
					edge, amounts[i], now,
				)
			}
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			if edge.key.from != r.source {
				candidateRecordFailure(
					edge, amounts[failIndex], now,
				)
			}
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// A failure attributed to the target proves every traversed channel,
	// though it does not identify an outgoing channel to blacklist.
	if failIndex == len(keys) {
		for _, key := range keys {
			r.releaseRouteUse(key)
		}

		return nil
	}

	// Unknown-source failures force route exploration without corrupting
	// persistent directional liquidity beliefs.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 56
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateBeliefKey struct {
	network string
	edge    candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateBeliefKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateBeliefKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Evidence decays quickly enough to tolerate background traffic while
	// remaining useful for consecutive payments in a batch.
	const halfLifeMinutes = 14.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{capacity: capacity}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{capacity: capacity}
	}

	b.conf = conf

	// Old bounds are treated as soft estimates because intervening payments
	// may have shifted liquidity in either direction.
	if now.Sub(b.updatedAt) > 7*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	network string, edge *candidateEdge) candidateLiquidityBelief {

	key := candidateBeliefKey{
		network: network,
		edge:    edge.key,
	}

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{capacity: edge.capacity}
	}

	return b
}

func candidateStorePair(
	network string, key candidateEdgeKey,
	forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	forwardKey := candidateBeliefKey{
		network: network,
		edge:    key,
	}
	candidateKnowledge.beliefs[forwardKey] = forward

	reverseEdge := candidateReverseKey(key)
	reverseKey := candidateBeliefKey{
		network: network,
		edge:    reverseEdge,
	}
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.84)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateBeliefKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateBeliefKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity miss is strong evidence for the depleted mode, but lower
	// amounts remain eligible for subsequent probing.
	estimate := amt / 20
	floor := edge.capacity / 1000
	if floor < 1 {
		floor = 1
	}
	if estimate > floor {
		estimate = floor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.99)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	network string, edge *candidateEdge,
	amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	key := candidateBeliefKey{
		network: network,
		edge:    edge.key,
	}
	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[key], edge.capacity, now,
	)

	if b.estimate < amt {
		b.estimate = edge.capacity * 9 / 10
		if b.estimate < amt {
			b.estimate = amt
		}
	}

	b.estimate -= amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.96)
	b.updatedAt = now
	candidateStorePair(network, edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view      routing.SimNetworkView
	networkID string
	source    route.Vertex
	spec      *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		networkID:      fmt.Sprintf("%T:%p", view, view),
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	return math.Max(0.003, math.Min(probability, 0.997))
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The first term models the nearly empty mode. The second models the
	// well-funded mode and retains a sharp cliff near channel capacity.
	lowMode := 0.475 * math.Exp(-ratio/0.022)
	highMode := 0.515 / (1 + math.Exp((ratio-0.90)/0.042))

	return candidateClampProbability(0.003 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.997
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.003
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.003 + 0.994*math.Pow(1-fraction, 2.8)
		probability = 0.72*bounded + 0.28*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(r.networkID, edge)
	conf := candidateBeliefConfidence(b, r.view.Now())
	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)
		switch {
		case ratio > 0.70:
			probability *= 0.025
		case ratio > 0.50:
			probability *= 0.12
		case ratio > 0.25:
			probability *= 0.48
		default:
			probability *= 0.88
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 2_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 5.5 * float64(fee) / feeScale
			hopCost := 0.075
			useCost := 0.13 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.sessionPenalty[edge.key]

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return (amt + d - 1) / d
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 12)

	// Balanced shards are tried first because they preserve enough part slots
	// to complete the remainder while minimizing liquidity pressure.
	amounts = candidateAppendUnique(amounts, minimum)
	amounts = candidateAppendUnique(
		amounts, minimum+minimum/5,
	)
	amounts = candidateAppendUnique(
		amounts, minimum+minimum/2,
	)
	amounts = candidateAppendUnique(
		amounts, minimum*2,
	)

	limit := partsLeft
	if limit > 8 {
		limit = 8
	}
	for parts := limit; parts >= 2; parts-- {
		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, parts),
		)
	}

	amounts = candidateAppendUnique(amounts, amt)

	return amounts
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		if shard < minimum || shard > amt {
			continue
		}

		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progress := float64(shard) / math.Max(float64(minimum), 1)
		fee := rt.TotalAmount - shard

		// Reliability dominates. Progress provides only a modest preference
		// for larger shards when their success probability is comparable.
		utility := math.Log(math.Max(probability, 1e-12)) +
			0.16*math.Log1p(progress) -
			4.0*float64(fee)/math.Max(float64(shard), 1)

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}

		if shard == minimum && probability >= 0.72 {
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.12
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+2.2, 9,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.10

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.95
		if i >= len(keys)/2 {
			penalty = 1.25
		}
		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 7,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(
				r.networkID, edge, amounts[i], now,
			)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				r.networkID, edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// Unknown-source failures trigger route-wide exploration without
	// contaminating persistent liquidity beliefs.
	r.penalizeUnknownRoute(keys)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateAttemptLimit   = 48
	candidateMaxRouteHops   = 20
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	return e.baseFeeMsat +
		(amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	updatedAt time.Time
}

var candidateKnowledge = struct {
	sync.RWMutex
	beliefs map[candidateEdgeKey]candidateLiquidityBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateLiquidityBelief),
}

func candidateReverseKey(key candidateEdgeKey) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func candidateClampAmount(
	amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	switch {
	case amt < 0:
		return 0
	case amt > capacity:
		return capacity
	default:
		return amt
	}
}

func candidateNormalizeBelief(
	b candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) candidateLiquidityBelief {

	b.capacity = capacity
	b.lowerOK = candidateClampAmount(b.lowerOK, capacity)
	b.estimate = candidateClampAmount(b.estimate, capacity)

	if b.upperFail < 0 || b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.upperFail != 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
	}
	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperFail != 0 && b.estimate >= b.upperFail {
		b.estimate = b.upperFail - 1
		if b.estimate < b.lowerOK {
			b.estimate = b.lowerOK
		}
	}

	b.conf = math.Max(0, math.Min(b.conf, 0.995))

	return b
}

func candidateBeliefConfidence(
	b candidateLiquidityBelief, now time.Time) float64 {

	if b.conf <= 0 || b.updatedAt.IsZero() {
		return 0
	}

	age := now.Sub(b.updatedAt).Minutes()
	if age < 0 {
		return 0
	}

	// Recent attempt feedback is valuable, but background payments can
	// invalidate directional evidence within a few virtual minutes.
	const halfLifeMinutes = 12.0

	conf := b.conf * math.Exp(-math.Ln2*age/halfLifeMinutes)
	if conf < 0.015 {
		return 0
	}

	return conf
}

func candidatePrepareObservation(
	b candidateLiquidityBelief, capacity lnwire.MilliSatoshi,
	now time.Time) candidateLiquidityBelief {

	if b.capacity != capacity {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	conf := candidateBeliefConfidence(b, now)
	if conf == 0 {
		return candidateLiquidityBelief{
			capacity: capacity,
		}
	}

	age := now.Sub(b.updatedAt)
	b.conf = conf

	// Aged bounds remain represented by the estimate, but cease to be
	// treated as exact observations.
	if age > 8*time.Minute {
		b.lowerOK = 0
		b.upperFail = 0
	}

	return candidateNormalizeBelief(b, capacity)
}

func candidateSnapshot(
	edge *candidateEdge) candidateLiquidityBelief {

	candidateKnowledge.RLock()
	b, ok := candidateKnowledge.beliefs[edge.key]
	candidateKnowledge.RUnlock()

	if !ok || b.capacity != edge.capacity {
		return candidateLiquidityBelief{
			capacity: edge.capacity,
		}
	}

	return b
}

func candidateStorePair(
	key candidateEdgeKey, forward candidateLiquidityBelief,
	capacity lnwire.MilliSatoshi) {

	forward = candidateNormalizeBelief(forward, capacity)
	candidateKnowledge.beliefs[key] = forward

	reverseKey := candidateReverseKey(key)
	reverse := candidatePrepareObservation(
		candidateKnowledge.beliefs[reverseKey],
		capacity, forward.updatedAt,
	)

	reverse.updatedAt = forward.updatedAt
	reverse.conf = math.Max(reverse.conf, forward.conf*0.82)
	reverse.estimate = capacity - forward.estimate

	if forward.upperFail != 0 {
		reverse.lowerOK = capacity - forward.upperFail + 1
	}
	if forward.lowerOK != 0 {
		reverse.upperFail = capacity - forward.lowerOK + 1
	}

	candidateKnowledge.beliefs[reverseKey] =
		candidateNormalizeBelief(reverse, capacity)
}

func candidateRecordPass(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	// Under the bimodal model, a successful non-trivial probe is strong
	// evidence for the high-liquidity mode.
	estimate := edge.capacity * 19 / 20
	if estimate < amt {
		estimate = amt
	}
	if b.estimate < estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.94)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordFailure(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt - 1
	}

	// A liquidity failure generally selects the depleted mode. Preserve
	// any proven lower bound, while placing the point estimate close to
	// zero rather than near half capacity.
	estimate := amt / 20
	capFloor := edge.capacity / 1000
	if capFloor < 1 {
		capFloor = 1
	}
	if estimate > capFloor {
		estimate = capFloor
	}
	if estimate < b.lowerOK {
		estimate = b.lowerOK
	}
	if b.estimate == 0 || estimate < b.estimate {
		b.estimate = estimate
	}

	b.conf = math.Max(b.conf, 0.985)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

func candidateRecordSettlement(
	edge *candidateEdge, amt lnwire.MilliSatoshi, now time.Time) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	b := candidatePrepareObservation(
		candidateKnowledge.beliefs[edge.key],
		edge.capacity, now,
	)

	estimate := b.estimate
	if estimate < amt {
		estimate = edge.capacity * 19 / 20
		if estimate < amt {
			estimate = amt
		}
	}

	b.estimate = estimate - amt
	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperFail > amt {
		b.upperFail -= amt
	} else {
		b.upperFail = 0
	}

	b.conf = math.Max(b.conf, 0.95)
	b.updatedAt = now
	candidateStorePair(edge.key, b, edge.capacity)
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionLower   map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionFailed  map[candidateEdgeKey]lnwire.MilliSatoshi
	sessionBlocked map[candidateEdgeKey]bool
	sessionPenalty map[candidateEdgeKey]float64
	edgeUses       map[candidateEdgeKey]uint32
	routeUses      map[string]uint32

	attempts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if view == nil {
		return nil, errors.New("network view is nil")
	}
	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}
	if spec.Amount <= 0 {
		return nil, errors.New("payment amount must be positive")
	}
	if source == spec.Target {
		return nil, errors.New("source is payment target")
	}

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionLower:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionFailed:  make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		sessionBlocked: make(map[candidateEdgeKey]bool),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		routeUses:      make(map[string]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(probability float64) float64 {
	switch {
	case probability < 0.005:
		return 0.005
	case probability > 0.995:
		return 0.995
	default:
		return probability
	}
}

func candidatePriorProbability(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)

	// The low mode makes very small probes plausible even when the
	// direction is depleted. The high mode stays nearly flat until the
	// channel-capacity cliff.
	lowMode := 0.47 * math.Exp(-ratio/0.018)
	highMode := 0.51 /
		(1 + math.Exp((ratio-0.91)/0.042))

	return candidateClampProbability(0.005 + lowMode + highMode)
}

func candidateLearnedProbability(
	b candidateLiquidityBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		return 0.005
	}
	if b.estimate == 0 {
		return candidatePriorProbability(amt, capacity)
	}

	width := math.Max(float64(capacity)*0.025, 1)
	position := (float64(amt) - float64(b.estimate)) / width
	probability := 1 / (1 + math.Exp(position))

	if b.upperFail != 0 {
		lower := float64(b.lowerOK)
		upper := float64(b.upperFail)
		fraction := (float64(amt) - lower) /
			math.Max(upper-lower, 1)
		fraction = math.Max(0, math.Min(fraction, 1))

		bounded := 0.005 + 0.99*math.Pow(1-fraction, 2.8)
		probability = 0.75*bounded + 0.25*probability
	}

	return candidateClampProbability(probability)
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge, amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 0.9995
	}

	failedAt := r.sessionFailed[edge.key]
	if failedAt != 0 && amt >= failedAt {
		return 0
	}
	if lower := r.sessionLower[edge.key]; lower >= amt {
		return 0.998
	}

	prior := candidatePriorProbability(amt, edge.capacity)
	if prior == 0 {
		return 0
	}

	b := candidateSnapshot(edge)
	conf := candidateBeliefConfidence(b, r.view.Now())
	probability := prior
	if conf != 0 {
		learned := candidateLearnedProbability(
			b, amt, edge.capacity,
		)
		probability = conf*learned + (1-conf)*prior
	}

	if failedAt != 0 {
		ratio := float64(amt) / float64(failedAt)

		// Do not blacklist the channel at all lower amounts. Require a
		// meaningful reduction before retrying, then gradually restore
		// the bimodal prior for genuinely small probes.
		switch {
		case ratio > 0.72:
			probability *= 0.02
		case ratio > 0.50:
			probability *= 0.10
		case ratio > 0.30:
			probability *= 0.32
		case ratio > 0.12:
			probability *= 0.68
		default:
			probability *= 0.92
		}
	}

	return candidateClampProbability(probability)
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   uint16
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = deliver

	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	sourceRisk := 0.0
	feeScale := math.Max(float64(deliver), 1_000_000)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)

		score, ok := bestScore[item.node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if required[item.node] != item.amount {
			continue
		}
		if item.node == r.source {
			sourceRisk = item.risk
			break
		}
		if item.hops >= candidateMaxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(item.amount) {
				continue
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				if fee < 0 ||
					item.amount >
						lnwire.MilliSatoshi(math.MaxInt64)-fee {

					continue
				}
				sending += fee
			}

			riskCost := -math.Log(probability)
			feeCost := 5.5 * float64(fee) / feeScale
			hopCost := 0.075
			useCost := 0.16 * math.Min(
				float64(r.edgeUses[edge.key]), 10,
			)
			penalty := r.sessionPenalty[edge.key]

			// Prefer channels with capacity headroom when otherwise
			// similarly probable. This also breaks ties away from paths
			// whose advertised capacity barely fits the shard.
			headroom := float64(item.amount) /
				math.Max(float64(edge.capacity), 1)
			capacityCost := 0.045 * headroom * headroom

			newScore := item.score + riskCost + feeCost +
				hopCost + useCost + penalty + capacityCost

			oldScore, exists := bestScore[edge.key.from]
			oldAmount := required[edge.key.from]
			if exists &&
				(newScore > oldScore+1e-12 ||
					(math.Abs(newScore-oldScore) <= 1e-12 &&
						sending >= oldAmount)) {

				continue
			}

			bestScore[edge.key.from] = newScore
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + riskCost,
				hops:   item.hops + 1,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		if len(path) > candidateMaxRouteHops {
			return nil, errors.New("selected route is too long")
		}

		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		fee := outgoing.fee(amounts[i+1])
		if fee < 0 ||
			amounts[i+1] >
				lnwire.MilliSatoshi(math.MaxInt64)-fee {

			return nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(
	amt lnwire.MilliSatoshi, divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return amt/d + lnwire.MilliSatoshi(boolToUint64(amt%d != 0))
}

func boolToUint64(value bool) uint64 {
	if value {
		return 1
	}

	return 0
}

func candidateAppendUnique(
	amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateShardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 12)
	divisors := []uint32{1, 2, 3, 4, 6, 8, 12, 16}

	for _, divisor := range divisors {
		if divisor > partsLeft {
			continue
		}

		amounts = candidateAppendUnique(
			amounts, candidateCeilDiv(amt, divisor),
		)
	}

	amounts = candidateAppendUnique(
		amounts, candidateCeilDiv(amt, partsLeft),
	)

	return amounts
}

func candidateRouteID(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	id := ""
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		id += fmt.Sprintf(
			"%x:%d:%x;", from[:], hop.ChannelID,
			hop.PubKeyBytes[:],
		)
		from = hop.PubKeyBytes
	}

	return id
}

func (r *candidateRouter) markRouteUsed(rt *route.Route) {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		r.edgeUses[key]++
		from = hop.PubKeyBytes
	}

	r.routeUses[candidateRouteID(rt)]++
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)
	shards := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		progressUnits := float64(shard) /
			math.Max(float64(minimum), 1)
		fee := rt.TotalAmount - shard
		feePenalty := 4.5 * float64(fee) /
			math.Max(float64(shard), 1)
		hopPenalty := 0.012 * float64(len(rt.Hops))

		routeReuse := float64(r.routeUses[candidateRouteID(rt)])
		reusePenalty := 0.22 * math.Min(routeReuse, 8)

		// Expected progress dominates the choice. This avoids burning many
		// attempts on tiny shards while still splitting amounts whose full
		// route probability is poor.
		utility := math.Log(math.Max(probability, 1e-12)) +
			0.88*math.Log(math.Max(progressUnits, 1)) -
			feePenalty - hopPenalty - reusePenalty

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	r.markRouteUsed(bestRoute)

	return bestRoute, nil
}

func (r *candidateRouter) routeData(
	rt *route.Route) ([]candidateEdgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func candidateFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordSessionPass(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	if amt > r.sessionLower[key] {
		r.sessionLower[key] = amt
	}
	if failed := r.sessionFailed[key]; failed != 0 && amt >= failed {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.12
}

func (r *candidateRouter) recordSessionFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	failed := r.sessionFailed[key]
	if failed == 0 || amt < failed {
		r.sessionFailed[key] = amt
	}
	if r.sessionLower[key] >= amt {
		r.sessionLower[key] = amt - 1
	}

	r.sessionPenalty[key] = math.Min(
		r.sessionPenalty[key]+1.75, 8,
	)
}

func (r *candidateRouter) recordSessionSettlement(
	key candidateEdgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	if lower := r.sessionLower[key]; lower > amt {
		r.sessionLower[key] = lower - amt
	} else {
		delete(r.sessionLower, key)
	}

	if failed := r.sessionFailed[key]; failed > amt {
		r.sessionFailed[key] = failed - amt
	} else {
		delete(r.sessionFailed, key)
	}

	r.sessionPenalty[key] *= 0.08

	reverse := candidateReverseKey(key)
	reverseLower := r.sessionLower[reverse] + amt
	if reverseLower > capacity {
		reverseLower = capacity
	}
	r.sessionLower[reverse] = reverseLower
}

func (r *candidateRouter) penalizeUnknownRoute(
	keys []candidateEdgeKey) {

	for i, key := range keys {
		if key.from == r.source {
			continue
		}

		penalty := 0.95
		if i >= len(keys)/2 {
			penalty = 1.20
		}

		r.sessionPenalty[key] = math.Min(
			r.sessionPenalty[key]+penalty, 7,
		)
	}
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("reported route is nil")
	}

	keys, amounts := r.routeData(rt)
	if len(keys) == 0 {
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, key := range keys {
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			candidateRecordSettlement(edge, amounts[i], now)
			r.recordSessionSettlement(
				key, amounts[i], edge.capacity,
			)
		}

		first := keys[0]
		if balance := r.localBalances[first.chanID];
			balance > amounts[0] {

			r.localBalances[first.chanID] =
				balance - amounts[0]
		} else {
			r.localBalances[first.chanID] = 0
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(keys) {
			prefixEnd = len(keys)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := r.edges[keys[i]]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordPass(edge, amounts[i], now)
			r.recordSessionPass(keys[i], amounts[i])
		}
	}

	code := result.Failure.Code()

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		edge := r.edges[key]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, amounts[failIndex], now,
			)
			r.recordSessionFailure(
				key, amounts[failIndex],
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 20

		default:
			r.sessionBlocked[key] = true
			r.sessionPenalty[key] = 12
		}

		return nil
	}

	// Failures without a usable source must trigger substantial route
	// exploration, but must not poison persistent channel beliefs.
	r.penalizeUnknownRoute(keys)

	return nil
}
